var textForPages =["\u041a\u0438\u0442\u0430\u0439\u0441\u043a\u0438\u0435 \u043c\u0435\u0442\u0430\u043b\u043b\u0443\u0440\u0433\u0438\u0447\u0435\u0441\u043a\u0438\u0435 \u000d\u000a\u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438\u000d\u000a\u0412\u044b\u043f\u0443\u0441\u043a #11\u000d\u000a\u0410\u043d\u0430\u043b\u0438\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0439\u2028\u000d\u000a\u0434\u0430\u0439\u0434\u0436\u0435\u0441\u0442 2026","\u041e\u0433\u043b\u0430\u0432\u043b\u0435\u043d\u0438\u0435\u000d\u000a\u0412\u0432\u0435\u0434\u0435\u043d\u0438\u0435 3\u000d\u000aNorth Copper Industry 4\u000d\u000aHunan Nonferrous Metals Holding Group 5\u000d\u000aTongling Nonferrous Metals Group 7\u000d\u000aTsingshan Holding Group Co., Ltd. 8\u000d\u000aJinchuan Group Co., Ltd. 10\u000d\u000aJiangxi Copper Corporation Limited 12\u000d\u000aChina Minmetals Corporation 14\u000d\u000a\u0412\u044b\u0432\u043e\u0434\u044b 16\u000d\u000a2/17","\u0412\u0432\u0435\u0434\u0435\u043d\u0438\u0435\u000d\u000a3/17\u000d\u000a\u041a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0438\u0435 \u043c\u0435\u0442\u0430\u043b\u043b\u0443\u0440\u0433\u0438\u0447\u0435\u0441\u043a\u0438\u0435 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438 \u041a\u041d\u0420\u000d\u000aJinchuan Group Co.\u000d\u000aHunan Nonferrous\u2028\u000d\u000aMetals Holding Group\u000d\u000aJiangxi Copper\u2028\u000d\u000aCorporation\u000d\u000aTsingshan Holding\u2028\u000d\u000aGroup Co.\u000d\u000aChina Minmetals\u2028\u000d\u000aCorporation\u000d\u000aNorth Copper Industry\u000d\u000a\u0428\u0442\u0430\u0431-\u043a\u0432\u0430\u0440\u0442\u0438\u0440\u0430: \u0426\u0437\u0438\u043d\u044c\u0447\u0430\u043d, \u043f\u0440\u043e\u0432\u0438\u043d\u0446\u0438\u044f \u0413\u0430\u043d\u044c\u0441\u0443.\u000a\u000d\u000a\u0413\u043e\u0441\u0443\u0434\u0430\u0440\u0441\u0442\u0432\u0435\u043d\u043d\u0430\u044f \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u041a\u0438\u0442\u0430\u044f.\u000a\u000d\u000a\u0417\u0430\u043d\u0438\u043c\u0430\u0435\u0442 2-\u0435 \u043c\u0435\u0441\u0442\u043e \u0432 \u043c\u0438\u0440\u0435 \u043f\u043e \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0443 \u000d\u000a\u043d\u0438\u043a\u0435\u043b\u044f, 4-\u0435 \u2014 \u043f\u043e \u043a\u043e\u0431\u0430\u043b\u044c\u0442\u0443, 1-\u0435 \u043c\u0435\u0441\u0442\u043e \u0432 \u0410\u0437\u0438\u0438 \u000d\u000a\u043f\u043e \u043c\u0435\u0442\u0430\u043b\u043b\u0430\u043c \u043f\u043b\u0430\u0442\u0438\u043d\u043e\u0432\u043e\u0439 \u0433\u0440\u0443\u043f\u043f\u044b \u0438 3-\u0435 \u043c\u0435\u0441\u0442\u043e \u000d\u000a\u0432 \u041a\u0438\u0442\u0430\u0435 \u043f\u043e \u043c\u0435\u0434\u0438.\u000d\u000a\u000d\u000a\u0421\u043e\u0437\u0434\u0430\u043d\u0430 \u0432 1958 \u0433\u043e\u0434\u0443.\u000a\u000d\u000a\u0412\u043b\u0430\u0434\u0435\u0435\u0442 \u043a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0438\u043c \u0432 \u041a\u0438\u0442\u0430\u0435 \u0438 \u0442\u0440\u0435\u0442\u044c\u0438\u043c \u000d\u000a\u0432 \u043c\u0438\u0440\u0435 \u043c\u0435\u0434\u043d\u043e-\u043d\u0438\u043a\u0435\u043b\u0435\u0432\u044b\u043c \u043c\u0435\u0441\u0442\u043e\u0440\u043e\u0436\u0434\u0435\u043d\u0438\u0435\u043c \u000d\u000a\u0426\u0437\u0438\u043d\u044c\u0447\u0443\u0430\u043d\u044c.\u000a\u000d\u000a\u0412\u044b\u0440\u0443\u0447\u043a\u0430 \u0437\u0430 2024 \u0433\u043e\u0434 \u2014 $58,8 \u043c\u043b\u0440\u0434.\u000d\u000a\u0428\u0442\u0430\u0431-\u043a\u0432\u0430\u0440\u0442\u0438\u0440\u0430: \u0422\u0443\u043d\u043b\u0438\u043d, \u043f\u0440\u043e\u0432\u0438\u043d\u0446\u0438\u044f \u0410\u043d\u044c\u0445\u043e\u0439.\u000a\u000d\u000a\u0412\u0445\u043e\u0434\u0438\u0442 \u0432 Fortune Global 500 \u0441\u0435\u043c\u044c \u043b\u0435\u0442 \u043f\u043e\u0434\u0440\u044f\u0434.\u000a\u000d\u000a\u0422\u0443\u043d\u043b\u0438\u043d \u0441\u0447\u0438\u0442\u0430\u0435\u0442\u0441\u044f \u0431\u0440\u043e\u043d\u0437\u043e\u0432\u043e\u0439 \u0441\u0442\u043e\u043b\u0438\u0446\u0435\u0439 \u041a\u0438\u0442\u0430\u044f, \u000d\u000a\u043f\u0435\u0440\u0432\u044b\u0439 \u0438\u043d\u0434\u0443\u0441\u0442\u0440\u0438\u0430\u043b\u044c\u043d\u044b\u0439 \u043c\u0435\u0434\u043d\u044b\u0439 \u043a\u043e\u043c\u043f\u043b\u0435\u043a\u0441 \u000d\u000a\u0431\u044b\u043b \u0441\u043e\u0437\u0434\u0430\u043d \u0432 1949 \u0433\u043e\u0434\u0443, \u0438\u0437 \u043d\u0435\u0433\u043e \u0432\u044b\u0440\u043e\u0441\u043b\u043e \u000d\u000a\u043f\u0440\u0435\u0434\u043f\u0440\u0438\u044f\u0442\u0438\u0435 Tongling.\u000a\u000d\u000a\u041a\u0430\u0442\u043e\u0434\u043d\u0430\u044f \u043c\u0435\u0434\u044c \u043c\u0430\u0440\u043a\u0438 Tongguan \u000d\u000a\u0437\u0430\u0440\u0435\u0433\u0438\u0441\u0442\u0440\u0438\u0440\u043e\u0432\u0430\u043d\u0430 \u043d\u0430 LME, \u0441\u0435\u0440\u0435\u0431\u0440\u044f\u043d\u044b\u0435 \u000d\u000a\u0441\u043b\u0438\u0442\u043a\u0438 \u0442\u043e\u0439 \u0436\u0435 \u043c\u0430\u0440\u043a\u0438 \u2014 \u0432 LBMA.\u000a\u000d\u000a\u0412\u044b\u0440\u0443\u0447\u043a\u0430 \u0437\u0430 2024 \u0433\u043e\u0434 \u2014 $20,3 \u043c\u043b\u0440\u0434.\u000d\u000a\u0428\u0442\u0430\u0431-\u043a\u0432\u0430\u0440\u0442\u0438\u0440\u0430: \u0427\u0430\u043d\u0448\u0430, \u043f\u0440\u043e\u0432\u0438\u043d\u0446\u0438\u044f \u0425\u0443\u043d\u0430\u043d\u044c.\u000a\u000d\u000a\u0412\u0445\u043e\u0434\u0438\u0442 \u043f\u044f\u0442\u0435\u0440\u043a\u0443 \u043a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0438\u0445 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u0442\u0435\u043b\u0435\u0439 \u000d\u000a\u0446\u0432\u0435\u0442\u043d\u044b\u0445 \u043c\u0435\u0442\u0430\u043b\u043b\u043e\u0432 \u041a\u041d\u0420.\u000a\u000d\u000a\u041f\u0440\u0438\u043d\u0430\u0434\u043b\u0435\u0436\u0438\u0442 China Minmetals.\u000a\u000d\u000a\u0421\u043e\u0437\u0434\u0430\u043d\u0430 \u0432 2004 \u0433\u043e\u0434\u0443 \u043f\u0440\u0430\u0432\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u043e\u043c \u000d\u000a\u043f\u0440\u043e\u0432\u0438\u043d\u0446\u0438\u0438 \u0425\u0443\u043d\u0430\u043d\u044c.\u000a\u000d\u000a\u0423\u043f\u0440\u0430\u0432\u043b\u044f\u0435\u0442 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u043c\u0438 \u000d\u000a\u043f\u0440\u0435\u0434\u043f\u0440\u0438\u044f\u0442\u0438\u044f\u043c\u0438 China Minmetals.\u000a\u000d\u000a\u0412\u044b\u0440\u0443\u0447\u043a\u0430 \u0437\u0430 2024 \u0433\u043e\u0434 \u2014 $5 5,5 \u043c\u043b\u0440\u0434.\u000d\u000a\u0428\u0442\u0430\u0431-\u043a\u0432\u0430\u0440\u0442\u0438\u0440\u0430: \u041d\u0430\u043d\u044c\u0447\u0430\u043d, \u043f\u0440\u043e\u0432\u0438\u043d\u0446\u0438\u044f \u0426\u0437\u044f\u043d\u0441\u0438.\u000a\u000d\u000a\u0421\u0430\u043c\u044b\u0439 \u043a\u0440\u0443\u043f\u043d\u044b\u0439 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u0442\u0435\u043b\u044c \u043c\u0435\u0434\u0438 \u000d\u000a\u0432 \u041a\u0438\u0442\u0430\u0435, \u0432\u043b\u0430\u0434\u0435\u0435\u0442 \u043a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0438\u043c \u0432 \u0410\u0437\u0438\u0438 \u000d\u000a\u043e\u0442\u043a\u0440\u044b\u0442\u044b\u043c \u043c\u0435\u0434\u043d\u044b\u043c \u0440\u0443\u0434\u043d\u0438\u043a\u043e\u043c \u0414\u044d\u0441\u0438\u043d.\u000a\u000d\u000a\u041e\u0441\u043d\u043e\u0432\u0430\u043d\u0430 \u0432 1979 \u0433\u043e\u0434\u0443.\u000a\u000d\u000a\u0417\u0430\u043d\u0438\u043c\u0430\u0435\u0442 398-\u0435 \u043c\u0435\u0441\u0442\u043e \u0432 \u0441\u043f\u0438\u0441\u043a\u0435 500 \u0441\u0430\u043c\u044b\u0445 \u000d\u000a\u0446\u0435\u043d\u043d\u044b\u0445 \u0431\u0440\u0435\u043d\u0434\u043e\u0432 \u043c\u0438\u0440\u0430.\u000a\u000d\u000a\u0412\u044b\u0440\u0443\u0447\u043a\u0430 \u0437\u0430 2024 \u0433\u043e\u0434 \u2014 $72,5 \u043c\u043b\u0440\u0434.\u000d\u000a\u0428\u0442\u0430\u0431-\u043a\u0432\u0430\u0440\u0442\u0438\u0440\u0430: \u0412\u044d\u043d\u044c\u0447\u0436\u043e\u0443, \u043f\u0440\u043e\u0432\u0438\u043d\u0446\u0438\u044f \u000d\u000a\u0427\u0436\u044d\u0446\u0437\u044f\u043d.\u000a\u000d\u000a\u041a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0438\u0439 \u0447\u0430\u0441\u0442\u043d\u044b\u0439 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u0442\u0435\u043b\u044c \u000d\u000a\u043d\u0435\u0440\u0436\u0430\u0432\u0435\u044e\u0449\u0435\u0439 \u0441\u0442\u0430\u043b\u0438 \u0438 \u043c\u0430\u0442\u0435\u0440\u0438\u0430\u043b\u043e\u0432 \u000d\u000a\u0434\u043b\u044f \u043d\u043e\u0432\u043e\u0439 \u044d\u043d\u0435\u0440\u0433\u0435\u0442\u0438\u043a\u0438 \u043d\u0430 \u043e\u0441\u043d\u043e\u0432\u0435 \u000d\u000a\u043d\u0438\u043a\u0435\u043b\u044f \u0432 \u041a\u0438\u0442\u0430\u0435.\u000d\u000a\u000d\u000a\u0421\u043e\u0437\u0434\u0430\u043d\u0430 \u0432 2003 \u0433\u043e\u0434\u0443.\u000a\u000d\u000a\u041a\u043e\u043d\u0442\u0440\u043e\u043b\u0438\u0440\u0443\u0435\u0442 \u043e\u043a\u043e\u043b\u043e 30% \u043c\u043e\u0449\u043d\u043e\u0441\u0442\u0435\u0439 \u000d\u000a\u043f\u043e \u0434\u043e\u0431\u044b\u0447\u0435 \u043d\u0438\u043a\u0435\u043b\u044f \u0432 \u0418\u043d\u0434\u043e\u043d\u0435\u0437\u0438\u0438.\u000a\u000d\u000a\u0412\u044b\u0440\u0443\u0447\u043a\u0430 \u0437\u0430 2024 \u0433\u043e\u0434 \u2014 $56,6 \u043c\u043b\u0440\u0434.\u000d\u000a\u0428\u0442\u0430\u0431-\u043a\u0432\u0430\u0440\u0442\u0438\u0440\u0430: \u041f\u0435\u043a\u0438\u043d.\u000a\u000d\u000a\u041a\u043b\u044e\u0447\u0435\u0432\u043e\u0435 \u0433\u043e\u0441\u0443\u0434\u0430\u0440\u0441\u0442\u0432\u0435\u043d\u043d\u043e\u0435 \u043f\u0440\u0435\u0434\u043f\u0440\u0438\u044f\u0442\u0438\u0435, \u000d\u000a\u043d\u0430\u0445\u043e\u0434\u044f\u0449\u0435\u0435\u0441\u044f \u043f\u043e\u0434 \u043f\u0440\u044f\u043c\u044b\u043c \u0443\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u0435\u043c \u000d\u000a\u0446\u0435\u043d\u0442\u0440\u0430\u043b\u044c\u043d\u043e\u0433\u043e \u043f\u0440\u0430\u0432\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u0430 \u000d\u000a\u0438 \u0441\u043f\u0435\u0446\u0438\u0430\u043b\u0438\u0437\u0438\u0440\u0443\u044e\u0449\u0435\u0435\u0441\u044f \u043d\u0430 \u0434\u043e\u0431\u044b\u0447\u0435 \u000d\u000a\u043c\u0435\u0442\u0430\u043b\u043b\u043e\u0432 \u0438 \u043c\u0438\u043d\u0435\u0440\u0430\u043b\u044c\u043d\u043e\u0433\u043e \u0441\u044b\u0440\u044c\u044f.\u000d\u000a\u000d\u000a\u041e\u0441\u043d\u043e\u0432\u0430\u043d\u0430 \u0432 1950 \u0433\u043e\u0434\u0443.\u000a\u000d\u000a\u0417\u0430\u043d\u0438\u043c\u0430\u0435\u0442 190-\u0435 \u043c\u0435\u0441\u0442\u043e \u0432 \u0441\u043f\u0438\u0441\u043a\u0435 500 \u000d\u000a\u0441\u0430\u043c\u044b\u0445 \u0446\u0435\u043d\u043d\u044b\u0445 \u0431\u0440\u0435\u043d\u0434\u043e\u0432 \u043c\u0438\u0440\u0430.\u000a\u000d\u000a\u0412\u044b\u0440\u0443\u0447\u043a\u0430 \u0437\u0430 2024 \u0433\u043e\u0434 \u2014 $116 \u043c\u043b\u0440\u0434.\u000d\u000a\u0428\u0442\u0430\u0431-\u043a\u0432\u0430\u0440\u0442\u0438\u0440\u0430: \u042e\u043d\u044c\u0447\u044d\u043d, \u043f\u0440\u043e\u0432\u0438\u043d\u0446\u0438\u044f \u000d\u000a\u0428\u0430\u043d\u044c\u0441\u0438.\u000a\u000d\u000a\u041a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0438\u0439 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u0442\u0435\u043b\u044c \u043c\u0435\u0434\u0438 \u000d\u000a\u0432 \u0441\u0435\u0432\u0435\u0440\u043d\u043e\u043c \u041a\u0438\u0442\u0430\u0435.\u000a\u000d\u000a\u0414\u0435\u0439\u0441\u0442\u0432\u0443\u0435\u0442 \u0441 1996 \u0433\u043e\u0434\u0430.\u000a\u000d\u000a\u0412\u043b\u0430\u0434\u0435\u0435\u0442 \u0440\u0443\u0434\u043d\u0438\u043a\u043e\u043c \u0422\u0443\u043d\u043a\u0443\u0430\u043d\u044a\u044e\u0439 \u2014 \u000d\u000a\u043a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0435\u0439 \u0432 \u0410\u0437\u0438\u0438 \u043f\u043e\u0434\u0437\u0435\u043c\u043d\u043e\u0439 \u0448\u0430\u0445\u0442\u043e\u0439 \u000d\u000a\u043f\u043e \u0434\u043e\u0431\u044b\u0447\u0435 \u043d\u0435\u0443\u0433\u043e\u043b\u044c\u043d\u044b\u0445 \u0440\u0435\u0441\u0443\u0440\u0441\u043e\u0432.\u000a\u000d\u000a\u0412\u044b\u0440\u0443\u0447\u043a\u0430 \u0437\u0430 2024 \u0433\u043e\u0434 \u2014 $3,35 \u043c\u043b\u0440\u0434.\u000d\u000aTongling Nonferrous\u2028\u000d\u000aMetals Group\u000d\u000a\u0412\u044b\u0440\u0443\u0447\u043a\u0430 \u043a\u0438\u0442\u0430\u0439\u0441\u043a\u0438\u0445\u2028\u000d\u000a\u043c\u0435\u0442\u0430\u043b\u043b\u0443\u0440\u0433\u043e\u0432 \u0432 2024 \u0433\u043e\u0434\u0443\u000d\u000a$ \u043c\u043b\u0440\u0434\u000d\u000a116\u000d\u000a72,5\u000d\u000a58,8\u000d\u000a56,6\u000d\u000a20,3\u000d\u000a5,5\u000d\u000a3,35\u000d\u000aChina Minmetals Corporation\u000d\u000aJiangxi Copper Corporation\u000d\u000aJinchuan Group Co.\u000d\u000aTsingshan Holding Group Co.\u000d\u000aTongling Nonferrous Metals Group\u000d\u000aHunan Nonferrous Metals Holding Group\u000d\u000aNorth Copper Industry","4/17\u000d\u000aNorth Copper Industry\u000d\u000a(\u5317\u65b9\u94dc\u4e1a\u80a1\u4efd\u6709\u9650\u516c\u53f8)\u000d\u000a\u0428\u0442\u0430\u0431-\u043a\u0432\u0430\u0440\u0442\u0438\u0440\u0430\u000d\u000a\u042e\u043d\u044c\u0447\u044d\u043d, \u043f\u0440\u043e\u0432\u0438\u043d\u0446\u0438\u044f \u0428\u0430\u043d\u044c\u0441\u0438\u000d\u000a\u041a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0438\u0439 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u0442\u0435\u043b\u044c \u043c\u0435\u0434\u0438 \u0432 \u0441\u0435\u0432\u0435\u0440\u043d\u043e\u043c \u041a\u0438\u0442\u0430\u0435. \u041f\u043e\u043c\u0438\u043c\u043e \u000d\u000a\u043a\u0430\u0442\u043e\u0434\u043d\u043e\u0439 \u043c\u0435\u0434\u0438 \u0432\u044b\u043f\u0443\u0441\u043a\u0430\u0435\u0442 \u0437\u043e\u043b\u043e\u0442\u043e \u0438 \u0441\u0435\u0440\u0435\u0431\u0440\u043e \u0432 \u0441\u043b\u0438\u0442\u043a\u0430\u0445, \u000d\u000a\u0433\u0443\u0431\u0447\u0430\u0442\u043e\u0435 \u0437\u043e\u043b\u043e\u0442\u043e, \u0433\u0443\u0431\u0447\u0430\u0442\u044b\u0439 \u043f\u0430\u043b\u043b\u0430\u0434\u0438\u0439, \u0441\u0435\u0440\u043d\u0443\u044e \u043a\u0438\u0441\u043b\u043e\u0442\u0443.\u000a\u000d\u000a\u0421\u0440\u0435\u0434\u0438 16 \u043a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0438\u0445 \u043c\u0435\u0434\u0435\u0434\u043e\u0431\u044b\u0432\u0430\u044e\u0449\u0438\u0445 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0439 \u041a\u0438\u0442\u0430\u044f \u000d\u000aNorth Copper \u0437\u0430\u043d\u0438\u043c\u0430\u0435\u0442 11-\u0435 \u043c\u0435\u0441\u0442\u043e \u043f\u043e \u0432\u044b\u0440\u0443\u0447\u043a\u0435 \u0438 9-\u0435 \u043c\u0435\u0441\u0442\u043e \u000d\u000a\u043f\u043e \u043f\u0440\u0438\u0431\u044b\u043b\u0438.\u000d\u000aNorth Copper Industry \u0434\u0435\u0439\u0441\u0442\u0432\u0443\u0435\u0442 \u0441 1996 \u0433\u043e\u0434\u0430. \u0420\u0430\u043d\u0435\u0435 \u043d\u043e\u0441\u0438\u043b\u0430 \u000d\u000a\u043d\u0430\u0437\u0432\u0430\u043d\u0438\u0435 Nanfeng Chemical \u0438 \u0437\u0430\u043d\u0438\u043c\u0430\u043b\u0430\u0441\u044c \u0445\u0438\u043c\u0438\u0447\u0435\u0441\u043a\u0438\u043c \u000d\u000a\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u043e\u043c.\u000a\u000d\u000a\u0413\u043e\u0441\u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u000d\u000a\u0432\u044b\u043a\u0443\u043f\u0438\u043b\u0430 \u0435\u0435 \u0434\u043b\u044f \u043a\u043e\u043d\u0441\u043e\u043b\u0438\u0434\u0430\u0446\u0438\u0438 \u043c\u0435\u0434\u043d\u044b\u0445 \u0430\u043a\u0442\u0438\u0432\u043e\u0432 \u0438 \u0432 2021 \u0433\u043e\u0434\u0443 \u000d\u000a\u043f\u0440\u043e\u0432\u0435\u043b\u0430 \u0440\u0435\u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u0438\u0437\u0430\u0446\u0438\u044e. \u0414\u043e\u0447\u043a\u0435 \u0431\u044b\u043b\u0438 \u043f\u0435\u0440\u0435\u0434\u0430\u043d\u044b \u0440\u0443\u0434\u043d\u0438\u043a \u000d\u000a\u0422\u0443\u043d\u043a\u0443\u0430\u043d\u044a\u044e\u0439 \u0438 \u0434\u0432\u0430 \u043c\u0435\u0434\u0435\u043f\u043b\u0430\u0432\u0438\u043b\u044c\u043d\u044b\u0445 \u0437\u0430\u0432\u043e\u0434\u0430.\u000d\u000aZhongtiaoshan Nonferrous Metals Group Co. Ltd. \u000d\u000a\u0420\u0443\u0434\u043d\u0438\u043a \u0422\u0443\u043d\u043a\u0443\u0430\u043d\u044a\u044e\u0439 \u2014 \u043a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0430\u044f \u0432 \u0410\u0437\u0438\u0438 \u043f\u043e\u0434\u0437\u0435\u043c\u043d\u0430\u044f \u0448\u0430\u0445\u0442\u0430 \u000d\u000a\u043f\u043e \u0434\u043e\u0431\u044b\u0447\u0435 \u043d\u0435\u0443\u0433\u043e\u043b\u044c\u043d\u044b\u0445 \u0440\u0435\u0441\u0443\u0440\u0441\u043e\u0432 (9 \u043c\u043b\u043d \u0442\u043e\u043d\u043d \u0432 \u0433\u043e\u0434).\u000a\u000d\u000a\u0412 2024 \u0433\u043e\u0434\u0443 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u0437\u0430\u043a\u0430\u0437\u0430\u043b\u0430 \u0435\u0433\u043e \u0440\u0435\u0441\u0443\u0440\u0441\u043e\u0432. \u000d\u000a\u0414\u043e\u043a\u0430\u0437\u0430\u043d\u043d\u044b\u0435 \u0437\u0430\u043f\u0430\u0441\u044b \u043c\u0435\u0434\u0438 \u0441\u043e\u0441\u0442\u0430\u0432\u0438\u043b\u0438 49 \u043c\u043b\u043d \u0442\u043e\u043d\u043d (47,65%), \u000d\u000a\u043f\u0440\u0435\u0434\u043f\u043e\u043b\u0430\u0433\u0430\u0435\u043c\u044b\u0435 \u2014 54 \u043c\u043b\u043d \u0442\u043e\u043d\u043d. \u041f\u0440\u0438 \u044d\u0442\u043e\u043c \u043d\u0430 \u0434\u0435\u0439\u0441\u0442\u0432\u0443\u044e\u0449\u0438\u0445 \u000d\u000a\u0443\u0447\u0430\u0441\u0442\u043a\u0430\u0445 \u0440\u0443\u0434\u043d\u0438\u043a\u0430 1,3 \u043c\u043b\u043d \u0442\u043e\u043d\u043d \u043c\u0435\u0434\u0438.\u000a\u000d\u000a\u0421\u043e\u043f\u0443\u0442\u0441\u0442\u0432\u0443\u044e\u0449\u0438\u0435 \u043c\u0435\u0442\u0430\u043b\u043b\u044b:\u000d\u000a\u0438\u0441\u0441\u043b\u0435\u0434\u043e\u0432\u0430\u043d\u0438\u0435\u000d\u000a\u0441\u043e\u0434\u0435\u0440\u0436\u0438\u0442\u0441\u044f\u000d\u000a\u041f\u043e\u0441\u043b\u0435 \u0440\u0435\u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u0438\u0437\u0430\u0446\u0438\u0438 \u0432 2023 \u0433\u043e\u0434\u0443 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u0437\u0430\u043f\u0443\u0441\u0442\u0438\u043b\u0430: \u000d\u000a\u0412\u044b\u0440\u0443\u0447\u043a\u0430 \u0437\u0430 2024 \u0433\u043e\u0434 \u2014 $3,35 \u043c\u043b\u0440\u0434 (\u0440\u043e\u0441\u0442 157% \u043a 2023 \u0433\u043e\u0434\u0443).\u2028\u000d\u000a\u041f\u043e \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u044e \u0441 2020 \u0433\u043e\u0434\u043e\u043c (\u0434\u043e \u0440\u0435\u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u0438\u0437\u0430\u0446\u0438\u0438) \u000d\u000a\u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438 \u0432\u044b\u0440\u043e\u0441\u043b\u0430 \u0431\u043e\u043b\u0435\u0435 \u0447\u0435\u043c \u0432 20 \u0440\u0430\u0437.\u000d\u000a\u0432\u044b\u0440\u0443\u0447\u043a\u0430\u000d\u000ahttps://news.smm.cn/news/103508321\u000a\u000d\u000ahttps://finance.sina.com.cn/stock/aiassist/agqsjs/2025-10-31/docinfvuans7160486.shtml\u000d\u000a\u041f\u0440\u0435\u0434\u043f\u0440\u0438\u044f\u0442\u0438\u0435 \u0443\u0441\u0442\u0430\u043d\u043e\u0432\u0438\u043b\u043e \u043e\u0442\u0440\u0430\u0441\u043b\u0435\u0432\u043e\u0439 \u0440\u0435\u043a\u043e\u0440\u0434, \u0432\u044b\u043f\u043e\u043b\u043d\u0438\u0432 \u000d\u000a\u043d\u0435\u043f\u0440\u0435\u0440\u044b\u0432\u043d\u0443\u044e \u043f\u0440\u043e\u043a\u0430\u0442\u043a\u0443 20 \u0442\u044b\u0441. \u043c\u0435\u0442\u0440\u043e\u0432 6-\u043c\u0438\u043a\u0440\u043e\u043d\u043d\u043e\u0439 \u043c\u0435\u0434\u043d\u043e\u0439 \u000d\u000a\u0444\u043e\u043b\u044c\u0433\u0438.\u000d\u000a\u041f\u043e\u043c\u0438\u043c\u043e \u0440\u0443\u0434\u043d\u0438\u043a\u0430 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u0434\u0432\u0443\u043c\u044f \u000d\u000a\u043c\u0435\u0442\u0430\u043b\u043b\u0443\u0440\u0433\u0438\u0447\u0435\u0441\u043a\u0438\u043c\u0438 \u0437\u0430\u0432\u043e\u0434\u0430\u043c\u0438 \u0441 \u043c\u043e\u0449\u043d\u043e\u0441\u0442\u044c\u044e \u043f\u0435\u0440\u0435\u0440\u0430\u0431\u043e\u0442\u043a\u0438 \u000d\u000a1,3 \u043c\u043b\u043d \u0442\u043e\u043d\u043d \u043a\u043e\u043d\u0446\u0435\u043d\u0442\u0440\u0430\u0442\u0430 \u0432 \u0433\u043e\u0434.\u000a\u000d\u000a\u041f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u043e \u0432 2024 \u0433\u043e\u0434\u0443:\u000d\u000a\u0443\u043f\u0440\u0430\u0432\u043b\u044f\u0435\u0442\u000d\u000a\u0421\u0444\u0435\u0440\u0430 \u0434\u0435\u044f\u0442\u0435\u043b\u044c\u043d\u043e\u0441\u0442\u0438 \u0438 \u043f\u043e\u0437\u0438\u0446\u0438\u0438 \u0432 \u043e\u0442\u0440\u0430\u0441\u043b\u0438\u000d\u000a\u0418\u0441\u0442\u043e\u0440\u0438\u044f \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438\u000d\u000a\u0420\u0435\u0441\u0443\u0440\u0441\u043d\u0430\u044f \u0431\u0430\u0437\u0430 \u0438 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0435\u2028\u000d\u000a\u043c\u043e\u0449\u043d\u043e\u0441\u0442\u0438\u000d\u000a\u041a\u043b\u044e\u0447\u0435\u0432\u044b\u0435 \u043f\u0440\u043e\u0435\u043a\u0442\u044b\u000d\u000a\u0424\u0438\u043d\u0430\u043d\u0441\u043e\u0432\u044b\u0435 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u044b\u000d\u000a\u0418\u0441\u0442\u043e\u0447\u043d\u0438\u043a\u0438\u000d\u000a\u0437\u043e\u043b\u043e\u0442\u043e \u2014 8 930 \u043a\u0433 (0,09 \u0433 \u043d\u0430 \u0442\u043e\u043d\u043d\u0443);\u000a\u000d\u000a\u043c\u043e\u043b\u0438\u0431\u0434\u0435\u043d \u2014 3 727 \u0442\u043e\u043d\u043d (0,011%).\u000d\u000a\u043a\u043e\u043c\u043f\u043b\u0435\u043a\u0441\u043d\u0443\u044e \u0441\u0438\u0441\u0442\u0435\u043c\u0443 \u043f\u0435\u0440\u0435\u0440\u0430\u0431\u043e\u0442\u043a\u0438 \u043c\u0435\u0434\u043d\u044b\u0445 \u0440\u0443\u0434;\u000a\u000d\u000a\u043f\u0440\u043e\u0435\u043a\u0442 Beitong New Materials \u043f\u043e \u0432\u044b\u043f\u0443\u0441\u043a\u0443 \u043c\u0435\u0434\u043d\u043e\u0439 \u043f\u0440\u043e\u043a\u0430\u0442\u043d\u043e\u0439 \u000d\u000a\u043b\u0435\u043d\u0442\u044b, \u0444\u043e\u043b\u044c\u0433\u0438 \u0438 \u043f\u043b\u0430\u043a\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u043e\u0433\u043e \u043c\u0435\u0434\u044c\u044e \u043b\u0430\u043c\u0438\u043d\u0430\u0442\u0430 \u000d\u000a\u0434\u043b\u044f \u043f\u0435\u0447\u0430\u0442\u043d\u044b\u0445 \u043f\u043b\u0430\u0442.\u000d\u000a\u043c\u0435\u0434\u044c \u0432 \u043a\u043e\u043d\u0446\u0435\u043d\u0442\u0440\u0430\u0442\u0435 \u2014 43,6 \u0442\u044b\u0441. \u0442\u043e\u043d\u043d;\u000a\u000d\u000a\u043a\u0430\u0442\u043e\u0434\u043d\u0430\u044f \u043c\u0435\u0434\u044c \u2014 313,2 \u0442\u044b\u0441. \u0442\u043e\u043d\u043d;\u000a\u000d\u000a\u0437\u043e\u043b\u043e\u0442\u043e \u2014 6,3 \u043a\u0433;\u000a\u000d\u000a\u0441\u0435\u0440\u0435\u0431\u0440\u043e \u2014 58 \u043a\u0433;\u000a\u000d\u000a\u0441\u0435\u0440\u043d\u0430\u044f \u043a\u0438\u0441\u043b\u043e\u0442\u0430 \u2014 1,03 \u043c\u043b\u043d \u0442\u043e\u043d\u043d;\u000a\u000d\u000a\u043c\u0435\u0434\u043d\u0430\u044f \u0444\u043e\u043b\u044c\u0433\u0430 \u043f\u0440\u043e\u043a\u0430\u0442\u043d\u0430\u044f \u2014 5 \u0442\u044b\u0441. \u0442\u043e\u043d\u043d.","5/17\u000d\u000aHunan Nonferrous \u000d\u000aMetals Holding Group\u000d\u000a(\u6e56\u5357\u6709\u8272\u91d1\u5c5e\u63a7\u80a1\u96c6\u56e2\u6709\u9650\u516c\u53f8)\u000d\u000a\u0428\u0442\u0430\u0431-\u043a\u0432\u0430\u0440\u0442\u0438\u0440\u0430\u000d\u000a\u0427\u0430\u043d\u0448\u0430, \u043f\u0440\u043e\u0432\u0438\u043d\u0446\u0438\u044f \u0425\u0443\u043d\u0430\u043d\u044c\u000d\u000a\u0412\u0435\u0440\u0442\u0438\u043a\u0430\u043b\u044c\u043d\u043e \u0438\u043d\u0442\u0435\u0433\u0440\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u0430\u044f \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f, \u0434\u043e\u0431\u044b\u0432\u0430\u0435\u0442 14 \u0446\u0432\u0435\u0442\u043d\u044b\u0445 \u000d\u000a\u043c\u0435\u0442\u0430\u043b\u043b\u043e\u0432: \u0441\u0443\u0440\u044c\u043c\u0443, \u0441\u0432\u0438\u043d\u0435\u0446, \u0446\u0438\u043d\u043a, \u043c\u0435\u0434\u044c, \u0437\u043e\u043b\u043e\u0442\u043e, \u0441\u0435\u0440\u0435\u0431\u0440\u043e, \u000d\u000a\u043f\u0430\u043b\u043b\u0430\u0434\u0438\u0439, \u0438\u043d\u0434\u0438\u0439, \u0432\u0438\u0441\u043c\u0443\u0442, \u043a\u0430\u0434\u043c\u0438\u0439, \u0442\u0435\u043b\u043b\u0443\u0440, \u0431\u0435\u0440\u0438\u043b\u043b\u0438\u0439, \u0432\u043e\u043b\u044c\u0444\u0440\u0430\u043c, \u000d\u000a\u043c\u043e\u043b\u0438\u0431\u0434\u0435\u043d, \u0430 \u0442\u0430\u043a\u0436\u0435 \u0436\u0435\u043b\u0435\u0437\u043e. \u0412\u044b\u043f\u0443\u0441\u043a\u0430\u0435\u0442 20 \u0432\u0438\u0434\u043e\u0432 \u000d\u000a\u0445\u0438\u043c\u043f\u0440\u043e\u0434\u0443\u043a\u0446\u0438\u0438, \u0432 \u0442. \u0447. \u0441\u0435\u0440\u043d\u0443\u044e \u043a\u0438\u0441\u043b\u043e\u0442\u0443, \u043f\u043b\u0430\u0432\u0438\u043a\u043e\u0432\u0443\u044e \u043a\u0438\u0441\u043b\u043e\u0442\u0443, \u000d\u000a\u0444\u0442\u043e\u0440\u0438\u0434 \u0430\u043b\u044e\u043c\u0438\u043d\u0438\u044f.\u000a\u000d\u000aHunan Nonferrous \u0432\u0445\u043e\u0434\u0438\u0442 \u043f\u044f\u0442\u0435\u0440\u043a\u0443 \u043a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0438\u0445 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u0442\u0435\u043b\u0435\u0439 \u000d\u000a\u0446\u0432\u0435\u0442\u043d\u044b\u0445 \u043c\u0435\u0442\u0430\u043b\u043b\u043e\u0432 \u041a\u0438\u0442\u0430\u044f. \u041f\u0440\u0438\u043d\u0430\u0434\u043b\u0435\u0436\u0438\u0442 China Minmetals.\u000d\u000aHunan Nonferrous \u0441\u043e\u0437\u0434\u0430\u043d\u0430 \u0432 2004 \u0433\u043e\u0434\u0443 \u043f\u0440\u0430\u0432\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u043e\u043c \u000d\u000a\u043f\u0440\u043e\u0432\u0438\u043d\u0446\u0438\u0438 \u0425\u0443\u043d\u0430\u043d\u044c. \u0412 \u0435\u0435 \u0441\u043e\u0441\u0442\u0430\u0432 \u0432\u043e\u0448\u043b\u0438 \u0441\u0435\u043c\u044c \u043f\u0440\u0435\u0434\u043f\u0440\u0438\u044f\u0442\u0438\u0439 \u000d\u000a\u0446\u0432\u0435\u0442\u043d\u043e\u0439 \u043c\u0435\u0442\u0430\u043b\u043b\u0443\u0440\u0433\u0438\u0438 \u0438 \u041d\u0418\u0418 \u043f\u043e\u043b\u0435\u0437\u043d\u044b\u0445 \u0438\u0441\u043a\u043e\u043f\u0430\u0435\u043c\u044b\u0445 \u0432 \u0433. \u0427\u0430\u043d\u0448\u0430.\u000a\u000d\u000a\u0412 2009 \u0433\u043e\u0434\u0443 China Minmetals \u0438\u043d\u0432\u0435\u0441\u0442\u0438\u0440\u043e\u0432\u0430\u043b\u0430 $820 \u043c\u043b\u043d \u000d\u000a\u0438 \u043f\u043e\u043b\u0443\u0447\u0438\u043b\u0430 51% \u0430\u043a\u0446\u0438\u0439 Hunan Nonferrous.\u000a\u000d\u000a\u0412 2011 \u0433\u043e\u0434\u0443 \u043f\u0440\u0430\u0432\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u043e \u043f\u0440\u043e\u0432\u0438\u043d\u0446\u0438\u0438 \u043e\u0441\u0442\u0430\u0432\u0448\u0438\u0435\u0441\u044f \u000d\u000a49% China Minmetals, \u0438 Hunan Nonferrous \u0441\u0442\u0430\u043b\u0430 \u0435\u0435 \u000d\u000a\u0441\u0442\u043e\u043f\u0440\u043e\u0446\u0435\u043d\u0442\u043d\u043e\u0439 \u0434\u043e\u0447\u0435\u0440\u043d\u0435\u0439 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0435\u0439.\u000a\u000d\u000a\u0412 2016\u20132021 \u0433\u043e\u0434\u0430\u0445 Hunan Nonferrous \u043f\u0440\u043e\u0448\u043b\u0430 \u000d\u000a\u0440\u0435\u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u0438\u0437\u0430\u0446\u0438\u044e \u0438 \u043f\u043e\u043b\u0443\u0447\u0438\u043b\u0430 \u043e\u0442 China Minmetals \u0430\u043a\u0442\u0438\u0432\u044b \u000d\u000a\u043f\u043e \u0441\u0443\u0440\u044c\u043c\u0435, \u0444\u0442\u043e\u0440\u0443, \u0440\u0435\u0434\u043a\u043e\u0437\u0435\u043c\u0430\u043c, \u0430 \u0442\u0430\u043a\u0436\u0435 \u0440\u044f\u0434 \u0433\u043e\u0440\u043d\u043e\u0434\u043e\u0431\u044b\u0432\u0430\u044e\u0449\u0438\u0445 \u000d\u000a\u043f\u0440\u0435\u0434\u043f\u0440\u0438\u044f\u0442\u0438\u0439, \u0441\u0442\u0430\u0432 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0435\u0439 \u043f\u0440\u044f\u043c\u043e\u0433\u043e \u0443\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u044f \u0432 \u0440\u0430\u043c\u043a\u0430\u0445 \u000d\u000a\u0433\u0440\u0443\u043f\u043f\u044b.\u000a\u000d\u000a\u0412 2025 \u0433\u043e\u0434\u0443 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u0440\u0430\u0437\u0432\u0438\u0432\u0430\u0435\u0442 \u0434\u043e\u0431\u044b\u0447\u0443 \u043d\u0430 \u0442\u0440\u0435\u0445 \u043a\u043b\u044e\u0447\u0435\u0432\u044b\u0445 \u000d\u000a\u043f\u043b\u043e\u0449\u0430\u0434\u043a\u0430\u0445: \u0428\u0443\u0439\u043a\u043e\u0443\u0448\u0430\u043d\u044c, \u0421\u0438\u043a\u0443\u0430\u043d\u0448\u0430\u043d\u044c, \u0425\u0443\u0430\u043d\u0448\u0430\u043f\u0438\u043d, \u000d\u000a\u043c\u043e\u0434\u0435\u0440\u043d\u0438\u0437\u0438\u0440\u0443\u0435\u0442 \u0441\u0442\u0430\u0440\u044b\u0435 \u0448\u0430\u0445\u0442\u044b \u0438 \u0441\u0442\u0440\u043e\u0438\u0442 \u043d\u043e\u0432\u044b\u0435.\u000d\u000a\u043f\u0435\u0440\u0435\u0434\u0430\u043b\u043e \u000d\u000aHunan Nonferrous \u043a\u043b\u044e\u0447\u0435\u0432\u044b\u043c\u0438 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u043c\u0438 \u000d\u000a\u043f\u0440\u0435\u0434\u043f\u0440\u0438\u044f\u0442\u0438\u044f\u043c\u0438 China Minmetals:\u000d\u000a\u0443\u043f\u0440\u0430\u0432\u043b\u044f\u0435\u0442\u000d\u000a\u0421\u0444\u0435\u0440\u0430 \u0434\u0435\u044f\u0442\u0435\u043b\u044c\u043d\u043e\u0441\u0442\u0438 \u0438 \u043f\u043e\u0437\u0438\u0446\u0438\u0438 \u0432 \u043e\u0442\u0440\u0430\u0441\u043b\u0438\u000d\u000a\u0418\u0441\u0442\u043e\u0440\u0438\u044f \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438\u000d\u000a\u041a\u043b\u044e\u0447\u0435\u0432\u044b\u0435 \u043f\u0440\u043e\u0435\u043a\u0442\u044b\u000d\u000aZhuzhou Smelter Group \u0444\u043b\u0430\u0433\u043c\u0430\u043d \u0441\u0432\u0438\u043d\u0446\u043e\u0432\u043e \u0446\u0438\u043d\u043a\u043e\u0432\u043e\u0439 \u000d\u000a\u043e\u0442\u0440\u0430\u0441\u043b\u0438 \u041a\u0438\u0442\u0430\u044f.\u000a\u000d\u000aShuikoushan Nonferrous Metals \u0438\u0441\u0442\u043e\u0440\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u0446\u0435\u043d\u0442\u0440 \u000d\u000a\u0441\u0432\u0438\u043d\u0446\u043e\u0432\u043e \u0446\u0438\u043d\u043a\u043e\u0432\u043e\u0439 \u043f\u0440\u043e\u043c\u044b\u0448\u043b\u0435\u043d\u043d\u043e\u0441\u0442\u0438, \u043d\u0430 \u043f\u0438\u043a\u0435 \u0440\u0430\u0441\u0446\u0432\u0435\u0442\u0430 \u000d\u000a\u0441\u0447\u0438\u0442\u0430\u043b\u0441\u044f \u043c\u0438\u0440\u043e\u0432\u043e\u0439 \u0441\u0432\u0438\u043d\u0446\u043e\u0432\u043e\u0439 \u0441\u0442\u043e\u043b\u0438\u0446\u0435\u0439.\u000a\u000d\u000aXikuangshan Shanxing Antimony Industry \u043a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0438\u0439 \u000d\u000a\u043c\u0438\u0440\u043e\u0432\u043e\u0439 \u0446\u0435\u043d\u0442\u0440 \u0434\u043e\u0431\u044b\u0447\u0438 \u0441\u0443\u0440\u044c\u043c\u044b, \u0435\u0439 \u043f\u0440\u0438\u043d\u0430\u0434\u043b\u0435\u0436\u0438\u0442 \u0434\u043e 20% \u000d\u000a\u043c\u0438\u0440\u043e\u0432\u043e\u0433\u043e \u0440\u044b\u043d\u043a\u0430.\u000a\u000d\u000aMinmetals Copper \u043f\u0435\u0440\u0432\u044b\u0439 \u0432 \u043f\u0440\u043e\u0432\u0438\u043d\u0446\u0438\u0438 \u0425\u0443\u043d\u0430\u043d\u044c \u043a\u0440\u0443\u043f\u043d\u044b\u0439 \u000d\u000a\u043f\u0440\u043e\u0435\u043a\u0442 Minmetals \u043f\u043e \u0434\u043e\u0431\u044b\u0447\u0435 \u043c\u0435\u0434\u0438 \u0438 \u0437\u043e\u043b\u043e\u0442\u0430 \u043f\u043e\u0441\u043b\u0435 \u000d\u000a\u0440\u0435\u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u0438\u0437\u0430\u0446\u0438\u0438 Hunan Nonferrous Metals. \u041f\u0435\u0440\u0435\u0440\u0430\u0431\u0430\u0442\u044b\u0432\u0430\u0435\u0442 \u000d\u000a\u043e\u0442\u0445\u043e\u0434\u044b \u0434\u0440\u0443\u0433\u0438\u0445 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432, \u0441\u043e\u0434\u0435\u0440\u0436\u0430\u0449\u0438\u0435 \u043c\u0435\u0434\u044c \u0438 \u0437\u043e\u043b\u043e\u0442\u043e, \u000d\u000a\u0438\u0441\u043f\u043e\u043b\u044c\u0437\u0443\u0435\u0442 \u0437\u0430\u0440\u0443\u0431\u0435\u0436\u043d\u044b\u0435 \u0440\u0435\u0441\u0443\u0440\u0441\u044b, \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u0438\u0440\u0443\u0435\u043c\u044b\u0435 \u000d\u000aChina Minmetals.\u000a\u000d\u000aHunan Nonferrous Investment \u043b\u0438\u0434\u0435\u0440 \u043f\u0435\u0440\u0435\u0440\u0430\u0431\u043e\u0442\u043a\u0438 \u000d\u000a\u0444\u0442\u043e\u0440\u0441\u043e\u0434\u0435\u0440\u0436\u0430\u0449\u0438\u0445 \u043c\u0430\u0442\u0435\u0440\u0438\u0430\u043b\u043e\u0432.\u000a\u000d\u000aHuangshaping Mining \u00ab\u0432\u0435\u0447\u043d\u043e\u0437\u0435\u043b\u0435\u043d\u043e\u0435 \u0434\u0435\u0440\u0435\u0432\u043e \u043a\u0438\u0442\u0430\u0439\u0441\u043a\u043e\u0439 \u000d\u000a\u0446\u0432\u0435\u0442\u043d\u043e\u0439 \u043c\u0435\u0442\u0430\u043b\u043b\u0443\u0440\u0433\u0438\u0438\u00bb: \u0441\u0432\u0438\u043d\u0446\u043e\u0432\u043e \u0446\u0438\u043d\u043a\u043e\u0432\u044b\u0435, \u0432\u043e\u043b\u044c\u0444\u0440\u0430\u043c\u043e\u000d\u000a\u043c\u043e\u043b\u0438\u0431\u0434\u0435\u043d\u043e\u0432\u044b\u0435 \u043a\u043e\u043d\u0446\u0435\u043d\u0442\u0440\u0430\u0442\u044b, \u043a\u043e\u043c\u043f\u043b\u0435\u043a\u0441\u043d\u043e\u0435 \u0438\u0437\u0432\u043b\u0435\u0447\u0435\u043d\u0438\u0435 \u000d\u000a\u0441\u0435\u0440\u0435\u0431\u0440\u0430, \u0441\u0435\u0440\u044b, \u0436\u0435\u043b\u0435\u0437\u0430.\u000a\u000d\u000aMinmetals Beryllium \u0435\u0434\u0438\u043d\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0439 \u043f\u043e\u0441\u0442\u0430\u0432\u0449\u0438\u043a \u000d\u000a\u0432\u044b\u0441\u043e\u043a\u043e\u043a\u0430\u0447\u0435\u0441\u0442\u0432\u0435\u043d\u043d\u043e\u0433\u043e \u043c\u0435\u0442\u0430\u043b\u043b\u0438\u0447\u0435\u0441\u043a\u043e\u0433\u043e \u0431\u0435\u0440\u0438\u043b\u043b\u0438\u044f \u000d\u000a\u0438 \u0432\u044b\u0441\u043e\u043a\u043e\u0447\u0438\u0441\u0442\u043e\u0433\u043e \u043e\u043a\u0441\u0438\u0434\u0430 \u0431\u0435\u0440\u0438\u043b\u043b\u0438\u044f \u0432 \u041a\u0438\u0442\u0430\u0435.\u000d\u000a\u0413\u043e\u0440\u043d\u043e\u0434\u043e\u0431\u044b\u0432\u0430\u044e\u0449\u0435\u0435\u2028\u000d\u000a\u043f\u0440\u0435\u0434\u043f\u0440\u0438\u044f\u0442\u0438\u0435\u000d\u000a\u0412\u044b\u043f\u043b\u0430\u0432\u043a\u0430 \u043c\u0435\u0434\u0438","6/17\u000d\u000a\u041f\u0440\u043e\u0432\u0438\u043d\u0446\u0438\u044e \u0425\u0443\u043d\u0430\u043d\u044c, \u0433\u0434\u0435 \u0441\u043e\u0441\u0440\u0435\u0434\u043e\u0442\u043e\u0447\u0435\u043d\u044b \u043e\u0441\u043d\u043e\u0432\u043d\u044b\u0435 \u0430\u043a\u0442\u0438\u0432\u044b \u000d\u000a\u0433\u0440\u0443\u043f\u043f\u044b, \u0432 \u041a\u0438\u0442\u0430\u0435 \u043d\u0430\u0437\u044b\u0432\u0430\u044e\u0442 \u00ab\u0440\u043e\u0434\u0438\u043d\u043e\u0439 \u0446\u0432\u0435\u0442\u043d\u044b\u0445 \u043c\u0435\u0442\u0430\u043b\u043b\u043e\u0432\u00bb.\u000a\u000d\u000a\u041d\u0435 \u0432\u0441\u0435 \u0437\u0430\u043f\u0430\u0441\u044b Hunan Nonferrous \u0434\u043e\u0441\u0442\u0443\u043f\u043d\u044b \u043f\u043e \u043e\u0442\u043a\u0440\u044b\u0442\u044b\u043c \u000d\u000a\u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a\u0430\u043c, \u0442\u0430\u043a \u043a\u0430\u043a \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u0443\u0435\u0442 \u0438 \u0440\u0435\u0441\u0443\u0440\u0441\u044b, \u000d\u000a\u043f\u0440\u0435\u0434\u043e\u0441\u0442\u0430\u0432\u043b\u044f\u0435\u043c\u044b\u0435 China Minmetals.\u000a\u000d\u000a\u0421\u0430\u043c\u044b\u0435 \u0437\u043d\u0430\u0447\u0438\u0442\u0435\u043b\u044c\u043d\u044b\u0435 \u0440\u0435\u0437\u0435\u0440\u0432\u044b \u0432 \u0440\u0430\u0441\u043f\u043e\u0440\u044f\u0436\u0435\u043d\u0438\u0438 \u000d\u000aHunan Nonferrous:\u000d\u000a\u041c\u043e\u0449\u043d\u043e\u0441\u0442\u0438 \u043a\u043e\u043d\u0435\u0447\u043d\u043e\u0439 \u043f\u0440\u043e\u0434\u0443\u043a\u0446\u0438\u0438, \u043f\u043e\u043c\u0438\u043c\u043e \u000d\u000a\u043a\u043e\u043d\u0446\u0435\u043d\u0442\u0440\u0430\u0442\u043e\u0432 \u0438 \u043f\u043e\u043b\u0443\u0444\u0430\u0431\u0440\u0438\u043a\u0430\u0442\u043e\u0432:\u000d\u000a\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0430\u000d\u000a\u0441\u0443\u0440\u044c\u043c\u0430 \u2014 200\u2013300 \u0442\u044b\u0441. \u0442\u043e\u043d\u043d, \u044d\u0442\u043e 30% \u043e\u0442 \u043c\u0438\u0440\u043e\u0432\u044b\u0445 \u0437\u0430\u043f\u0430\u0441\u043e\u0432.  \u000d\u000a\u0437\u043e\u043b\u043e\u0442\u043e \u0432 \u0441\u043b\u0438\u0442\u043a\u0430\u0445 \u2014 2,44 \u0442\u043e\u043d\u043d\u044b;\u000a\u000d\u000a\u0441\u0435\u0440\u0435\u0431\u0440\u043e \u0432 \u0441\u043b\u0438\u0442\u043a\u0430\u0445 \u2014 200 \u0442\u043e\u043d\u043d;\u000a\u000d\u000a\u0441\u0443\u0440\u044c\u043c\u0430 \u2014 30 \u0442\u044b\u0441. \u0442\u043e\u043d\u043d;\u000a\u000d\u000a\u043a\u0430\u0442\u043e\u0434\u043d\u0430\u044f \u043c\u0435\u0434\u044c \u2014 100 \u0442\u044b\u0441. \u0442\u043e\u043d\u043d;\u000a\u000d\u000a\u0446\u0438\u043d\u043a \u2014 680 \u0442\u044b\u0441. \u0442\u043e\u043d\u043d;\u000a\u000d\u000a\u0441\u0432\u0438\u043d\u0435\u0446 \u2014 150 \u0442\u044b\u0441. \u0442\u043e\u043d\u043d;\u000a\u000d\u000a\u0444\u0442\u043e\u0440\u0441\u043e\u0434\u0435\u0440\u0436\u0430\u0449\u0438\u0435 \u0445\u0438\u043c\u0438\u0447\u0435\u0441\u043a\u0438\u0435 \u043f\u0440\u043e\u0434\u0443\u043a\u0442\u044b \u2014 129 \u0442\u044b\u0441. \u0442\u043e\u043d\u043d;\u000a\u000d\u000a\u0441\u0435\u0440\u043d\u0430\u044f \u043a\u0438\u0441\u043b\u043e\u0442\u0430 \u2014 1,1 \u043c\u043b\u043d \u0442\u043e\u043d\u043d.\u000d\u000a\u0414\u0438\u0441\u0431\u0430\u043b\u0430\u043d\u0441 \u0441\u043f\u0440\u043e\u0441\u0430 \u0438 \u043f\u0440\u0435\u0434\u043b\u043e\u0436\u0435\u043d\u0438\u044f \u043d\u0430 \u0440\u044b\u043d\u043a\u0435 \u0441\u044b\u0440\u044c\u044f.\u000a\u000d\u000a\u0421\u043d\u0438\u0436\u0435\u043d\u0438\u0435 \u043c\u0430\u0440\u0436\u0438 \u043f\u0435\u0440\u0435\u0440\u0430\u0431\u043e\u0442\u043a\u0438 \u043c\u0435\u0442\u0430\u043b\u043b\u043e\u0432.\u000a\u000d\u000a\u0423\u0441\u0438\u043b\u0435\u043d\u0438\u0435 \u044d\u043a\u0441\u043f\u043e\u0440\u0442\u043d\u043e\u0433\u043e \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044f \u043d\u0430\u0434 \u043f\u0440\u043e\u0434\u0443\u043a\u0446\u0438\u0435\u0439 \u0434\u0432\u043e\u0439\u043d\u043e\u0433\u043e \u000d\u000a\u043d\u0430\u0437\u043d\u0430\u0447\u0435\u043d\u0438\u044f (\u043e\u0441\u043e\u0431\u0435\u043d\u043d\u043e \u0441\u0443\u0440\u044c\u043c\u044b); \u0432 \u0434\u0435\u043a\u0430\u0431\u0440\u0435 2025 \u0433\u043e\u0434\u0430 \u000d\u000a\u0437\u0430 \u043d\u0435\u043b\u0435\u0433\u0430\u043b\u044c\u043d\u044b\u0439 \u044d\u043a\u0441\u043f\u043e\u0440\u0442 \u0441\u0443\u0440\u044c\u043c\u044b \u0432\u044b\u043d\u0435\u0441\u0435\u043d \u043f\u0440\u0438\u0433\u043e\u0432\u043e\u0440 \u2014\u2028\u000d\u000a12 \u043b\u0435\u0442 \u043b\u0438\u0448\u0435\u043d\u0438\u044f \u0441\u0432\u043e\u0431\u043e\u0434\u044b \u0438 \u0448\u0442\u0440\u0430\u0444 \u2014 $139 \u0442\u044b\u0441.\u000a\u000d\u000a\u0421\u043b\u0430\u0431\u044b\u0439 \u0441\u043f\u0440\u043e\u0441 \u0438 \u0441\u043d\u0438\u0436\u0435\u043d\u0438\u0435 \u0446\u0435\u043d \u043d\u0430 \u0431\u0435\u0440\u0438\u043b\u043b\u0438\u0435\u0432\u0443\u044e \u043f\u0440\u043e\u0434\u0443\u043a\u0446\u0438\u044e.\u000a\u000d\u000a\u0423\u0436\u0435\u0441\u0442\u043e\u0447\u0435\u043d\u0438\u0435 \u044d\u043a\u043e\u043b\u043e\u0433\u0438\u0447\u0435\u0441\u043a\u0438\u0445 \u0442\u0440\u0435\u0431\u043e\u0432\u0430\u043d\u0438\u0439. \u0412 2017 \u0433\u043e\u0434\u0443 Hunan \u000d\u000aNonferrous \u043e\u0431\u0432\u0438\u043d\u0438\u043b\u0438 \u0432 \u0437\u0430\u0433\u0440\u044f\u0437\u043d\u0435\u043d\u0438\u0438 \u0432\u043e\u0434 \u043f\u0440\u0438 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0435 \u000d\u000a\u0446\u0438\u043d\u043a\u0430. \u041c\u043e\u0434\u0435\u0440\u043d\u0438\u0437\u0430\u0446\u0438\u044f \u0438 \u044d\u043a\u043e\u043b\u043e\u0433\u0438\u0447\u0435\u0441\u043a\u0438\u0435 \u043c\u0435\u0440\u044b \u043e\u0431\u043e\u0448\u043b\u0438\u0441\u044c \u000d\u000a\u0432 $1,39 \u043c\u043b\u0440\u0434.\u000d\u000a\u0432\u044b\u0440\u0443\u0447\u043a\u0430 \u2014 $3,34 \u043c\u043b\u0440\u0434 (+8,55%).\u000d\u000a\u0432\u044b\u0440\u0443\u0447\u043a\u0430 \u2014 $2,40 \u043c\u043b\u0440\u0434 (+31,31%).\u000d\u000a\u0412\u044b\u0440\u0443\u0447\u043a\u0430 \u0432 2024 \u0433\u043e\u0434\u0443 \u2014 $5 5,5 \u043c\u043b\u0440\u0434.\u000a\u000d\u000a\u041f\u043e\u0441\u043b\u0435\u0434\u043d\u0438\u0435 \u0434\u043e\u0441\u0442\u0443\u043f\u043d\u044b\u0435 \u0434\u0430\u043d\u043d\u044b\u0435 \u0437\u0430 \u0432\u0435\u0441\u044c 2023 \u0433\u043e\u0434: \u000d\u000a1-\u0435 \u043f\u043e\u043b\u0443\u0433\u043e\u0434\u0438\u0435 2024 \u0433\u043e\u0434\u0430:\u000d\u000a\u0424\u0438\u043d\u0430\u043d\u0441\u043e\u0432\u044b\u0435 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u044b\u000d\u000aHunan Nonferrous Metals Holding Group (\u6e56\u5357\u6709\u8272\u91d1\u5c5e\u63a7\u80a1\u96c6\u56e2\u6709\u9650\u516c\u53f8)\u000d\u000a\u0420\u0435\u0441\u0443\u0440\u0441\u043d\u0430\u044f \u0431\u0430\u0437\u0430 \u0438 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0435\u2028\u000d\u000a\u043c\u043e\u0449\u043d\u043e\u0441\u0442\u0438\u000d\u000a\u041f\u0440\u043e\u0431\u043b\u0435\u043c\u044b \u0438 \u0432\u044b\u0437\u043e\u0432\u044b\u000d\u000a\u0413\u043e\u0440\u043d\u043e \u043e\u0431\u043e\u0433\u0430\u0442\u0438\u0442\u0435\u043b\u044c\u043d\u044b\u0439 \u043a\u043e\u043c\u0431\u0438\u043d\u0430\u0442","7/17\u000d\u000aTongling Nonferrous \u000d\u000aMetals Group\u000d\u000a(\u94dc\u9675\u6709\u8272\u91d1\u5c5e\u96c6\u56e2)\u000d\u000a\u0428\u0442\u0430\u0431-\u043a\u0432\u0430\u0440\u0442\u0438\u0440\u0430\u000d\u000a\u0422\u0443\u043d\u043b\u0438\u043d, \u043f\u0440\u043e\u0432\u0438\u043d\u0446\u0438\u044f \u0410\u043d\u044c\u0445\u043e\u0439\u000d\u000a\u041e\u0441\u043d\u043e\u0432\u043d\u0430\u044f \u043f\u0440\u043e\u0434\u0443\u043a\u0446\u0438\u044f \u2014 \u0440\u0430\u0444\u0438\u043d\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u0430\u044f \u043c\u0435\u0434\u044c, \u043f\u0440\u043e\u0432\u043e\u043b\u043e\u043a\u0430, \u000d\u000a\u0444\u043e\u043b\u044c\u0433\u0430, \u043f\u043b\u0430\u0441\u0442\u0438\u043d\u044b.\u000a\u000d\u000aTongling Nonferrous \u0432\u0445\u043e\u0434\u0438\u0442 \u0432 Fortune Global 500 \u0441\u0435\u043c\u044c \u043b\u0435\u0442 \u000d\u000a\u043f\u043e\u0434\u0440\u044f\u0434. \u0412 2025 \u0433\u043e\u0434\u0443 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u0437\u0430\u043d\u044f\u043b\u0430 451-\u0435 \u043c\u0435\u0441\u0442\u043e.\u000d\u000a\u0422\u0443\u043d\u043b\u0438\u043d \u0441\u0447\u0438\u0442\u0430\u0435\u0442\u0441\u044f \u0431\u0440\u043e\u043d\u0437\u043e\u0432\u043e\u0439 \u0441\u0442\u043e\u043b\u0438\u0446\u0435\u0439 \u041a\u0438\u0442\u0430\u044f: \u043c\u0435\u0434\u044c \u0437\u0434\u0435\u0441\u044c \u000d\u000a\u0434\u043e\u0431\u044b\u0432\u0430\u044e\u0442 \u043d\u0435\u0441\u043a\u043e\u043b\u044c\u043a\u043e \u0442\u044b\u0441\u044f\u0447\u0435\u043b\u0435\u0442\u0438\u0439.\u000a\u000d\u000a\u0412 1949 \u0433\u043e\u0434\u0443, \u0441\u0440\u0430\u0437\u0443 \u043f\u043e\u0441\u043b\u0435 \u043e\u0441\u043d\u043e\u0432\u0430\u043d\u0438\u044f \u041a\u041d\u0420, \u0432\u043b\u0430\u0441\u0442\u0438 \u0440\u0435\u0448\u0438\u043b\u0438 \u000d\u000a\u0441\u043e\u0437\u0434\u0430\u0442\u044c \u0442\u0443\u0442 \u0438\u043d\u0434\u0443\u0441\u0442\u0440\u0438\u0430\u043b\u044c\u043d\u044b\u0439 \u043c\u0435\u0434\u043d\u044b\u0439 \u043a\u043e\u043c\u043f\u043b\u0435\u043a\u0441.\u000a\u000d\u000a\u041a 1980 \u0433\u043e\u0434\u0443 \u043c\u043e\u0449\u043d\u043e\u0441\u0442\u044c \u043f\u0440\u0435\u0434\u043f\u0440\u0438\u044f\u0442\u0438\u044f \u0432\u044b\u0440\u043e\u0441\u043b\u0430 \u043f\u0440\u0438\u043c\u0435\u0440\u043d\u043e \u000d\u000a\u0432 20 \u0440\u0430\u0437. \u041f\u043e\u0441\u0442\u0440\u043e\u0435\u043d\u044b \u043d\u043e\u0432\u044b\u0435 \u0440\u0443\u0434\u043d\u0438\u043a\u0438, \u043e\u0431\u043e\u0433\u0430\u0442\u0438\u0442\u0435\u043b\u044c\u043d\u044b\u0435 \u0444\u0430\u0431\u0440\u0438\u043a\u0438 \u000d\u000a\u0438 \u0434\u0432\u0430 \u043c\u0435\u0434\u0435\u043f\u043b\u0430\u0432\u0438\u043b\u044c\u043d\u044b\u0445 \u0437\u0430\u0432\u043e\u0434\u0430.\u000a\u000d\u000a\u0412 2014 \u0433\u043e\u0434\u0443 \u0437\u0430\u043f\u0443\u0449\u0435\u043d\u043e \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u043e \u0432\u044b\u0441\u043e\u043a\u043e\u0442\u043e\u0447\u043d\u043e\u0439 \u043c\u0435\u0434\u043d\u043e\u0439 \u000d\u000a\u0444\u043e\u043b\u044c\u0433\u0438 \u0434\u043b\u044f \u044d\u043b\u0435\u043a\u0442\u0440\u043e\u043d\u043d\u044b\u0445 \u043f\u0440\u0438\u0431\u043e\u0440\u043e\u0432 \u0438 \u043b\u0438\u0442\u0438\u0435\u0432\u044b\u0445 \u0430\u043a\u043a\u0443\u043c\u0443\u043b\u044f\u0442\u043e\u0440\u043e\u0432 \u000d\u000a\u0442\u043e\u043b\u0449\u0438\u043d\u043e\u0439 \u043e\u0442 8 \u043c\u043a\u043c.\u000a\u000d\u000a\u0412 2023 \u0433\u043e\u0434\u0443 Tongling \u043a\u0443\u043f\u0438\u043b\u0430 70% China Railway Construction \u000d\u000aCopper Crown, \u0432\u043b\u0430\u0434\u0435\u044e\u0449\u0435\u0439 \u043c\u0435\u0434\u043d\u044b\u043c \u0440\u0443\u0434\u043d\u0438\u043a\u043e\u043c \u041c\u0438\u0440\u0430\u0434\u043e\u0440 \u000d\u000a(\u042d\u043a\u0432\u0430\u0434\u043e\u0440).\u000d\u000a\u0421\u0444\u0435\u0440\u0430 \u0434\u0435\u044f\u0442\u0435\u043b\u044c\u043d\u043e\u0441\u0442\u0438 \u0438 \u043f\u043e\u0437\u0438\u0446\u0438\u0438 \u0432 \u043e\u0442\u0440\u0430\u0441\u043b\u0438\u000d\u000a\u0418\u0441\u0442\u043e\u0440\u0438\u044f \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438\u000d\u000a\u041a\u043b\u044e\u0447\u0435\u0432\u044b\u0435 \u043f\u0440\u043e\u0435\u043a\u0442\u044b\u000d\u000aTongling \u0440\u0430\u0437\u0432\u0438\u0432\u0430\u0435\u0442 \u043a\u043b\u0430\u0441\u0442\u0435\u0440 Anhui Tongling Advanced \u000d\u000aStructural Materials, \u0432\u043a\u043b\u044e\u0447\u0430\u044e\u0449\u0438\u0439 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u043e \u043d\u043e\u0432\u044b\u0445 \u000d\u000a\u043c\u0430\u0442\u0435\u0440\u0438\u0430\u043b\u043e\u0432 \u043d\u0430 \u043e\u0441\u043d\u043e\u0432\u0435 \u043c\u0435\u0434\u0438.\u000a\u000d\u000aTongguan Copper Foil Group \u043e\u0434\u043d\u043e\u0439 \u0438\u0437 \u043f\u0435\u0440\u0432\u044b\u0445 \u0432 \u041a\u0438\u0442\u0430\u0435 \u000d\u000a\u0437\u0430\u043f\u0443\u0441\u0442\u0438\u043b\u0430 \u043c\u0430\u0441\u0441\u043e\u0432\u044b\u0439 \u0432\u044b\u043f\u0443\u0441\u043a \u043c\u0435\u0434\u043d\u043e\u0439 \u0444\u043e\u043b\u044c\u0433\u0438 \u0434\u043b\u044f \u043b\u0438\u0442\u0438\u0435\u0432\u044b\u0445 \u000d\u000a\u0431\u0430\u0442\u0430\u0440\u0435\u0439 \u0442\u043e\u043b\u0449\u0438\u043d\u043e\u0439 4,5 \u0438 6 \u043c\u043a\u043c.\u000a\u000d\u000a\u0412 \u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u0435 \u0445\u043e\u043b\u0434\u0438\u043d\u0433\u0430 \u2014 \u043d\u0430\u0446\u0438\u043e\u043d\u0430\u043b\u044c\u043d\u044b\u0439 \u0442\u0435\u0445\u043d\u043e\u043b\u043e\u0433\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u000d\u000a\u0446\u0435\u043d\u0442\u0440, \u0430\u043a\u043a\u0440\u0435\u0434\u0438\u0442\u043e\u0432\u0430\u043d\u043d\u0430\u044f \u043b\u0430\u0431\u043e\u0440\u0430\u0442\u043e\u0440\u0438\u044f \u0438 \u0435\u0449\u0435 48 \u0434\u043e\u0447\u0435\u0440\u043d\u0438\u0445 \u000d\u000a\u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0439.\u000a\u000d\u000a\u0412 2024 \u0433\u043e\u0434\u0443 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u0432\u043b\u043e\u0436\u0438\u043b\u0430 \u0432 \u041d\u0418\u041e\u041a\u0420 $660 \u043c\u043b\u043d. \u000d\u000a\u0420\u0435\u0430\u043b\u0438\u0437\u043e\u0432\u0430\u043b\u0430 410 \u043d\u0430\u0443\u0447\u043d\u043e-\u0442\u0435\u0445\u043d\u0438\u0447\u0435\u0441\u043a\u0438\u0445 \u043f\u0440\u043e\u0435\u043a\u0442\u043e\u0432.\u000d\u000a\u0412\u043e\u043b\u0430\u0442\u0438\u043b\u044c\u043d\u043e\u0441\u0442\u044c \u0446\u0435\u043d \u043d\u0430 \u0446\u0432\u0435\u0442\u043d\u044b\u0435 \u043c\u0435\u0442\u0430\u043b\u043b\u044b.\u000a\u000d\u000a\u041d\u0438\u0437\u043a\u0438\u0435 \u0442\u0430\u0440\u0438\u0444\u044b \u043d\u0430 \u043f\u0435\u0440\u0435\u0440\u0430\u0431\u043e\u0442\u043a\u0443 \u043c\u0435\u0434\u0438.\u000a\u000d\u000a\u0420\u0430\u0441\u0442\u0443\u0449\u0438\u0435 \u0442\u0440\u0435\u0431\u043e\u0432\u0430\u043d\u0438\u044f \u043a \u043c\u0430\u0442\u0435\u0440\u0438\u0430\u043b\u0430\u043c \u0434\u043b\u044f \u043d\u043e\u0432\u043e\u0439 \u044d\u043d\u0435\u0440\u0433\u0435\u0442\u0438\u043a\u0438.\u000d\u000a\u0428\u0442\u0430\u0431-\u043a\u0432\u0430\u0440\u0442\u0438\u0440\u0430 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438\u000d\u000a\u041e\u0431\u0449\u0438\u0435 \u0437\u0430\u043f\u0430\u0441\u044b \u043c\u0435\u0434\u0438 \u0433\u0440\u0443\u043f\u043f\u044b \u2014 8,8 \u043c\u043b\u043d \u0442\u043e\u043d\u043d. \u0418\u0437 \u043d\u0438\u0445 7 \u043c\u043b\u043d \u0442\u043e\u043d\u043d \u2014 \u000d\u000a\u0432 \u042d\u043a\u0432\u0430\u0434\u043e\u0440\u0435, 1,8 \u043c\u043b\u043d \u0442\u043e\u043d\u043d \u2014 \u0432 \u041a\u0438\u0442\u0430\u0435.\u000a\u000d\u000a\u041c\u0435\u0441\u0442\u043e\u0440\u043e\u0436\u0434\u0435\u043d\u0438\u0435 \u041c\u0438\u0440\u0430\u0434\u043e\u0440 \u0432 \u042d\u043a\u0432\u0430\u0434\u043e\u0440\u0435:\u000d\u000a\u0413\u043e\u0434\u043e\u0432\u043e\u0439 \u043e\u0431\u044a\u0435\u043c \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0430 \u0440\u0430\u0444\u0438\u043d\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u043e\u0439 \u043c\u0435\u0434\u0438 \u2014 \u000d\u000a1,76 \u043c\u043b\u043d \u0442\u043e\u043d\u043d.\u000a\u000d\u000a\u041a\u0430\u0442\u043e\u0434\u043d\u0430\u044f \u043c\u0435\u0434\u044c \u043c\u0430\u0440\u043a\u0438 \u00ab\u0422\u0443\u043d\u0433\u0443\u0430\u043d\u044c\u00bb \u0437\u0430\u0440\u0435\u0433\u0438\u0441\u0442\u0440\u0438\u0440\u043e\u0432\u0430\u043d\u0430 \u043d\u0430 LME, \u000d\u000a\u0441\u0435\u0440\u0435\u0431\u0440\u044f\u043d\u044b\u0435 \u0441\u043b\u0438\u0442\u043a\u0438 \u0442\u043e\u0439 \u0436\u0435 \u043c\u0430\u0440\u043a\u0438 \u2014 \u0432 LBMA.\u000d\u000a\u0412\u044b\u0440\u0443\u0447\u043a\u0430 \u0437\u0430 2024 \u0433\u043e\u0434 \u2014 $20,3 \u043c\u043b\u0440\u0434 (+5,88%).\u000d\u000a\u041a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u0443\u0441\u0438\u043b\u0438\u0432\u0430\u0435\u0442 \u0442\u0435\u0445\u043d\u043e\u043b\u043e\u0433\u0438\u0447\u0435\u0441\u043a\u0443\u044e \u0431\u0430\u0437\u0443, \u0447\u0442\u043e\u0431\u044b \u0443\u0434\u0435\u0440\u0436\u0438\u0432\u0430\u0442\u044c \u000d\u000a\u043c\u0430\u0440\u0436\u0443 \u0438 \u0441\u043e\u043e\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u043e\u0432\u0430\u0442\u044c \u0442\u0440\u0435\u0431\u043e\u0432\u0430\u043d\u0438\u044f\u043c \u0446\u0435\u043f\u043e\u0447\u0435\u043a Li-ion\u0430\u043a\u043a\u0443\u043c\u0443\u043b\u044f\u0442\u043e\u0440\u043e\u0432, \u044d\u043b\u0435\u043a\u0442\u0440\u043e\u043d\u0438\u043a\u0438 \u0438 \u0432\u044b\u0441\u043e\u043a\u043e\u0442\u043e\u0447\u043d\u043e\u0439 \u043c\u0435\u0434\u0438.\u000d\u000a\u043c\u0435\u0434\u044c \u2014 7 \u043c\u043b\u043d \u0442\u043e\u043d\u043d;\u000a\u000d\u000a\u0437\u043e\u043b\u043e\u0442\u043e \u2014 181 \u0442\u043e\u043d\u043d\u0430;\u000a\u000d\u000a\u0441\u0435\u0440\u0435\u0431\u0440\u043e \u2014 1108 \u0442\u043e\u043d\u043d.\u000d\u000a\u0420\u0435\u0441\u0443\u0440\u0441\u043d\u0430\u044f \u0431\u0430\u0437\u0430 \u0438 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0435\u2028\u000d\u000a\u043c\u043e\u0449\u043d\u043e\u0441\u0442\u0438\u000d\u000a\u0424\u0438\u043d\u0430\u043d\u0441\u043e\u0432\u044b\u0435 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u044b\u000d\u000a\u041f\u0440\u043e\u0431\u043b\u0435\u043c\u044b \u0438 \u0432\u044b\u0437\u043e\u0432\u044b","8/17\u000d\u000aTsingshan Holding \u000d\u000aGroup Co., Ltd.\u000d\u000a(\u9752\u5c71\u63a7\u80a1\u96c6\u56e2\u6709\u9650\u516c\u53f8)\u000d\u000a\u0428\u0442\u0430\u0431-\u043a\u0432\u0430\u0440\u0442\u0438\u0440\u0430\u000d\u000a\u0412\u044d\u043d\u044c\u0447\u0436\u043e\u0443, \u043f\u0440\u043e\u0432\u0438\u043d\u0446\u0438\u044f \u000d\u000a\u0427\u0436\u044d\u0446\u0437\u044f\u043d\u000d\u000a\u041a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0438\u0439 \u0447\u0430\u0441\u0442\u043d\u044b\u0439 \u043d\u0435\u0440\u0436\u0430\u0432\u0435\u044e\u0449\u0435\u0439 \u0441\u0442\u0430\u043b\u0438 \u000d\u000a\u0438 \u043c\u0430\u0442\u0435\u0440\u0438\u0430\u043b\u043e\u0432 \u0434\u043b\u044f \u043d\u043e\u0432\u043e\u0439 \u044d\u043d\u0435\u0440\u0433\u0435\u0442\u0438\u043a\u0438 \u043d\u0430 \u043e\u0441\u043d\u043e\u0432\u0435 \u043d\u0438\u043a\u0435\u043b\u044f \u0432 \u041a\u0438\u0442\u0430\u0435.\u000a\u000d\u000a\u041a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u0438\u043c\u0435\u0435\u0442 \u0440\u0435\u043f\u0443\u0442\u0430\u0446\u0438\u044e \u043b\u0438\u0434\u0435\u0440\u0430 \u0442\u0435\u0445\u043d\u043e\u043b\u043e\u0433\u0438\u0447\u0435\u0441\u043a\u0438\u0445 \u000d\u000a\u0438\u043d\u043d\u043e\u0432\u0430\u0446\u0438\u0439 \u0438 \u043d\u043e\u0432\u044b\u0445 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0445 \u0440\u0435\u0448\u0435\u043d\u0438\u0439.\u000a\u000d\u000a\u0417\u0430\u043d\u0438\u043c\u0430\u0435\u0442 265-\u0435 \u043c\u0435\u0441\u0442\u043e \u0432 Fortune Global 500.\u000d\u000a\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u0442\u0435\u043b\u044c \u000d\u000aTsingshan \u0441\u043e\u0437\u0434\u0430\u043d\u0430 \u0432 2003 \u0433\u043e\u0434\u0443. \u0415\u0435 \u043f\u0440\u0435\u0434\u0448\u0435\u0441\u0442\u0432\u0435\u043d\u043d\u0438\u0446\u0435\u0439 \u000d\u000a\u0431\u044b\u043b\u0430 Zhejiang Tsingshan Special Steel Co., Ltd., \u0440\u0430\u0431\u043e\u0442\u0430\u0432\u0448\u0430\u044f \u000d\u000a\u0441 1998 \u0433\u043e\u0434\u0430.\u000a\u000d\u000a\u0412 2008 \u0433\u043e\u0434\u0443 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u043f\u0435\u0440\u0432\u043e\u0439 \u0432 \u043c\u0438\u0440\u0435 \u043f\u043e\u0441\u0442\u0440\u043e\u0438\u043b\u0430 \u000d\u000a\u0438\u043d\u0442\u0435\u0433\u0440\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u0443\u044e \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0435\u043d\u043d\u0443\u044e \u043b\u0438\u043d\u0438\u044e RKEF-AOD \u000d\u000a\u0434\u043b\u044f \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0430 \u043d\u0435\u0440\u0436\u0430\u0432\u0435\u044e\u0449\u0435\u0439 \u0441\u0442\u0430\u043b\u0438, \u0432 \u043a\u043e\u0440\u043d\u0435 \u0438\u0437\u043c\u0435\u043d\u0438\u0432 \u000d\u000a\u0442\u0440\u0430\u0434\u0438\u0446\u0438\u043e\u043d\u043d\u044b\u0435 \u0442\u0435\u0445\u043d\u043e\u043b\u043e\u0433\u0438\u0438. \u000a\u000d\u000a\u0412 2009 \u0433\u043e\u0434\u0443 Tsingshan \u0441\u0434\u0435\u043b\u0430\u043b\u0430 \u043f\u0435\u0440\u0432\u044b\u0435 \u0438\u043d\u0432\u0435\u0441\u0442\u0438\u0446\u0438\u0438 \u000d\u000a\u0432 \u0440\u0430\u0437\u0440\u0430\u0431\u043e\u0442\u043a\u0443 \u043c\u0435\u0441\u0442\u043e\u0440\u043e\u0436\u0434\u0435\u043d\u0438\u044f \u043b\u0430\u0442\u0435\u0440\u0438\u0442\u043d\u043e\u0439 \u043d\u0438\u043a\u0435\u043b\u0435\u0432\u043e\u0439 \u0440\u0443\u0434\u044b \u000d\u000a\u0432 \u0418\u043d\u0434\u043e\u043d\u0435\u0437\u0438\u0438, \u0438\u0437 \u043a\u043e\u0442\u043e\u0440\u043e\u0433\u043e \u0440\u0430\u0437\u043e\u0432\u044c\u044e\u0442\u0441\u044f \u0434\u0432\u0430 \u0438\u043d\u0434\u0443\u0441\u0442\u0440\u0438\u0430\u043b\u044c\u043d\u044b\u0445 \u000d\u000a\u043c\u0435\u0433\u0430\u043a\u043b\u0430\u0441\u0442\u0435\u0440\u0430 \u2014 \u041c\u043e\u0440\u043e\u0432\u0430\u043b\u0438 \u0438 \u0412\u0435\u0434\u0430 \u0411\u044d\u0439.\u000a\u000d\u000a\u0412 2014-\u043c \u0437\u0430\u043b\u043e\u0436\u0435\u043d \u043f\u0440\u043e\u043c\u044b\u0448\u043b\u0435\u043d\u043d\u044b\u0439 \u043f\u0430\u0440\u043a \u041c\u043e\u0440\u043e\u0432\u0430\u043b\u0438 \u000d\u000a\u0432 \u0418\u043d\u0434\u043e\u043d\u0435\u0437\u0438\u0438 (IMIP).\u000a\u000d\u000a\u0412 2020 \u0433\u043e\u0434\u0443 \u0432 \u0438\u043d\u0434\u0443\u0441\u0442\u0440\u0438\u0430\u043b\u044c\u043d\u043e\u043c \u043f\u0430\u0440\u043a\u0435 \u0412\u0435\u0434\u0430 \u0411\u044d\u0439 (IWIP) \u000d\u000a\u0432 \u0418\u043d\u0434\u043e\u043d\u0435\u0437\u0438\u0438 \u0432\u044b\u0441\u0442\u0440\u043e\u0435\u043d\u0430 \u043f\u0435\u0440\u0432\u0430\u044f \u0432 \u043c\u0438\u0440\u0435 \u043f\u043e\u043b\u043d\u043e\u0441\u0442\u044c\u044e \u000d\u000a\u0438\u043d\u0442\u0435\u0433\u0440\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u0430\u044f \u0442\u0435\u0445\u043d\u043e\u043b\u043e\u0433\u0438\u0447\u0435\u0441\u043a\u0430\u044f \u0446\u0435\u043f\u043e\u0447\u043a\u0430, \u0432\u043a\u043b\u044e\u0447\u0430\u044e\u0449\u0430\u044f \u000d\u000a\u0434\u043e\u0431\u044b\u0447\u0443 \u043d\u0438\u043a\u0435\u043b\u044f, \u0432\u044b\u043f\u043b\u0430\u0432\u043a\u0443 \u043d\u0438\u043a\u0435\u043b\u0435\u0432\u043e\u0433\u043e \u0447\u0443\u0433\u0443\u043d\u0430 \u0438 \u0444\u0435\u0440\u0440\u043e\u0445\u0440\u043e\u043c\u0430, \u000d\u000a\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u043e \u043d\u0435\u0440\u0436\u0430\u0432\u0435\u044e\u0449\u0435\u0439 \u0441\u0442\u0430\u043b\u0438, \u043f\u0440\u043e\u043a\u0430\u0442, \u0430 \u0442\u0430\u043a\u0436\u0435 \u000d\u000a\u0438\u0437\u0433\u043e\u0442\u043e\u0432\u043b\u0435\u043d\u0438\u0435 \u043c\u0430\u0442\u0435\u0440\u0438\u0430\u043b\u043e\u0432 \u0434\u043b\u044f \u043d\u043e\u0432\u043e\u0439 \u044d\u043d\u0435\u0440\u0433\u0435\u0442\u0438\u043a\u0438 \u0438\u0437 \u043d\u0438\u043a\u0435\u043b\u044f.\u000a\u000d\u000a\u0412 2021-\u043c Tsingshan \u0441\u0442\u0430\u043d\u043e\u0432\u0438\u0442\u0441\u044f \u043a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0438\u043c \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u0442\u0435\u043b\u0435\u043c \u000d\u000a\u043d\u0438\u043a\u0435\u043b\u044f \u0432 \u0418\u043d\u0434\u043e\u043d\u0435\u0437\u0438\u0438.\u000a\u000d\u000a\u041a 2025 \u0433\u043e\u0434\u0443 \u0432 \u043f\u0440\u043e\u043c\u043f\u0430\u0440\u043a\u0435 \u041c\u043e\u0440\u043e\u0432\u0430\u043b\u0438 \u0434\u0435\u0439\u0441\u0442\u0432\u0443\u044e\u0442 11 \u043f\u043b\u0430\u0432\u0438\u043b\u044c\u043d\u044b\u0445 \u000d\u000a\u043f\u0440\u0435\u0434\u043f\u0440\u0438\u044f\u0442\u0438\u0439, \u043d\u0430 \u043d\u0438\u0445 \u0440\u0430\u0431\u043e\u0442\u0430\u044e\u0442 85 \u0442\u044b\u0441. \u0447\u0435\u043b\u043e\u0432\u0435\u043a, \u043e\u0431\u044a\u0435\u043c \u000d\u000a\u0438\u043d\u0432\u0435\u0441\u0442\u0438\u0446\u0438\u0439 \u043f\u0440\u0435\u0432\u044b\u0441\u0438\u043b $34 \u043c\u043b\u0440\u0434.\u000d\u000a\u0421\u0444\u0435\u0440\u0430 \u0434\u0435\u044f\u0442\u0435\u043b\u044c\u043d\u043e\u0441\u0442\u0438 \u0438 \u043f\u043e\u0437\u0438\u0446\u0438\u0438 \u0432 \u043e\u0442\u0440\u0430\u0441\u043b\u0438\u000d\u000a\u0418\u0441\u0442\u043e\u0440\u0438\u044f \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438\u000d\u000a\u0418\u043d\u0434\u043e\u043d\u0435\u0437\u0438\u044f: \u043a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0438\u0439 \u043d\u0438\u043a\u0435\u043b\u0435\u0432\u044b\u0439 \u043a\u043b\u0430\u0441\u0442\u0435\u0440 \u0432 \u043c\u0438\u0440\u0435\u000a\u000d\u000aTsingshan \u044f\u0432\u043b\u044f\u0435\u0442\u0441\u044f \u0433\u043b\u0430\u0432\u043d\u044b\u043c \u0438\u043d\u0432\u0435\u0441\u0442\u043e\u0440\u043e\u043c \u0438 \u043e\u0440\u0433\u0430\u043d\u0438\u0437\u0430\u0442\u043e\u0440\u043e\u043c \u000d\u000a\u0438\u043d\u0434\u0443\u0441\u0442\u0440\u0438\u0430\u043b\u044c\u043d\u044b\u0445 \u043c\u0435\u0433\u0430\u043a\u043b\u0430\u0441\u0442\u0435\u0440\u043e\u0432 \u0412\u0435\u0434\u0430 \u0411\u044d\u0439 \u0438 \u041c\u043e\u0440\u043e\u0432\u0430\u043b\u0438. \u000d\u000a\u0412\u044b\u0441\u0442\u0440\u043e\u0435\u043d\u044b \u043f\u043e\u043b\u043d\u044b\u0435 \u0446\u0435\u043f\u043e\u0447\u043a\u0438: \u043e\u0442 \u0434\u043e\u0431\u044b\u0447\u0438 \u0438 \u043e\u0431\u043e\u0433\u0430\u0449\u0435\u043d\u0438\u044f \u000d\u000a\u043d\u0438\u043a\u0435\u043b\u044f, \u0445\u0440\u043e\u043c\u0430, \u0436\u0435\u043b\u0435\u0437\u0430 \u0434\u043e \u043a\u043e\u043c\u043f\u043b\u0435\u043a\u0441\u043d\u043e\u0439 \u043f\u0435\u0440\u0435\u0440\u0430\u0431\u043e\u0442\u043a\u0438 \u000d\u000a\u0438 \u043f\u043e\u043b\u0443\u0447\u0435\u043d\u0438\u044f \u0432\u044b\u0441\u043e\u043a\u043e\u0442\u0435\u0445\u043d\u043e\u043b\u043e\u0433\u0438\u0447\u043d\u043e\u0433\u043e \u0441\u044b\u0440\u044c\u044f.\u000a\u000d\u000a\u042d\u0442\u0430 \u043c\u043e\u0434\u0435\u043b\u044c \u0437\u0430\u0434\u0430\u043b\u0430 \u043d\u043e\u0432\u044b\u0439 \u0441\u0442\u0430\u043d\u0434\u0430\u0440\u0442 \u0432\u0435\u0440\u0442\u0438\u043a\u0430\u043b\u044c\u043d\u043e\u0439 \u000d\u000a\u0438\u043d\u0442\u0435\u0433\u0440\u0430\u0446\u0438\u0438. \u0418\u043d\u0434\u043e\u043d\u0435\u0437\u0438\u044f, \u0437\u0430\u043f\u0440\u0435\u0442\u0438\u0432 \u044d\u043a\u0441\u043f\u043e\u0440\u0442 \u0440\u0443\u0434\u044b, \u0444\u0430\u043a\u0442\u0438\u0447\u0435\u0441\u043a\u0438 \u000d\u000a\u0441\u0434\u0435\u043b\u0430\u043b\u0430 Tsingshan \u0433\u043b\u0430\u0432\u043d\u044b\u043c\u0438 \u0432\u043e\u0440\u043e\u0442\u0430\u043c\u0438 \u043c\u0438\u0440\u043e\u0432\u043e\u0433\u043e \u043d\u0438\u043a\u0435\u043b\u0435\u0432\u043e\u0433\u043e \u000d\u000a\u0431\u0438\u0437\u043d\u0435\u0441\u0430. \u041c\u043d\u043e\u0433\u0438\u0435 \u043a\u0438\u0442\u0430\u0439\u0441\u043a\u0438\u0435 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u0442\u0435\u043b\u0438 \u0441\u0442\u0430\u043b\u0438 \u000d\u000a\u0440\u0435\u0437\u0438\u0434\u0435\u043d\u0442\u0430\u043c\u0438 \u0432 \u043a\u043b\u0430\u0441\u0442\u0435\u0440\u0430\u0445 \u0412\u0435\u0434\u0430 \u0411\u044d\u0439 \u0438 \u041c\u043e\u0440\u043e\u0432\u0430\u043b\u0438, \u043a\u043e\u0442\u043e\u0440\u044b\u0435 \u000d\u000a\u0441\u0442\u0440\u043e\u0438\u043b\u0430 Tsingshan.\u000d\u000a\u0417\u0438\u043c\u0431\u0430\u0431\u0432\u0435: \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u043e \u0444\u0435\u0440\u0440\u043e\u0445\u0440\u043e\u043c\u0430\u000a\u000d\u000a\u041f\u0435\u0440\u0432\u044b\u0435 \u0430\u043a\u0442\u0438\u0432\u044b \u043f\u0440\u0438\u043e\u0431\u0440\u0435\u0442\u0435\u043d\u044b \u0432 2012 \u0433\u043e\u0434\u0443. \u0412 2024-\u043c \u000d\u000a\u043d\u0430 \u0437\u0430\u0432\u043e\u0434\u0435 Manhize \u0437\u0430\u043f\u0443\u0449\u0435\u043d\u0430 \u043f\u0435\u0440\u0432\u0430\u044f \u043e\u0447\u0435\u0440\u0435\u0434\u044c \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0430.\u000d\u000a\u0413\u043b\u043e\u0431\u0430\u043b\u044c\u043d\u0430\u044f \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0435\u043d\u043d\u0430\u044f \u0441\u0435\u0442\u044c\u000a\u000d\u000a\u0412\u0441\u0435\u0433\u043e, \u0441 \u0443\u0447\u0435\u0442\u043e\u043c \u043f\u043b\u043e\u0449\u0430\u0434\u043e\u043a \u0432 \u0424\u0443\u0446\u0437\u044f\u043d\u0435, \u0413\u0443\u0430\u043d\u0434\u0443\u043d\u0435 \u0438 \u0427\u0436\u044d\u0446\u0437\u044f\u043d\u0435, \u000d\u000a\u0430 \u0442\u0430\u043a\u0436\u0435 \u0441 \u0437\u0430\u0440\u0443\u0431\u0435\u0436\u043d\u044b\u043c\u0438 \u0430\u043a\u0442\u0438\u0432\u0430\u043c\u0438 \u0432 \u0418\u043d\u0434\u0438\u0438 \u0438 \u0421\u0428\u0410, \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u000d\u000a\u0441\u0444\u043e\u0440\u043c\u0438\u0440\u043e\u0432\u0430\u043b\u0430 \u0432\u043e\u0441\u0435\u043c\u044c \u043a\u0440\u0443\u043f\u043d\u044b\u0445 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0445 \u0431\u0430\u0437. \u000d\u000a\u0428\u0442\u0430\u0442 \u2014 \u0431\u043e\u043b\u0435\u0435 185 \u0442\u044b\u0441. \u0441\u043e\u0442\u0440\u0443\u0434\u043d\u0438\u043a\u043e\u0432. \u0413\u0435\u043e\u0433\u0440\u0430\u0444\u0438\u044f \u043f\u0440\u0438\u0441\u0443\u0442\u0441\u0442\u0432\u0438\u044f \u2014 \u000d\u000a\u0441\u0432\u044b\u0448\u0435 100 \u0441\u0442\u0440\u0430\u043d \u0438 \u0440\u0435\u0433\u0438\u043e\u043d\u043e\u0432.\u000d\u000a\u0422\u0435\u0445\u043d\u043e\u043b\u043e\u0433\u0438\u044f \u043a\u043e\u043d\u0432\u0435\u0440\u0442\u0430\u0446\u0438\u0438 NPI \u0432 \u043d\u0438\u043a\u0435\u043b\u0435\u0432\u044b\u0439 \u0448\u0442\u0435\u0439\u043d (2021 \u0433\u043e\u0434)\u000a\u000d\u000aTsingshan \u043f\u0435\u0440\u0432\u043e\u0439 \u0440\u0430\u0437\u0440\u0430\u0431\u043e\u0442\u0430\u043b\u0430 \u043c\u0435\u0442\u043e\u0434 \u043f\u0440\u0435\u043e\u0431\u0440\u0430\u0437\u043e\u0432\u0430\u043d\u0438\u044f \u000d\u000a\u043d\u0438\u043a\u0435\u043b\u0435\u0432\u043e\u0433\u043e \u0447\u0443\u0433\u0443\u043d\u0430 \u0432 \u0432\u044b\u0441\u043e\u043a\u043e\u043a\u0430\u0447\u0435\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0439 \u043d\u0438\u043a\u0435\u043b\u0435\u0432\u044b\u0439 \u000d\u000a\u0448\u0442\u0435\u0439\u043d, \u0438\u0437 \u043a\u043e\u0442\u043e\u0440\u043e\u0433\u043e \u043c\u043e\u0436\u043d\u043e \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u0442\u044c:\u000d\u000a\u0414\u043e \u044d\u0442\u043e\u0433\u043e \u043d\u0430 \u0440\u044b\u043d\u043a\u0435 \u043d\u0435 \u0441\u0443\u0449\u0435\u0441\u0442\u0432\u043e\u0432\u0430\u043b\u043e \u043c\u0435\u0442\u043e\u0434\u0430 \u0430\u043f\u0433\u0440\u0435\u0439\u0434\u0430 \u000d\u000a\u043d\u0438\u0437\u043a\u043e\u0441\u043e\u0440\u0442\u043d\u043e\u0433\u043e \u043d\u0438\u043a\u0435\u043b\u044f \u0434\u043e \u043f\u0440\u043e\u0434\u0443\u043a\u0446\u0438\u0438 \u0432\u044b\u0441\u043e\u043a\u043e\u0433\u043e \u043a\u0430\u0447\u0435\u0441\u0442\u0432\u0430. \u000d\u000aTsingshan \u0435\u0449\u0435 \u0440\u0430\u0437 \u043f\u043e\u043c\u0435\u043d\u044f\u043b\u0430 \u043f\u0440\u0430\u0432\u0438\u043b\u0430 \u0438\u0433\u0440\u044b \u0432 \u043e\u0442\u0440\u0430\u0441\u043b\u0438.\u000d\u000a\u041a\u043b\u044e\u0447\u0435\u0432\u044b\u0435 \u043f\u0440\u043e\u0435\u043a\u0442\u044b\u000d\u000a\u0441\u0443\u043b\u044c\u0444\u0430\u0442 \u043d\u0438\u043a\u0435\u043b\u044f \u0430\u043a\u043a\u0443\u043c\u0443\u043b\u044f\u0442\u043e\u0440\u043d\u043e\u0433\u043e \u043a\u0430\u0447\u0435\u0441\u0442\u0432\u0430;\u000a\u000d\u000a\u0440\u0430\u0444\u0438\u043d\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0439 \u043d\u0438\u043a\u0435\u043b\u044c.","9/17\u000d\u000aTsingshan \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u0438\u0440\u0443\u0435\u0442 \u043e\u043a\u043e\u043b\u043e 30% \u043c\u043e\u0449\u043d\u043e\u0441\u0442\u0435\u0439 \u043f\u043e \u0434\u043e\u0431\u044b\u0447\u0435 \u000d\u000a\u043d\u0438\u043a\u0435\u043b\u044f \u0432 \u0418\u043d\u0434\u043e\u043d\u0435\u0437\u0438\u0438.\u000a\u000d\u000a\u041a 2025 \u0433\u043e\u0434\u0443 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u0443\u0432\u0435\u043b\u0438\u0447\u0438\u0442\u044c \u0433\u043e\u0434\u043e\u0432\u043e\u0439 \u043e\u0431\u044a\u0435\u043c \u000d\u000a\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0430 \u0432\u044b\u0441\u043e\u043a\u043e\u043a\u0430\u0447\u0435\u0441\u0442\u0432\u0435\u043d\u043d\u043e\u0433\u043e \u043d\u0438\u043a\u0435\u043b\u0435\u0432\u043e\u0433\u043e \u0448\u0442\u0435\u0439\u043d\u0430 \u000d\u000a\u0434\u043e 1 \u043c\u043b\u043d \u0442\u043e\u043d\u043d, \u0447\u0442\u043e \u0441\u043e\u0441\u0442\u0430\u0432\u043b\u044f\u0435\u0442 \u0431\u043e\u043b\u0435\u0435 40% \u043c\u0438\u0440\u043e\u0432\u043e\u0433\u043e \u000d\u000a\u043f\u0440\u0435\u0434\u043b\u043e\u0436\u0435\u043d\u0438\u044f.\u000d\u000a\u043f\u043b\u0430\u043d\u0438\u0440\u0443\u0435\u0442 \u000d\u000aTsingshan \u0443\u043f\u0440\u0430\u0432\u043b\u044f\u0435\u0442 \u0432\u043e\u0441\u0435\u043c\u044c\u044e \u043a\u0440\u0443\u043f\u043d\u044b\u043c\u0438 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u043c\u0438 \u000d\u000a\u0446\u0435\u043d\u0442\u0440\u0430\u043c\u0438, \u0432\u043a\u043b\u044e\u0447\u0430\u044e\u0449\u0438\u043c\u0438:\u000d\u000a\u041f\u043e\u043c\u0438\u043c\u043e \u043a\u043b\u0430\u0441\u0441\u0438\u0447\u0435\u0441\u043a\u0438\u0445, \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u043f\u043e\u0441\u0442\u0430\u0432\u043b\u044f\u0435\u0442 \u0438\u043d\u043d\u043e\u0432\u0430\u0446\u0438\u043e\u043d\u043d\u044b\u0435 \u000d\u000a\u043c\u0430\u0442\u0435\u0440\u0438\u0430\u043b\u044b, \u0442\u0430\u043a\u0438\u0435 \u043a\u0430\u043a \u0443\u043b\u044c\u0442\u0440\u0430\u0442\u043e\u043d\u043a\u0438\u0435 \u0441\u0442\u0430\u043b\u044c\u043d\u044b\u0435 \u043b\u0438\u0441\u0442\u044b \u0434\u043b\u044f \u000d\u000a\u0441\u043a\u043b\u0430\u0434\u043d\u044b\u0445 \u0442\u0435\u043b\u0435\u0444\u043e\u043d\u043e\u0432 \u0438 \u0441\u043f\u043b\u0430\u0432\u044b \u0441 \u043d\u0438\u0437\u043a\u0438\u043c \u0441\u043e\u0434\u0435\u0440\u0436\u0430\u043d\u0438\u0435\u043c \u043d\u0438\u043a\u0435\u043b\u044f \u000d\u000a\u0434\u043b\u044f \u044d\u043b\u0435\u043a\u0442\u0440\u043e\u043c\u043e\u0431\u0438\u043b\u0435\u0439.\u000d\u000a\u0421\u0430\u043d\u043a\u0446\u0438\u0438 \u0421\u0428\u0410 \u0443\u0434\u0430\u043b\u043e\u0441\u044c \u0441\u043c\u044f\u0433\u0447\u0438\u0442\u044c, \u0441\u043e\u0437\u0434\u0430\u0432 \u0441\u043e\u0432\u043c\u0435\u0441\u0442\u043d\u044b\u0435 \u000d\u000a\u043f\u0440\u0435\u0434\u043f\u0440\u0438\u044f\u0442\u0438\u044f \u0432 \u0418\u043d\u0434\u043e\u043d\u0435\u0437\u0438\u0438 (\u043d\u0430\u043f\u0440\u0438\u043c\u0435\u0440, \u0441 \u0444\u0440\u0430\u043d\u0446\u0443\u0437\u0441\u043a\u043e\u0439 \u000d\u000a\u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0435\u0439 Eramet \u0438 \u044e\u0436\u043d\u043e\u043a\u043e\u0440\u0435\u0439\u0441\u043a\u043e\u0439 POSCO), \u0447\u0442\u043e\u0431\u044b \u000d\u000a\u043e\u0431\u0435\u0441\u043f\u0435\u0447\u0438\u0442\u044c \u0434\u043e\u0441\u0442\u0443\u043f \u0441\u0432\u043e\u0435\u0439 \u043f\u0440\u043e\u0434\u0443\u043a\u0446\u0438\u0438 \u043d\u0430 \u0440\u044b\u043d\u043a\u0438 \u0421\u0428\u0410 \u000d\u000a\u0438 \u0415\u0432\u0440\u043e\u043f\u044b.    \u000a\u000d\u000a\u041a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u043f\u0435\u0440\u0435\u0436\u0438\u043b\u0430 \u0446\u0435\u043d\u043e\u0432\u044b\u0435 \u043a\u043e\u043b\u0435\u0431\u0430\u043d\u0438\u044f 2020\u20132021 \u0433\u043e\u0434\u043e\u0432, \u000d\u000a\u0441\u043e\u0445\u0440\u0430\u043d\u0438\u043b\u0430 \u0440\u043e\u0441\u0442 \u0438 \u0443\u0441\u0438\u043b\u0438\u043b\u0430 \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044c \u043d\u0430\u0434 \u043a\u043b\u044e\u0447\u0435\u0432\u044b\u043c\u0438 \u000d\u000a\u0441\u044b\u0440\u044c\u0435\u0432\u044b\u043c\u0438 \u0431\u0430\u0437\u0430\u043c\u0438, \u0447\u0442\u043e \u0438 \u043e\u0431\u0435\u0441\u043f\u0435\u0447\u0438\u043b\u043e \u0440\u0435\u043a\u043e\u0440\u0434\u043d\u044b\u0435 \u043f\u043e\u043a\u0430\u0437\u0430\u0442\u0435\u043b\u0438 \u000d\u000a\u0432 2024 \u0433\u043e\u0434\u0443.\u000d\u000a\u041d\u0435\u0440\u0436\u0430\u0432\u0435\u044e\u0449\u0430\u044f \u0441\u0442\u0430\u043b\u044c \u2014 16 \u043c\u043b\u043d \u0442\u043e\u043d\u043d.\u000a\u000d\u000a\u0423\u0433\u043b\u0435\u0440\u043e\u0434\u0438\u0441\u0442\u0430\u044f \u0441\u0442\u0430\u043b\u044c \u2014 7 \u043c\u043b\u043d \u0442\u043e\u043d\u043d.\u000a\u000d\u000a\u0424\u0435\u0440\u0440\u043e\u043d\u0438\u043a\u0435\u043b\u044c \u2014 9 \u043c\u043b\u043d \u0442\u043e\u043d\u043d.\u000a\u000d\u000a\u0413\u0438\u0434\u0440\u0430\u0442\u044b \u043d\u0438\u043a\u0435\u043b\u044f \u2014 90 \u0442\u044b\u0441. \u0442\u043e\u043d\u043d.\u000d\u000a\u0434\u043e\u0431\u044b\u0447\u0443 \u043d\u0438\u043a\u0435\u043b\u044f \u0438 \u0445\u0440\u043e\u043c\u0430;\u000a\u000d\u000a\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u043e:\u000d\u000aNPI, \u0444\u0435\u0440\u0440\u043e\u0445\u0440\u043e\u043c\u0430 \u0438 \u043d\u0435\u0440\u0436\u0430\u0432\u0435\u044e\u0449\u0435\u0439 \u0441\u0442\u0430\u043b\u0438,\u000a\u000d\u000a\u0445\u043e\u043b\u043e\u0434\u043d\u043e\u043a\u0430\u0442\u0430\u043d\u043e\u0439 \u0438 \u0433\u043e\u0440\u044f\u0447\u0435\u043a\u0430\u0442\u0430\u043d\u043e\u0439 \u0441\u0442\u0430\u043b\u0438,\u000a\u000d\u000a\u043c\u0430\u0442\u0435\u0440\u0438\u0430\u043b\u043e\u0432 \u0434\u043b\u044f \u0430\u043a\u043a\u0443\u043c\u0443\u043b\u044f\u0442\u043e\u0440\u043e\u0432 \u0438 \u043d\u043e\u0432\u043e\u0439 \u044d\u043d\u0435\u0440\u0433\u0435\u0442\u0438\u043a\u0438.\u000d\u000a\u0412\u043e\u043b\u0430\u0442\u0438\u043b\u044c\u043d\u043e\u0441\u0442\u044c \u0433\u043b\u043e\u0431\u0430\u043b\u044c\u043d\u044b\u0445 \u0446\u0435\u043f\u043e\u0447\u0435\u043a \u043f\u043e\u0441\u0442\u0430\u0432\u043e\u043a.\u000a\u000d\u000a\u0420\u0435\u0437\u043a\u0438\u0435 \u043a\u043e\u043b\u0435\u0431\u0430\u043d\u0438\u044f \u0446\u0435\u043d \u043d\u0430 \u043d\u0438\u043a\u0435\u043b\u044c \u0438 \u043d\u0435\u0440\u0436\u0430\u0432\u0435\u044e\u0449\u0443\u044e \u0441\u0442\u0430\u043b\u044c.\u000a\u000d\u000a\u0420\u0430\u0441\u0442\u0443\u0449\u0438\u0435 \u0442\u0440\u0435\u0431\u043e\u0432\u0430\u043d\u0438\u044f \u043a \u043a\u0430\u0447\u0435\u0441\u0442\u0432\u0443 \u043c\u0430\u0442\u0435\u0440\u0438\u0430\u043b\u043e\u0432 \u0434\u043b\u044f \u043d\u043e\u0432\u043e\u0439 \u000d\u000a\u044d\u043d\u0435\u0440\u0433\u0435\u0442\u0438\u043a\u0438.\u000a\u000d\u000a\u041d\u0435\u043e\u0431\u0445\u043e\u0434\u0438\u043c\u043e\u0441\u0442\u044c \u0437\u0430\u0449\u0438\u0449\u0430\u0442\u044c \u0440\u0435\u043d\u0442\u0430\u0431\u0435\u043b\u044c\u043d\u043e\u0441\u0442\u044c \u0432 \u0443\u0441\u043b\u043e\u0432\u0438\u044f\u0445 \u000d\u000a\u0432\u044b\u0441\u043e\u043a\u043e\u0439 \u043a\u043e\u043d\u043a\u0443\u0440\u0435\u043d\u0446\u0438\u0438.\u000d\u000a\u0412\u044b\u0440\u0443\u0447\u043a\u0430 \u0432 2024 \u0433\u043e\u0434\u0443 \u2014 $56,6 \u043c\u043b\u0440\u0434.\u000d\u000a\u0424\u0438\u043d\u0430\u043d\u0441\u043e\u0432\u044b\u0435 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u044b\u000d\u000aTsingshan Holding Group Co., Ltd. (\u9752\u5c71\u63a7\u80a1\u96c6\u56e2\u6709\u9650\u516c\u53f8)\u000d\u000a\u0420\u0435\u0441\u0443\u0440\u0441\u043d\u0430\u044f \u0431\u0430\u0437\u0430 \u0438 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0435\u2028\u000d\u000a\u043c\u043e\u0449\u043d\u043e\u0441\u0442\u0438\u000d\u000a\u041f\u0440\u043e\u0431\u043b\u0435\u043c\u044b \u0438 \u0432\u044b\u0437\u043e\u0432\u044b\u000d\u000a\u0428\u0442\u0430\u0431 \u043a\u0432\u0430\u0440\u0442\u0438\u0440\u0430 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438","10/17\u000d\u000aJinchuan\u2028\u000d\u000aGroup Co., Ltd.\u000d\u000a(\u91d1\u5ddd\u96c6\u56e2\u80a1\u4efd\u6709\u9650\u516c\u53f8)\u000d\u000a\u0428\u0442\u0430\u0431-\u043a\u0432\u0430\u0440\u0442\u0438\u0440\u0430\u000d\u000a\u0421\u0430\u0439\u0442\u000d\u000a\u0426\u0437\u0438\u043d\u044c\u0447\u0430\u043d, \u043f\u0440\u043e\u0432\u0438\u043d\u0446\u0438\u044f \u000d\u000a\u0413\u0430\u043d\u044c\u0441\u0443\u000d\u000aen.jnmc.com\u000d\u000a\u0413\u043e\u0441\u0443\u0434\u0430\u0440\u0441\u0442\u0432\u0435\u043d\u043d\u0430\u044f \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u041a\u0438\u0442\u0430\u044f. \u041e\u0441\u043d\u043e\u0432\u043d\u0430\u044f \u043f\u0440\u043e\u0434\u0443\u043a\u0446\u0438\u044f: \u000d\u000a\u043d\u0438\u043a\u0435\u043b\u044c, \u043c\u0435\u0434\u044c, \u043a\u043e\u0431\u0430\u043b\u044c\u0442, \u0437\u043e\u043b\u043e\u0442\u043e, \u0441\u0435\u0440\u0435\u0431\u0440\u043e, \u043c\u0435\u0442\u0430\u043b\u043b\u044b \u043f\u043b\u0430\u0442\u0438\u043d\u043e\u0432\u043e\u0439 \u000d\u000a\u0433\u0440\u0443\u043f\u043f\u044b, \u0441\u043e\u0432\u0440\u0435\u043c\u0435\u043d\u043d\u044b\u0435 \u043c\u0430\u0442\u0435\u0440\u0438\u0430\u043b\u044b \u0434\u043b\u044f \u0430\u043a\u043a\u0443\u043c\u0443\u043b\u044f\u0442\u043e\u0440\u043e\u0432 \u000d\u000a\u0438 \u0445\u0438\u043c\u0438\u0447\u0435\u0441\u043a\u0438\u0435 \u043f\u0440\u043e\u0434\u0443\u043a\u0442\u044b.\u000a\u000d\u000aJinchuan \u0437\u0430\u043d\u0438\u043c\u0430\u0435\u0442 2-\u0435 \u043c\u0435\u0441\u0442\u043e \u0432 \u043c\u0438\u0440\u0435 \u043f\u043e \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0443 \u043d\u0438\u043a\u0435\u043b\u044f, \u000d\u000a4-\u0435 \u2014 \u043f\u043e \u043a\u043e\u0431\u0430\u043b\u044c\u0442\u0443, 1-\u0435 \u043c\u0435\u0441\u0442\u043e \u0432 \u0410\u0437\u0438\u0438 \u043f\u043e \u043c\u0435\u0442\u0430\u043b\u043b\u0430\u043c \u043f\u043b\u0430\u0442\u0438\u043d\u043e\u0432\u043e\u0439 \u000d\u000a\u0433\u0440\u0443\u043f\u043f\u044b \u0438 3-\u0435 \u043c\u0435\u0441\u0442\u043e \u0432 \u041a\u0438\u0442\u0430\u0435 \u043f\u043e \u043c\u0435\u0434\u0438. \u0412 2025 \u0433\u043e\u0434\u0443 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u000d\u000a\u0434\u043e\u0431\u0438\u043b\u0430\u0441\u044c 235-\u0433\u043e \u043c\u0435\u0441\u0442\u0430 \u0432 Fortune Global 500 \u0438 59-\u0433\u043e \u043c\u0435\u0441\u0442\u0430 \u000d\u000a\u0441\u0440\u0435\u0434\u0438 500 \u043a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0438\u0445 \u043f\u0440\u0435\u0434\u043f\u0440\u0438\u044f\u0442\u0438\u0439 \u041a\u0438\u0442\u0430\u044f.\u000d\u000a\u041a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u043e\u0442\u0441\u0447\u0435\u0442 \u0441 1958 \u0433\u043e\u0434\u0430, \u043a\u043e\u0433\u0434\u0430 \u0432 \u0440\u0430\u0439\u043e\u043d\u0435 \u0433\u043e\u0440\u043e\u0434\u0430 \u000d\u000a\u0426\u0437\u0438\u043d\u044c\u0447\u0430\u043d \u043e\u0442\u043a\u0440\u044b\u043b\u0438 \u0431\u043e\u043b\u044c\u0448\u043e\u0435 \u043c\u0435\u0434\u043d\u043e-\u043d\u0438\u043a\u0435\u043b\u0435\u0432\u043e\u0435 \u043c\u0435\u0441\u0442\u043e\u0440\u043e\u0436\u0434\u0435\u043d\u0438\u0435. \u000d\u000a\u0412 \u0433\u0435\u043e\u043b\u043e\u0433\u043e\u0440\u0430\u0437\u0432\u0435\u0434\u043a\u0435 \u0443\u0447\u0430\u0441\u0442\u0432\u043e\u0432\u0430\u043b\u0438 \u0441\u043e\u0432\u0435\u0442\u0441\u043a\u0438\u0435 \u0441\u043f\u0435\u0446\u0438\u0430\u043b\u0438\u0441\u0442\u044b.\u000a\u000d\u000a\u0412 1959 \u0433\u043e\u0434\u0443 \u043f\u043e\u044f\u0432\u0438\u043b\u0430\u0441\u044c Northwest China Metallurgical \u000d\u000aConstruction Company \u0438 \u043d\u0430\u0447\u0430\u043b\u043e\u0441\u044c \u043f\u0440\u043e\u043c\u044b\u0448\u043b\u0435\u043d\u043d\u043e\u0435 \u043e\u0441\u0432\u043e\u0435\u043d\u0438\u0435 \u000d\u000a\u043c\u0435\u0441\u0442\u043e\u0440\u043e\u0436\u0434\u0435\u043d\u0438\u044f. \u0412\u044b\u0441\u043e\u043a\u043e\u0433\u043e\u0440\u043d\u043e\u0435 \u0440\u0430\u0441\u043f\u043e\u043b\u043e\u0436\u0435\u043d\u0438\u0435 \u0437\u0430\u0441\u0442\u0430\u0432\u0438\u043b\u043e \u000d\u000a\u0441\u0442\u0440\u043e\u0438\u0442\u044c \u0441\u043e\u0431\u0441\u0442\u0432\u0435\u043d\u043d\u0443\u044e \u0436\u0435\u043b\u0435\u0437\u043d\u0443\u044e \u0434\u043e\u0440\u043e\u0433\u0443.\u000a\u000d\u000a\u0412 1964 \u0433\u043e\u0434\u0443 \u0437\u0430\u043f\u0443\u0449\u0435\u043d\u0430 \u043f\u0435\u0440\u0432\u0430\u044f \u043b\u0438\u043d\u0438\u044f \u043f\u043e \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0443 \u043d\u0438\u043a\u0435\u043b\u044f.\u000a\u000d\u000a1965 \u0433\u043e\u0434 \u2014 \u043e\u043f\u044b\u0442\u043d\u043e\u0435 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u043e \u043c\u0435\u0442\u0430\u043b\u043b\u043e\u0432 \u043f\u043b\u0430\u0442\u0438\u043d\u043e\u0432\u043e\u0439 \u000d\u000a\u0433\u0440\u0443\u043f\u043f\u044b.\u000a\u000d\u000a1966 \u0433\u043e\u0434 \u2014 \u0437\u0430 \u0440\u0430\u0431\u043e\u0442\u0430\u043c\u0438 \u043f\u0440\u0438\u0435\u0445\u0430\u043b \u043b\u0438\u0447\u043d\u043e \u043d\u0430\u0431\u043b\u044e\u0434\u0430\u0442\u044c \u0414\u044d\u043d \u0421\u044f\u043e\u043f\u0438\u043d.\u000a\u000d\u000a\u0412 2001 \u0433\u043e\u0434\u0443 \u0431\u044b\u043b\u0430 \u043e\u0441\u043d\u043e\u0432\u0430\u043d\u0430 Jinchuan Group Co., Ltd, \u043f\u043e\u0441\u0442\u0440\u043e\u0435\u043d \u000d\u000a\u0441\u043e\u0431\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0439 \u0442\u0435\u0445\u043d\u043e\u043f\u0430\u0440\u043a \u0432 \u0433. \u041b\u0430\u043d\u044c\u0447\u0436\u043e\u0443 \u0438 \u043d\u0430\u0447\u0430\u043b\u043e\u0441\u044c \u000d\u000a\u043f\u0440\u0438\u043e\u0431\u0440\u0435\u0442\u0435\u043d\u0438\u0435 \u0437\u0430\u0440\u0443\u0431\u0435\u0436\u043d\u044b\u0445 \u043c\u0435\u0441\u0442\u043e\u0440\u043e\u0436\u0434\u0435\u043d\u0438\u0439.\u000a\u000d\u000a2004  \u0433\u043e\u0434 \u2014 Jinchuan Group \u043f\u043e\u0441\u0442\u0440\u043e\u0438\u043b\u0430 \u0422\u0435\u0445\u043d\u043e\u043b\u043e\u0433\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u043f\u0430\u0440\u043a \u000d\u000a\u0426\u0437\u0438\u043d\u044c\u0447\u0443\u0430\u043d\u044c \u0432 \u041b\u0430\u043d\u044c\u0447\u0436\u043e\u0443.\u000a\u000d\u000a2005 \u0433\u043e\u0434 \u2014 \u0437\u0430\u043f\u0443\u0449\u0435\u043d\u043e \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u043e \u043d\u0430 \u043c\u0435\u0434\u043d\u043e-\u043a\u043e\u0431\u0430\u043b\u044c\u0442\u043e\u0432\u043e\u043c \u000d\u000a\u0437\u0430\u0432\u043e\u0434\u0435 \u0432 \u0414\u0420 \u041a\u043e\u043d\u0433\u043e.\u000d\u000a \u0432\u0435\u0434\u0435\u0442 Jinchuan \u0440\u0430\u0437\u0432\u0438\u0432\u0430\u0435\u0442 \u043c\u0435\u0436\u0434\u0443\u043d\u0430\u0440\u043e\u0434\u043d\u0443\u044e \u0441\u0435\u0442\u044c \u0434\u043e\u0431\u044b\u0432\u0430\u044e\u0449\u0438\u0445 \u000d\u000a\u0430\u043a\u0442\u0438\u0432\u043e\u0432:\u000d\u000a\u0412 2024 \u0433\u043e\u0434\u0443 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u043f\u0440\u0438\u043e\u0431\u0440\u0435\u043b\u0430 \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044c \u043d\u0430\u0434 \u043e\u0434\u043d\u0438\u043c \u000d\u000a\u0438\u0437 \u043a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0438\u0445 \u0432 \u041a\u0438\u0442\u0430\u0435 \u043d\u0438\u043a\u0435\u043b\u0435\u0432\u044b\u0445 \u043c\u0435\u0441\u0442\u043e\u0440\u043e\u0436\u0434\u0435\u043d\u0438\u0439 \u2014 \u000d\u000a\u0421\u044f\u0440\u0438\u0445\u0430\u043c\u0443 \u0432 \u043f\u0440\u043e\u0432\u0438\u043d\u0446\u0438\u0438 \u0426\u0438\u043d\u0445\u0430\u0439. \u0422\u0430\u043a\u0436\u0435 \u043e\u043d\u0430 \u0437\u0430\u044f\u0432\u043b\u044f\u043b\u0430 \u000d\u000a\u043e \u0433\u043e\u0442\u043e\u0432\u043d\u043e\u0441\u0442\u0438 \u0438\u043d\u0432\u0435\u0441\u0442\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u0432 \u043d\u0438\u043a\u0435\u043b\u044c-\u043a\u043e\u0431\u0430\u043b\u044c\u0442\u043e\u0432\u044b\u0435 \u0430\u043a\u0442\u0438\u0432\u044b \u000d\u000a\u041a\u0430\u0437\u0430\u0445\u0441\u0442\u0430\u043d\u0430.\u000a\u000d\u000a2008 \u0433\u043e\u0434 \u2014 \u0433\u0440\u0443\u043f\u043f\u0430 Jinchuan \u043a\u0443\u043f\u0438\u043b\u0430 \u043c\u0435\u0434\u043d\u044b\u0439 \u0440\u0443\u0434\u043d\u0438\u043a \u0411\u0430\u0443\u044d\u0440\u0430\u0447\u0438 \u000d\u000a\u0432 \u041c\u0435\u043a\u0441\u0438\u043a\u0435.\u000a\u000d\u000a2010 \u0433\u043e\u0434 \u2014 \u043f\u0435\u0440\u0435\u0437\u0430\u043f\u0443\u0449\u0435\u043d\u043e \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u043e \u043d\u0430 \u043d\u0438\u043a\u0435\u043b\u0435\u0432\u043e\u043c \u000d\u000a\u0440\u0443\u0434\u043d\u0438\u043a\u0435 \u041c\u0443\u043d\u0430\u043b\u0438 \u0432 \u0417\u0430\u043c\u0431\u0438\u0438. \u000d\u000a\u0421\u0444\u0435\u0440\u0430 \u0434\u0435\u044f\u0442\u0435\u043b\u044c\u043d\u043e\u0441\u0442\u0438 \u0438 \u043f\u043e\u0437\u0438\u0446\u0438\u0438 \u0432 \u043e\u0442\u0440\u0430\u0441\u043b\u0438\u000d\u000a\u0418\u0441\u0442\u043e\u0440\u0438\u044f \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438 \u041a\u043b\u044e\u0447\u0435\u0432\u044b\u0435 \u043f\u0440\u043e\u0435\u043a\u0442\u044b\u000d\u000a\u043d\u0438\u043a\u0435\u043b\u0435\u0432\u043e\u0435 \u043c\u0435\u0441\u0442\u043e\u0440\u043e\u0436\u0434\u0435\u043d\u0438\u0435 \u0412\u0430\u043d\u0438\u0430\u0442\u0430\u0440\u0430 \u041f\u0435\u0440\u0441\u0430\u0434\u0430 (\u0418\u043d\u0434\u043e\u043d\u0435\u0437\u0438\u044f);\u000a\u000d\u000a\u043d\u0438\u043a\u0435\u043b\u0435\u0432\u044b\u0439 \u0440\u0443\u0434\u043d\u0438\u043a \u041c\u0443\u043d\u0430\u043b\u0438 (\u0417\u0430\u043c\u0431\u0438\u044f);\u000a\u000d\u000a\u043f\u043b\u0430\u0442\u0438\u043d\u043e\u0432\u044b\u0439 \u0440\u0443\u0434\u043d\u0438\u043a \u0432 \u042e\u0410\u0420 (Sino-Steel Jinchuan);\u000a\u000d\u000a\u043c\u0435\u0434\u043d\u043e-\u043a\u043e\u0431\u0430\u043b\u044c\u0442\u043e\u0432\u044b\u0439 \u0440\u0443\u0434\u043d\u0438\u043a \u0420\u0443\u0432\u0430\u0441\u0438 \u0432 \u0414\u0420\u041a, \u0432\u044b\u0448\u0435\u0434\u0448\u0438\u0439 \u000d\u000a\u043d\u0430 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u043e \u0432 2023 \u0433\u043e\u0434\u0443;\u000a\u000d\u000a\u043f\u0440\u043e\u0435\u043a\u0442 \u0433\u043b\u0443\u0431\u043e\u043a\u043e\u0439 \u043f\u0435\u0440\u0435\u0440\u0430\u0431\u043e\u0442\u043a\u0438 \u041c\u0443\u0441\u043e\u043d\u043e\u0439 (\u041a\u043e\u043b\u0432\u0435\u0437\u0438, \u0414\u0420\u041a), \u000d\u000a\u043a\u043e\u0442\u043e\u0440\u044b\u0439 \u0432\u043a\u043b\u044e\u0447\u0430\u0435\u0442 \u0432 \u0441\u0435\u0431\u044f \u0434\u043e\u0431\u044b\u0447\u0443, \u043e\u0431\u043e\u0433\u0430\u0449\u0435\u043d\u0438\u0435 \u0438 \u043f\u043b\u0430\u0432\u043a\u0443 \u000d\u000a\u0438 \u0434\u043e\u043b\u0436\u0435\u043d \u0432\u044b\u0439\u0442\u0438 \u043d\u0430 \u043f\u043e\u043b\u043d\u0443\u044e \u043c\u043e\u0449\u043d\u043e\u0441\u0442\u044c \u0432 2026 \u0433\u043e\u0434\u0443.\u000d\u000a\u0420\u043e\u0431\u043e\u0442\u0438\u0437\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u0430\u044f \u043b\u0438\u043d\u0438\u044f","11/17\u000d\u000aJinchuan \u0432\u043b\u0430\u0434\u0435\u0435\u0442 \u043a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0438\u043c \u0432 \u041a\u0438\u0442\u0430\u0435 \u0438 \u0442\u0440\u0435\u0442\u044c\u0438\u043c \u0432 \u043c\u0438\u0440\u0435 \u000d\u000a\u043c\u0435\u0434\u043d\u043e-\u043d\u0438\u043a\u0435\u043b\u0435\u0432\u044b\u043c \u043c\u0435\u0441\u0442\u043e\u0440\u043e\u0436\u0434\u0435\u043d\u0438\u0435\u043c \u0426\u0437\u0438\u043d\u044c\u0447\u0443\u0430\u043d\u044c (4 \u043c\u043b\u043d \u0442\u043e\u043d\u043d \u000d\u000a\u043c\u0435\u0434\u0438 \u0438 6 \u043c\u043b\u043d \u0442\u043e\u043d\u043d \u043d\u0438\u043a\u0435\u043b\u044f).\u000a\u000d\u000a\u0414\u043e\u043f\u043e\u043b\u043d\u0438\u0442\u0435\u043b\u044c\u043d\u044b\u0435 \u0437\u0430\u0440\u0443\u0431\u0435\u0436\u043d\u044b\u0435 \u0440\u0435\u0441\u0443\u0440\u0441\u044b:\u000d\u000a\u0413\u043e\u0434\u043e\u0432\u043e\u0435 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u043e:\u000d\u000a\u041a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u0440\u0430\u0437\u0432\u0438\u0432\u0430\u0435\u0442 \u043f\u043e\u043b\u043d\u044b\u0439 \u0446\u0438\u043a\u043b \u0441\u043e\u0432\u0440\u0435\u043c\u0435\u043d\u043d\u044b\u0445 \u000d\u000a\u0430\u043a\u043a\u0443\u043c\u0443\u043b\u044f\u0442\u043e\u0440\u043d\u044b\u0445 \u043c\u0430\u0442\u0435\u0440\u0438\u0430\u043b\u043e\u0432:\u000d\u000a\u0418\u043d\u0434\u043e\u043d\u0435\u0437\u0438\u044f \u2014 \u043d\u0438\u043a\u0435\u043b\u044c;\u000a\u000d\u000a\u0417\u0430\u043c\u0431\u0438\u044f \u2014 \u043d\u0438\u043a\u0435\u043b\u044c;\u000a\u000d\u000a\u042e\u0410\u0420 \u2014 \u043c\u0435\u0442\u0430\u043b\u043b\u044b \u043f\u043b\u0430\u0442\u0438\u043d\u043e\u0432\u043e\u0439 \u0433\u0440\u0443\u043f\u043f\u044b;\u000a\u000d\u000a\u0414\u0435\u043c\u043e\u043a\u0440\u0430\u0442\u0438\u0447\u0435\u0441\u043a\u0430\u044f \u0420\u0435\u0441\u043f\u0443\u0431\u043b\u0438\u043a\u0430 \u041a\u043e\u043d\u0433\u043e \u2014 \u043c\u0435\u0434\u044c \u0438 \u043a\u043e\u0431\u0430\u043b\u044c\u0442 \u000d\u000a(\u043f\u0440\u043e\u0435\u043a\u0442\u044b \u0420\u0443\u0432\u0430\u0441\u0438 \u0438 \u041c\u0443\u0441\u043e\u043d\u043e\u0439).\u000d\u000a\u043d\u0438\u043a\u0435\u043b\u0435\u0432\u0430\u044f \u043f\u0440\u043e\u0434\u0443\u043a\u0446\u0438\u044f \u2014 330 \u0442\u044b\u0441. \u0442\u043e\u043d\u043d (\u0432 \u0442\u043e\u043c \u0447\u0438\u0441\u043b\u0435\u2028\u000d\u000a190 \u0442\u044b\u0441. \u0442\u043e\u043d\u043d \u044d\u043b\u0435\u043a\u0442\u0440\u043e\u043b\u0438\u0442\u0438\u0447\u0435\u0441\u043a\u043e\u0433\u043e \u043d\u0438\u043a\u0435\u043b\u044f \u0438 10 \u0442\u044b\u0441. \u0442\u043e\u043d\u043d \u000d\u000a\u043a\u0430\u0440\u0431\u043e\u043d\u0438\u043b\u044c\u043d\u043e\u0433\u043e);\u000a\u000d\u000a\u043a\u043e\u0431\u0430\u043b\u044c\u0442 \u2014 17 \u0442\u044b\u0441. \u0442\u043e\u043d\u043d, \u0432\u043a\u043b\u044e\u0447\u0430\u044f 7 \u0442\u044b\u0441. \u0442\u043e\u043d\u043d \u000d\u000a\u044d\u043b\u0435\u043a\u0442\u0440\u043e\u043b\u0438\u0442\u0438\u0447\u0435\u0441\u043a\u043e\u0433\u043e;\u000d\u000a\u043c\u0435\u0434\u044c \u2014 \u0431\u043e\u043b\u0435\u0435 1,1 \u043c\u043b\u043d \u0442\u043e\u043d\u043d;\u000a\u000d\u000a\u043c\u0435\u0442\u0430\u043b\u043b\u044b \u043f\u043b\u0430\u0442\u0438\u043d\u043e\u0432\u043e\u0439 \u0433\u0440\u0443\u043f\u043f\u044b \u2014 10 \u0442\u043e\u043d\u043d;\u000a\u000d\u000a\u0437\u043e\u043b\u043e\u0442\u043e \u2014 30 \u0442\u043e\u043d\u043d;\u000a\u000d\u000a\u0441\u0435\u0440\u0435\u0431\u0440\u043e \u2014 600 \u0442\u043e\u043d\u043d.\u000d\u000a\u0441\u0443\u043b\u044c\u0444\u0430\u0442 \u043d\u0438\u043a\u0435\u043b\u044f \u2014 200 \u0442\u044b\u0441. \u0442\u043e\u043d\u043d;\u000a\u000d\u000a\u0442\u0440\u043e\u0439\u043d\u044b\u0435 \u043f\u0440\u0435\u043a\u0443\u0440\u0441\u043e\u0440\u044b \u043a\u0430\u0442\u043e\u0434\u043d\u044b\u0445 \u043c\u0430\u0442\u0435\u0440\u0438\u0430\u043b\u043e\u0432 \u2014 120 \u0442\u044b\u0441. \u0442\u043e\u043d\u043d;\u000a\u000d\u000a\u0442\u0440\u043e\u0439\u043d\u044b\u0435 \u043a\u0430\u0442\u043e\u0434\u043d\u044b\u0435 \u043c\u0430\u0442\u0435\u0440\u0438\u0430\u043b\u044b \u2014 80 \u0442\u044b\u0441. \u0442\u043e\u043d\u043d;\u000a\u000d\u000aLMO/LFP-\u043a\u0430\u0442\u043e\u0434\u044b \u2014 6 \u0442\u044b\u0441. \u0442\u043e\u043d\u043d;\u000a\u000d\u000a\u0442\u0435\u0442\u0440\u0430\u043e\u043a\u0441\u0438\u0434 \u0442\u0440\u0438\u043a\u043e\u0431\u0430\u043b\u044c\u0442\u0430 \u2014 11 \u0442\u044b\u0441. \u0442\u043e\u043d\u043d;\u000a\u000d\u000a\u0441\u0444\u0435\u0440\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u0433\u0438\u0434\u0440\u043e\u043a\u0441\u0438\u0434 \u043d\u0438\u043a\u0435\u043b\u044f \u2014 3 \u0442\u044b\u0441. \u0442\u043e\u043d\u043d;\u000a\u000d\u000a\u043f\u0435\u0440\u0435\u0440\u0430\u0431\u043e\u0442\u043a\u0430 \u0430\u043a\u043a\u0443\u043c\u0443\u043b\u044f\u0442\u043e\u0440\u043e\u0432 \u2014 5 \u0442\u044b\u0441. \u0442\u043e\u043d\u043d.\u000d\u000a\u0423\u0436\u0435\u0441\u0442\u043e\u0447\u0435\u043d\u0438\u0435 \u0440\u044b\u043d\u043a\u0430 \u043c\u0435\u0434\u043d\u043e\u0433\u043e \u0441\u044b\u0440\u044c\u044f \u0438 \u043f\u0430\u0434\u0435\u043d\u0438\u0435 \u0441\u043f\u0440\u043e\u0441\u0430 \u000d\u000a\u043d\u0430 \u043a\u0430\u0431\u0435\u043b\u044c\u043d\u0443\u044e \u043f\u0440\u043e\u0434\u0443\u043a\u0446\u0438\u044e, \u0441\u043f\u0440\u043e\u0432\u043e\u0446\u0438\u0440\u043e\u0432\u0430\u0432\u0448\u0438\u0435 \u0441\u043d\u0438\u0436\u0435\u043d\u0438\u0435 \u000d\u000a\u0440\u0435\u043d\u0442\u0430\u0431\u0435\u043b\u044c\u043d\u043e\u0441\u0442\u0438.\u000a\u000d\u000a\u0417\u0430\u043f\u0440\u0435\u0442 \u043d\u0430 \u044d\u043a\u0441\u043f\u043e\u0440\u0442 \u043a\u043e\u0431\u0430\u043b\u044c\u0442\u0430 \u0438\u0437 \u0414\u0435\u043c\u043e\u043a\u0440\u0430\u0442\u0438\u0447\u0435\u0441\u043a\u043e\u0439 \u0420\u0435\u0441\u043f\u0443\u0431\u043b\u0438\u043a\u0438 \u000d\u000a\u041a\u043e\u043d\u0433\u043e, \u0441\u0442\u0430\u0432\u0448\u0438\u0439 \u0432 \u0444\u0435\u0432\u0440\u0430\u043b\u0435 2025-\u0433\u043e \u043f\u0440\u0438\u0447\u0438\u043d\u043e\u0439 \u0440\u0435\u0437\u043a\u043e\u0433\u043e \u000d\u000a\u043f\u0430\u0434\u0435\u043d\u0438\u044f \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0430.\u000a\u000d\u000a\u041d\u0435\u0441\u0442\u0430\u0431\u0438\u043b\u044c\u043d\u0430\u044f \u044d\u043d\u0435\u0440\u0433\u043e\u0441\u0438\u0441\u0442\u0435\u043c\u0430 \u0414\u0420\u041a \u0438, \u043a\u0430\u043a \u0441\u043b\u0435\u0434\u0441\u0442\u0432\u0438\u0435, \u043f\u0435\u0440\u0435\u0431\u043e\u0438 \u000d\u000a\u0432 \u044f\u043d\u0432\u0430\u0440\u0435 2025 \u0433\u043e\u0434\u0430.\u000a\u000d\u000a\u041d\u0435\u043e\u0431\u0445\u043e\u0434\u0438\u043c\u043e\u0441\u0442\u044c \u043e\u0434\u043d\u043e\u0432\u0440\u0435\u043c\u0435\u043d\u043d\u043e \u043c\u043e\u0434\u0435\u0440\u043d\u0438\u0437\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u0441\u0442\u0430\u0440\u044b\u0435 \u000d\u000a\u043c\u043e\u0449\u043d\u043e\u0441\u0442\u0438 \u0438 \u0432\u044b\u0445\u043e\u0434\u0438\u0442\u044c \u043d\u0430 \u0432\u044b\u0441\u043e\u043a\u043e\u0442\u0435\u0445\u043d\u043e\u043b\u043e\u0433\u0438\u0447\u043d\u044b\u0435 \u0440\u044b\u043d\u043a\u0438.\u000a\u000d\u000a\u0423\u0436\u0435\u0441\u0442\u043e\u0447\u0435\u043d\u0438\u0435 \u044d\u043a\u043e\u043b\u043e\u0433\u0438\u0447\u0435\u0441\u043a\u0438\u0445 \u043d\u043e\u0440\u043c.\u000d\u000a\u0412\u044b\u0440\u0443\u0447\u043a\u0430 \u0432 2024 \u0433\u043e\u0434\u0443 \u2014 $58,8 \u043c\u043b\u0440\u0434.\u000a\u000d\u000a\u0421\u0442\u0440\u0430\u0442\u0435\u0433\u0438\u0447\u0435\u0441\u043a\u0430\u044f \u0446\u0435\u043b\u044c \u2014 \u043a 2030 \u0433\u043e\u0434\u0443 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u043f\u043b\u0430\u043d\u0438\u0440\u0443\u0435\u0442 \u000d\u000a\u0434\u043e\u0441\u0442\u0438\u0447\u044c 1 \u0442\u0440\u043b\u043d \u044e\u0430\u043d\u0435\u0439 ($139 \u043c\u043b\u0440\u0434) \u0432\u044b\u0440\u0443\u0447\u043a\u0438.\u000d\u000a\u0424\u0438\u043d\u0430\u043d\u0441\u043e\u0432\u044b\u0435 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u044b\u000d\u000aJinchuan Group Co., Ltd. (\u91d1\u5ddd\u96c6\u56e2\u80a1\u4efd\u6709\u9650\u516c\u53f8)\u000d\u000a\u0420\u0435\u0441\u0443\u0440\u0441\u043d\u0430\u044f \u0431\u0430\u0437\u0430 \u0438 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0435 \u043c\u043e\u0449\u043d\u043e\u0441\u0442\u0438\u000d\u000a\u041f\u0440\u043e\u0431\u043b\u0435\u043c\u044b \u0438 \u0432\u044b\u0437\u043e\u0432\u044b\u000d\u000a\u041f\u0440\u043e\u043c\u044b\u0448\u043b\u0435\u043d\u043d\u044b\u0439 \u043a\u043b\u0430\u0441\u0442\u0435\u0440","12/17\u000d\u000aJiangxi Copper \u000d\u000aCorporation Limited\u000d\u000a(\u6c5f\u897f\u94dc\u4e1a\u96c6\u56e2\u6709\u9650\u516c\u53f8)\u000d\u000a\u0428\u0442\u0430\u0431-\u043a\u0432\u0430\u0440\u0442\u0438\u0440\u0430\u000d\u000a\u041d\u0430\u043d\u044c\u0447\u0430\u043d, \u043f\u0440\u043e\u0432\u0438\u043d\u0446\u0438\u044f \u0426\u0437\u044f\u043d\u0441\u0438\u000d\u000a\u041a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0438\u0439 \u043c\u0435\u0434\u0438 \u0432 \u041a\u0438\u0442\u0430\u0435.\u000a\u000d\u000a\u0418\u043d\u0442\u0435\u0433\u0440\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0439 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u0442\u0435\u043b\u044c \u043f\u043e\u043b\u0438\u043c\u0435\u0442\u0430\u043b\u043b\u043e\u0432: \u043c\u0435\u0434\u0438, \u000d\u000a\u0437\u043e\u043b\u043e\u0442\u0430, \u0441\u0435\u0440\u0435\u0431\u0440\u0430, \u0441\u0432\u0438\u043d\u0446\u0430, \u0446\u0438\u043d\u043a\u0430, \u0432\u043e\u043b\u044c\u0444\u0440\u0430\u043c\u0430, \u0440\u0435\u043d\u0438\u044f \u0438 \u0442\u0435\u043b\u043b\u0443\u0440\u0430.\u000a\u000d\u000aHunan Nonferrous \u0432\u0445\u043e\u0434\u0438\u0442 \u043f\u044f\u0442\u0435\u0440\u043a\u0443 \u043a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0438\u0445 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u0442\u0435\u043b\u0435\u0439 \u000d\u000a\u0446\u0432\u0435\u0442\u043d\u044b\u0445 \u043c\u0435\u0442\u0430\u043b\u043b\u043e\u0432 \u041a\u0438\u0442\u0430\u044f. \u041f\u0440\u0438\u043d\u0430\u0434\u043b\u0435\u0436\u0438\u0442 China Minmetals.\u000d\u000a\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u0442\u0435\u043b\u044c\u000d\u000a\u041a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0438\u0439 \u0432 \u0410\u0437\u0438\u0438 \u043e\u0442\u043a\u0440\u044b\u0442\u044b\u0439 \u043c\u0435\u0434\u043d\u044b\u0439 \u0440\u0443\u0434\u043d\u0438\u043a \u0414\u044d\u0441\u0438\u043d \u0441 \u0437\u0430\u043f\u0430\u0441\u0430\u043c\u0438 \u000d\u000a\u043c\u0435\u0434\u0438 5 \u043c\u043b\u043d \u0442\u043e\u043d\u043d \u0438 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0441\u0442\u044c\u044e 150 \u0442\u044b\u0441. \u0442\u043e\u043d\u043d.  \u000a\u000d\u000a\u041a\u0440\u0443\u043f\u043d\u044b\u0435 \u043c\u0435\u0434\u043d\u044b\u0435 \u0440\u0443\u0434\u043d\u0438\u043a\u0438 \u0423\u0448\u0430\u043d\u044c \u0438 \u042e\u043d\u043f\u0438\u043d. \u000a\u000d\u000a\u041c\u0435\u0434\u0435\u043f\u043b\u0430\u0432\u0438\u043b\u044c\u043d\u044b\u0439 \u0437\u0430\u0432\u043e\u0434 \u0432 \u0413\u0443\u0439\u0441\u0438 \u2014 \u043a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0438\u0439 \u0432 \u043c\u0438\u0440\u0435:\u000d\u000a\u041a\u043b\u0430\u0441\u0442\u0435\u0440 \u043d\u043e\u0432\u044b\u0445 \u043c\u0435\u0434\u043d\u044b\u0445 \u043c\u0430\u0442\u0435\u0440\u0438\u0430\u043b\u043e\u0432 \u0432 \u043f\u0440\u043e\u0432\u0438\u043d\u0446\u0438\u0438 \u0426\u0437\u044f\u043d\u0441\u0438  \u2014  \u000d\u000a\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u043e \u043c\u0435\u0434\u043d\u043e\u0439 \u0444\u043e\u043b\u044c\u0433\u0438 \u0442\u043e\u043b\u0449\u0438\u043d\u043e\u0439 3,5 \u043c\u043a\u043c \u000d\u000a\u0434\u043b\u044f \u044d\u043b\u0435\u043a\u0442\u0440\u043e\u043d\u0438\u043a\u0438 \u0438 \u0430\u043a\u043a\u0443\u043c\u0443\u043b\u044f\u0442\u043e\u0440\u043e\u0432.\u000a\u000d\u000aJiangxi Copper \u0440\u0430\u043d\u0435\u0435 \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u0438\u0440\u043e\u0432\u0430\u043b\u0430 \u043f\u0440\u0430\u0432\u0430 \u043d\u0430 \u0434\u043e\u0431\u044b\u0447\u0443 \u000d\u000a\u043d\u0430 \u0440\u0435\u0434\u043a\u043e\u0437\u0435\u043c\u0435\u043b\u044c\u043d\u043e\u043c \u0440\u0443\u0434\u043d\u0438\u043a\u0435 \u041c\u0430\u043e\u043d\u044e\u043f\u0438\u043d, \u0432 2023 \u0433\u043e\u0434\u0443 \u000d\u000a\u043f\u043e \u0440\u0435\u0448\u0435\u043d\u0438\u044e \u0440\u0435\u0433\u0443\u043b\u044f\u0442\u043e\u0440\u0430 \u0430\u043a\u0442\u0438\u0432 \u043f\u0435\u0440\u0435\u0434\u0430\u043b\u0438 \u0432 \u0441\u043e\u0441\u0442\u0430\u0432 China Rare \u000d\u000aEarth Group.\u000a\u000d\u000a\u041a\u043b\u044e\u0447\u0435\u0432\u044b\u0435 \u0437\u0430\u0440\u0443\u0431\u0435\u0436\u043d\u044b\u0435 \u043f\u0440\u043e\u0435\u043a\u0442\u044b:\u000d\u000a\u0421\u0444\u0435\u0440\u0430 \u0434\u0435\u044f\u0442\u0435\u043b\u044c\u043d\u043e\u0441\u0442\u0438 \u0438 \u043f\u043e\u0437\u0438\u0446\u0438\u0438 \u0432 \u043e\u0442\u0440\u0430\u0441\u043b\u0438\u000d\u000a\u041a\u043b\u044e\u0447\u0435\u0432\u044b\u0435 \u043f\u0440\u043e\u0435\u043a\u0442\u044b\u000d\u000a\u043a\u0430\u0442\u043e\u0434\u043d\u0430\u044f \u043c\u0435\u0434\u044c \u2014 1 \u043c\u043b\u043d \u0442\u043e\u043d\u043d \u0432 \u0433\u043e\u0434;\u000a\u000d\u000a\u0441\u043e\u043f\u0443\u0442\u0441\u0442\u0432\u0443\u044e\u0449\u0430\u044f \u043f\u0440\u043e\u0434\u0443\u043a\u0446\u0438\u044f \u2014 4 \u043c\u043b\u043d \u0442\u043e\u043d\u043d \u0441\u0435\u0440\u043d\u043e\u0439 \u043a\u0438\u0441\u043b\u043e\u0442\u044b \u000d\u000a\u0438 30 \u0442\u043e\u043d\u043d \u0437\u043e\u043b\u043e\u0442\u0430 \u0435\u0436\u0435\u0433\u043e\u0434\u043d\u043e.\u000d\u000a18,61% \u0430\u043a\u0446\u0438\u0439 \u043a\u0430\u043d\u0430\u0434\u0441\u043a\u043e\u0439 . \u0417\u0430\u043f\u0430\u0441\u044b \u043c\u0435\u0434\u0438 \u2014 \u000d\u000a35,5 \u043c\u043b\u043d \u0442\u043e\u043d\u043d, \u0434\u043e\u0431\u044b\u0447\u0430 700 \u0442\u044b\u0441. \u0442\u043e\u043d\u043d \u0432 \u0433\u043e\u0434. \u041c\u0435\u0433\u0430\u043f\u0440\u043e\u0435\u043a\u0442 \u000d\u000a\u041a\u043e\u0431\u0440\u0435 \u041f\u0430\u043d\u0430\u043c\u0430 (300 \u0442\u044b\u0441. \u0442\u043e\u043d\u043d \u0432 \u0433\u043e\u0434) \u0432\u0440\u0435\u043c\u0435\u043d\u043d\u043e \u0437\u0430\u043c\u043e\u0440\u043e\u0436\u0435\u043d\u2028\u000d\u000a\u0438\u0437 \u0437\u0430 \u0440\u0435\u0448\u0435\u043d\u0438\u044f \u043f\u0440\u0430\u0432\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u0430 \u041f\u0430\u043d\u0430\u043c\u044b \u043d\u0430 \u0444\u043e\u043d\u0435 \u000d\u000a\u044d\u043a\u043e\u043b\u043e\u0433\u0438\u0447\u0435\u0441\u043a\u0438\u0445 \u043f\u0440\u043e\u0442\u0435\u0441\u0442\u043e\u0432.\u000a\u000d\u000a25% \u0440\u0443\u0434\u043d\u0438\u043a\u0430 \u0410\u0439\u043d\u0430\u043a (\u0410\u0444\u0433\u0430\u043d\u0438\u0441\u0442\u0430\u043d) \u2014 11 \u043c\u043b\u043d \u0442\u043e\u043d\u043d \u0437\u0430\u043f\u0430\u0441\u043e\u0432, \u000d\u000a\u043f\u0440\u043e\u0435\u043a\u0442\u043d\u0430\u044f \u043c\u043e\u0449\u043d\u043e\u0441\u0442\u044c 300 \u0442\u044b\u0441. \u0442\u043e\u043d\u043d \u043c\u0435\u0434\u0438. \u041e\u043f\u044b\u0442\u043d\u0430\u044f \u0434\u043e\u0431\u044b\u0447\u0430 \u000d\u000a\u043d\u0430\u0447\u043d\u0435\u0442\u0441\u044f \u0432 2026 \u0433\u043e\u0434\u0443, \u0432\u044b\u0445\u043e\u0434 \u043d\u0430 \u043f\u043e\u043b\u043d\u0443\u044e \u043c\u043e\u0449\u043d\u043e\u0441\u0442\u044c \u2014 \u000d\u000a\u0432 2027 \u0433\u043e\u0434\u0443.\u000a\u000d\u000a22,5% \u0440\u0443\u0434\u043d\u0438\u043a\u0430 \u041b\u0430\u0441-\u0411\u0430\u043c\u0431\u0430\u0441 \u0432 \u041f\u0435\u0440\u0443 (400 \u0442\u044b\u0441. \u0442\u043e\u043d\u043d \u0432 \u0433\u043e\u0434).\u000a\u000d\u000a\u0421\u0442\u043e\u043f\u0440\u043e\u0446\u0435\u043d\u0442\u043d\u044b\u0439 \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044c \u043d\u0430\u0434 \u0440\u0443\u0434\u043d\u0438\u043a\u043e\u043c \u041a\u0438\u043d\u0441\u0435\u0432\u0435\u0440\u0435 (\u0414\u0420\u041a) \u000d\u000a\u043f\u043e\u0441\u043b\u0435 \u043f\u043e\u043a\u0443\u043f\u043a\u0438 28% \u0432 2023 \u0433\u043e\u0434\u0443 \u2014 \u043c\u043e\u0449\u043d\u043e\u0441\u0442\u044c \u0434\u043e 150 \u0442\u044b\u0441. \u0442\u043e\u043d\u043d \u000d\u000a\u0440\u0430\u0444\u0438\u043d\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u043e\u0439 \u043c\u0435\u0434\u0438. \u041a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u0441\u0442\u0440\u043e\u0438\u0442 \u043f\u0435\u0440\u0432\u0443\u044e \u0432 \u0410\u0444\u0440\u0438\u043a\u0435 \u000d\u000a\u043b\u0438\u043d\u0438\u044e \u043f\u043e \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0443 \u043c\u0435\u0434\u043d\u043e\u0439 \u0444\u043e\u043b\u044c\u0433\u0438.\u000a\u000d\u000a\u0423\u0432\u0435\u043b\u0438\u0447\u0435\u043d\u043d\u0430\u044f \u0434\u043e 12,9% \u0434\u043e\u043b\u044f \u0432 SolGold, \u0432\u043b\u0430\u0434\u0435\u044e\u0449\u0435\u0439 \u000d\u000a\u043c\u0435\u0441\u0442\u043e\u0440\u043e\u0436\u0434\u0435\u043d\u0438\u0435\u043c \u041a\u0430\u0441\u043a\u0430\u0431\u0435\u043b\u044c \u0432 \u042d\u043a\u0432\u0430\u0434\u043e\u0440\u0435 (12,2 \u043c\u043b\u043d \u0442\u043e\u043d\u043d \u043c\u0435\u0434\u0438).\u000d\u000aFirst Quantum Minerals\u000d\u000a165 \u0435 \u043c\u0435\u0441\u0442\u043e \u0432 (2025 \u0433\u043e\u0434);\u000a\u000d\u000a398-\u0435 \u043c\u0435\u0441\u0442\u043e \u0432 \u0441\u043f\u0438\u0441\u043a\u0435 500 \u0441\u0430\u043c\u044b\u0445 \u0434\u043e\u0440\u043e\u0433\u0438\u0445 \u0431\u0440\u0435\u043d\u0434\u043e\u0432 \u043c\u0438\u0440\u0430 \u000d\u000a(Brand Finance Global 500).\u000d\u000aFortune Global 500\u000d\u000aJiangxi Copper \u043e\u0441\u043d\u043e\u0432\u0430\u043d\u0430 \u0432 1979 \u0433\u043e\u0434\u0443 \u0432 \u0440\u0430\u043c\u043a\u0430\u0445 \u043d\u0430\u0446\u0438\u043e\u043d\u0430\u043b\u044c\u043d\u043e\u0439 \u000d\u000a\u043f\u0440\u043e\u0433\u0440\u0430\u043c\u043c\u044b \u043f\u043e \u0440\u0430\u0437\u0432\u0438\u0442\u0438\u044e \u043c\u0435\u0434\u043d\u043e\u0439 \u0438\u043d\u0434\u0443\u0441\u0442\u0440\u0438\u0438 \u043d\u0430 \u0431\u0430\u0437\u0435 \u000d\u000a\u043a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0438\u0445 \u043c\u0435\u0441\u0442\u043e\u0440\u043e\u0436\u0434\u0435\u043d\u0438\u0439 \u043f\u0440\u043e\u0432\u0438\u043d\u0446\u0438\u0438 \u0426\u0437\u044f\u043d\u0441\u0438.\u000a\u000d\u000a\u0412 1980\u201390 \u0445 \u0433\u043e\u0434\u0430\u0445 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u0440\u0430\u0441\u0448\u0438\u0440\u044f\u043b\u0430 \u043c\u043e\u0449\u043d\u043e\u0441\u0442\u0438, \u043e\u0441\u0432\u0430\u0438\u0432\u0430\u043b\u0430 \u000d\u000a\u043d\u043e\u0432\u044b\u0435 \u0440\u0443\u0434\u043d\u0438\u043a\u0438, \u0434\u043e\u0431\u044b\u0447\u0443 \u0437\u043e\u043b\u043e\u0442\u0430 \u0438 \u0441\u0435\u0440\u0435\u0431\u0440\u0430, \u0440\u0430\u0437\u0432\u0438\u0432\u0430\u043b\u0430 \u000d\u000a\u0445\u0438\u043c\u0438\u0447\u0435\u0441\u043a\u043e\u0435 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u043e.\u000a\u000d\u000a\u0412 2008 \u0433\u043e\u0434\u0443 \u0433\u0440\u0443\u043f\u043f\u0430 \u043f\u0440\u043e\u0432\u0435\u043b\u0430 \u0440\u0435\u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u0438\u0437\u0430\u0446\u0438\u044e.\u000a\u000d\u000a\u0412 2019 \u0433\u043e\u0434\u0443 \u2014 \u043f\u0440\u0438\u043e\u0431\u0440\u0435\u043b\u0430 \u0434\u043e\u043b\u044e \u0432 \u043a\u0430\u043d\u0430\u0434\u0441\u043a\u043e\u0439 First Quantum \u000d\u000aMinerals.\u000a\u000d\u000a\u0412 2021 \u0433\u043e\u0434\u0443 \u2014 \u0438\u043d\u0432\u0435\u0441\u0442\u0438\u0440\u043e\u0432\u0430\u043b\u0430 \u0432 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u043e \u043b\u0438\u0442\u0438\u0435\u0432\u044b\u0445 \u000d\u000a\u0438 \u043c\u0435\u0434\u043d\u044b\u0445 \u043c\u0430\u0442\u0435\u0440\u0438\u0430\u043b\u043e\u0432 \u0434\u043b\u044f \u043d\u043e\u0432\u043e\u0439 \u044d\u043d\u0435\u0440\u0433\u0435\u0442\u0438\u043a\u0438, \u0432 \u0447\u0430\u0441\u0442\u043d\u043e\u0441\u0442\u0438 \u000d\u000a\u0430\u043a\u043a\u0443\u043c\u0443\u043b\u044f\u0442\u043e\u0440\u043e\u0432 \u0434\u043b\u044f \u044d\u043b\u0435\u043a\u0442\u0440\u043e\u043c\u043e\u0431\u0438\u043b\u0435\u0439.\u000d\u000a\u0418\u0441\u0442\u043e\u0440\u0438\u044f \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438\u000d\u000a\u0428\u0442\u0430\u0431 \u043a\u0432\u0430\u0440\u0442\u0438\u0440\u0430 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438","13/17\u000d\u000a\u0421\u043e\u0431\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0435 \u0437\u0430\u043f\u0430\u0441\u044b \u043c\u0435\u0434\u0438 \u0432 \u041a\u041d\u0420 \u2014 8,9 \u043c\u043b\u043d \u0442\u043e\u043d\u043d. \u0421 \u0443\u0447\u0435\u0442\u043e\u043c \u000d\u000a\u0437\u0430\u0440\u0443\u0431\u0435\u0436\u043d\u044b\u0445 \u0434\u043e\u043b\u0435\u0432\u044b\u0445 \u0430\u043a\u0442\u0438\u0432\u043e\u0432 \u043e\u0431\u0449\u0438\u0439 \u0440\u0435\u0441\u0443\u0440\u0441 \u043f\u0440\u0435\u0432\u044b\u0448\u0430\u0435\u0442 \u000d\u000a20 \u043c\u043b\u043d \u0442\u043e\u043d\u043d.\u000a\u000d\u000a\u041f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0435 \u043c\u043e\u0449\u043d\u043e\u0441\u0442\u0438:\u000d\u000a\u043a\u0430\u0442\u043e\u0434\u043d\u0430\u044f \u043c\u0435\u0434\u044c \u00ad\u2014 2 \u043c\u043b\u043d \u0442\u043e\u043d\u043d \u0432 \u0433\u043e\u0434;\u000a\u000d\u000a\u0441\u0435\u0440\u043d\u0430\u044f \u043a\u0438\u0441\u043b\u043e\u0442\u0430 \u2014 4 \u043c\u043b\u043d \u0442\u043e\u043d\u043d \u0432 \u0433\u043e\u0434;\u000a\u000d\u000a\u0437\u043e\u043b\u043e\u0442\u043e \u2014 30 \u0442\u043e\u043d\u043d \u0432 \u0433\u043e\u0434;\u000a\u000d\u000a\u0441\u043e\u043f\u0443\u0442\u0441\u0442\u0432\u0443\u044e\u0449\u0438\u0435 \u043c\u0435\u0442\u0430\u043b\u043b\u044b \u2014 \u0441\u0435\u0440\u0435\u0431\u0440\u043e, \u0432\u043e\u043b\u044c\u0444\u0440\u0430\u043c, \u0440\u0435\u043d\u0438\u0439, \u0442\u0435\u043b\u043b\u0443\u0440.\u000d\u000a\u041d\u0435\u0445\u0432\u0430\u0442\u043a\u0430 \u0432\u043d\u0443\u0442\u0440\u0435\u043d\u043d\u0438\u0445 \u0440\u0435\u0441\u0443\u0440\u0441\u043e\u0432 \u043c\u0435\u0434\u0438 \u2014 \u0438\u043c\u043f\u043e\u0440\u0442 \u043f\u0435\u0440\u0435\u043a\u0440\u044b\u0432\u0430\u0435\u0442 \u000d\u000a\u0431\u043e\u043b\u0435\u0435 70% \u043f\u043e\u0442\u0440\u0435\u0431\u043d\u043e\u0441\u0442\u0438.\u000a\u000d\u000a\u0412\u043e\u043b\u0430\u0442\u0438\u043b\u044c\u043d\u043e\u0441\u0442\u044c \u0441\u0442\u043e\u0438\u043c\u043e\u0441\u0442\u0438 \u043c\u0435\u0434\u0438 \u0432\u043b\u0438\u044f\u0435\u0442 \u043d\u0430 \u0432\u044b\u0440\u0443\u0447\u043a\u0443 \u000d\u000a(\u0432 2024 \u0433\u043e\u0434\u0443 \u043e\u043d\u0430 \u0441\u043d\u0438\u0437\u0438\u043b\u0430\u0441\u044c \u0438\u043c\u0435\u043d\u043d\u043e \u0438\u0437-\u0437\u0430 \u043a\u043e\u0440\u0440\u0435\u043a\u0442\u0438\u0440\u043e\u0432\u043a\u0438 \u0446\u0435\u043d).\u000a\u000d\u000a\u0423\u0436\u0435\u0441\u0442\u043e\u0447\u0435\u043d\u0438\u0435 \u044d\u043a\u043e\u043b\u043e\u0433\u0438\u0447\u0435\u0441\u043a\u0438\u0445 \u0442\u0440\u0435\u0431\u043e\u0432\u0430\u043d\u0438\u0439 \u0442\u0440\u0435\u0431\u0443\u0435\u0442 \u043a\u0440\u0443\u043f\u043d\u044b\u0445 \u000d\u000a\u0438\u043d\u0432\u0435\u0441\u0442\u0438\u0446\u0438\u0439.\u000a\u000d\u000a \u041f\u0435\u0440\u0435\u0438\u0437\u0431\u044b\u0442\u043e\u043a \u043f\u043b\u0430\u0432\u0438\u043b\u044c\u043d\u044b\u0445 \u043c\u043e\u0449\u043d\u043e\u0441\u0442\u0435\u0439 \u0432 \u041a\u0438\u0442\u0430\u0435 \u0443\u0441\u0438\u043b\u0438\u0432\u0430\u0435\u0442 \u000d\u000a\u043a\u043e\u043d\u043a\u0443\u0440\u0435\u043d\u0446\u0438\u044e.\u000a\u000d\u000a\u0422\u0430\u0440\u0438\u0444\u044b TC/RC \u043d\u0430 2025 \u0433\u043e\u0434 ($21,25 \u0437\u0430 \u0442\u043e\u043d\u043d\u0443 \u0438 2,13 \u0446\u0435\u043d\u0442\u0430 \u000d\u000a\u0437\u0430 \u0444\u0443\u043d\u0442), \u0441\u043e\u0433\u043b\u0430\u0441\u043e\u0432\u0430\u043d\u043d\u044b\u0435 \u0441\u043e\u0432\u043c\u0435\u0441\u0442\u043d\u043e \u0441 China Copper, Tongling, \u000d\u000aJinchuan \u0438 Daye Nonferrous, \u043e\u043a\u0430\u0437\u0430\u043b\u0438\u0441\u044c \u0432 \u0447\u0435\u0442\u044b\u0440\u0435 \u0440\u0430\u0437\u0430 \u043d\u0438\u0436\u0435 \u000d\u000a\u0443\u0440\u043e\u0432\u043d\u0435\u0439 2024 \u0433\u043e\u0434\u0430 \u0438 \u043d\u0438\u0436\u0435 \u0441\u0435\u0431\u0435\u0441\u0442\u043e\u0438\u043c\u043e\u0441\u0442\u0438 \u0434\u043b\u044f \u0431\u043e\u043b\u044c\u0448\u0438\u043d\u0441\u0442\u0432\u0430 \u000d\u000a\u043f\u0440\u0435\u0434\u043f\u0440\u0438\u044f\u0442\u0438\u0439 \u2014 \u0447\u0442\u043e \u0444\u0430\u043a\u0442\u0438\u0447\u0435\u0441\u043a\u0438 \u043e\u0437\u043d\u0430\u0447\u0430\u0435\u0442 \u0440\u0430\u0431\u043e\u0442\u0443 \u0432 \u0443\u0431\u044b\u0442\u043e\u043a.\u000d\u000a\u0412\u044b\u0440\u0443\u0447\u043a\u0430 (2024 \u0433\u043e\u0434) \u2014 $72,5 \u043c\u043b\u0440\u0434 (\u22120,18% \u043a \u043f\u0440\u0435\u0434\u044b\u0434\u0443\u0449\u0435\u043c\u0443 \u0433\u043e\u0434\u0443).\u000d\u000a\u0424\u0438\u043d\u0430\u043d\u0441\u043e\u0432\u044b\u0435 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u044b\u000d\u000aJiangxi Copper Corporation Limited (\u6c5f\u897f\u94dc\u4e1a\u96c6\u56e2\u6709\u9650\u516c\u53f8)\u000d\u000a\u0420\u0435\u0441\u0443\u0440\u0441\u043d\u0430\u044f \u0431\u0430\u0437\u0430 \u0438 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0435\u2028\u000d\u000a\u043c\u043e\u0449\u043d\u043e\u0441\u0442\u0438\u000d\u000a\u041f\u0440\u043e\u0431\u043b\u0435\u043c\u044b \u0438 \u0432\u044b\u0437\u043e\u0432\u044b\u000d\u000a\u041f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0439 \u0446\u0435\u0445","14/17\u000d\u000aChina Minmetals \u000d\u000aCorporation\u000d\u000a(\u4e2d\u56fd\u4e94\u77ff\u96c6\u56e2\u516c\u53f8)\u000d\u000a\u0428\u0442\u0430\u0431-\u043a\u0432\u0430\u0440\u0442\u0438\u0440\u0430\u000d\u000a\u041f\u0435\u043a\u0438\u043d\u000d\u000aChina Minmetals \u2014 \u043a\u043b\u044e\u0447\u0435\u0432\u043e\u0435 \u0433\u043e\u0441\u0443\u0434\u0430\u0440\u0441\u0442\u0432\u0435\u043d\u043d\u043e\u0435 \u043f\u0440\u0435\u0434\u043f\u0440\u0438\u044f\u0442\u0438\u0435, \u000d\u000a\u043d\u0430\u0445\u043e\u0434\u044f\u0449\u0435\u0435\u0441\u044f \u043f\u043e\u0434 \u043f\u0440\u044f\u043c\u044b\u043c \u0443\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u0435\u043c \u0446\u0435\u043d\u0442\u0440\u0430\u043b\u044c\u043d\u043e\u0433\u043e \u000d\u000a\u043f\u0440\u0430\u0432\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u0430 \u0438 \u0441\u043f\u0435\u0446\u0438\u0430\u043b\u0438\u0437\u0438\u0440\u0443\u044e\u0449\u0435\u0435\u0441\u044f \u043d\u0430 \u0434\u043e\u0431\u044b\u0447\u0435 \u043c\u0435\u0442\u0430\u043b\u043b\u043e\u0432 \u000d\u000a\u0438 \u043c\u0438\u043d\u0435\u0440\u0430\u043b\u044c\u043d\u043e\u0433\u043e \u0441\u044b\u0440\u044c\u044f.\u000a\u000d\u000a\u041a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u0437\u0430\u043d\u0438\u043c\u0430\u0435\u0442 \u0432\u0430\u0436\u043d\u0435\u0439\u0448\u0443\u044e \u0440\u043e\u043b\u044c \u0432 \u0441\u0442\u0440\u0430\u0442\u0435\u0433\u0438\u0447\u0435\u0441\u043a\u043e\u043c \u000d\u000a\u043e\u0431\u0435\u0441\u043f\u0435\u0447\u0435\u043d\u0438\u0438 \u041a\u0438\u0442\u0430\u044f \u043e\u0441\u043d\u043e\u0432\u043d\u044b\u043c\u0438 \u043c\u0438\u043d\u0435\u0440\u0430\u043b\u0430\u043c\u0438.\u000a\u000d\u000a\u041f\u043e \u0441\u043e\u0441\u0442\u043e\u044f\u043d\u0438\u044e \u043d\u0430 2024 \u0433\u043e\u0434 Minmetals \u0437\u0430\u043d\u0438\u043c\u0430\u0435\u0442 86-\u0435 \u043c\u0435\u0441\u0442\u043e \u000d\u000a\u0432 \u0440\u0435\u0439\u0442\u0438\u043d\u0433\u0435 Fortune Global 500 \u0438 190-\u0435 \u043c\u0435\u0441\u0442\u043e \u0441\u0440\u0435\u0434\u0438 500 \u0441\u0430\u043c\u044b\u0445 \u000d\u000a\u0434\u043e\u0440\u043e\u0433\u0438\u0445 \u0431\u0440\u0435\u043d\u0434\u043e\u0432 \u043c\u0438\u0440\u0430 (Brand Finance Global 500).\u000d\u000aChina Minmetals \u043e\u0441\u043d\u043e\u0432\u0430\u043d\u0430 \u0432 1950 \u0433\u043e\u0434\u0443 \u043a\u0430\u043a \u0433\u043e\u0441\u0443\u0434\u0430\u0440\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0439 \u000d\u000a\u043e\u043f\u0435\u0440\u0430\u0442\u043e\u0440 \u0432\u043d\u0435\u0448\u043d\u0435\u0439 \u0442\u043e\u0440\u0433\u043e\u0432\u043b\u0438 \u043c\u0435\u0442\u0430\u043b\u043b\u0430\u043c\u0438. \u0412 1950\u20131960-\u0445 \u0447\u0435\u0440\u0435\u0437 \u000d\u000a\u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u044b \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438 \u043f\u0440\u043e\u0445\u043e\u0434\u0438\u043b\u043e \u0434\u043e 25% \u0432\u0441\u0435\u0439 \u0432\u043d\u0435\u0448\u043d\u0435\u0439 \u0442\u043e\u0440\u0433\u043e\u0432\u043b\u0438 \u000d\u000a\u041a\u0438\u0442\u0430\u044f, \u0447\u0442\u043e \u0441\u0434\u0435\u043b\u0430\u043b\u043e China Minmetals \u043a\u043b\u044e\u0447\u0435\u0432\u044b\u043c \u0438\u043d\u0441\u0442\u0440\u0443\u043c\u0435\u043d\u0442\u043e\u043c \u000d\u000a\u043f\u043e\u0441\u043b\u0435\u0432\u043e\u0435\u043d\u043d\u043e\u0433\u043e \u0432\u043e\u0441\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u0438\u044f \u044d\u043a\u043e\u043d\u043e\u043c\u0438\u043a\u0438.\u000a\u000d\u000a\u0421 \u043d\u0430\u0447\u0430\u043b\u043e\u043c \u0440\u0435\u0444\u043e\u0440\u043c Minmetals \u0443\u0442\u0440\u0430\u0442\u0438\u043b\u0430 \u043c\u043e\u043d\u043e\u043f\u043e\u043b\u0438\u044e \u000d\u000a\u0438 \u043e\u0434\u043d\u043e\u0439 \u0438\u0437 \u043f\u0435\u0440\u0432\u044b\u0445 \u0441\u0440\u0435\u0434\u0438 \u0433\u043e\u0441\u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0439 \u043f\u0435\u0440\u0435\u0448\u043b\u0430 \u000d\u000a\u043a \u0434\u0438\u0432\u0435\u0440\u0441\u0438\u0444\u0438\u0446\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u043e\u0439 \u043c\u043e\u0434\u0435\u043b\u0438, \u0430 \u0437\u0430\u0442\u0435\u043c \u2014 \u043a \u0433\u043b\u043e\u0431\u0430\u043b\u044c\u043d\u043e\u0439 \u000d\u000a\u044d\u043a\u0441\u043f\u0430\u043d\u0441\u0438\u0438 \u0441 \u043f\u0440\u0438\u0441\u0443\u0442\u0441\u0442\u0432\u0438\u0435\u043c \u0431\u043e\u043b\u0435\u0435 \u0447\u0435\u043c \u0432 40 \u0441\u0442\u0440\u0430\u043d\u0430\u0445.\u000a\u000d\u000a\u0412 2000-\u0445 \u0433\u043e\u0434\u0430\u0445 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u0441\u043c\u0435\u043d\u0438\u043b\u0430 \u0444\u043e\u043a\u0443\u0441 \u0441 \u0442\u043e\u0440\u0433\u043e\u0432\u043b\u0438 \u043d\u0430 \u0434\u043e\u0431\u044b\u0447\u0443 \u000d\u000a\u0438 \u043f\u0435\u0440\u0435\u0440\u0430\u0431\u043e\u0442\u043a\u0443 \u043c\u0435\u0442\u0430\u043b\u043b\u043e\u0432, \u0438\u043d\u0442\u0435\u0433\u0440\u0438\u0440\u043e\u0432\u0430\u0432 \u043a\u0440\u0443\u043f\u043d\u044b\u0435 \u0433\u043e\u0441\u0430\u043a\u0442\u0438\u0432\u044b.\u000a\u000d\u000a\u0412 2015 \u0433\u043e\u0434\u0443 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u0441\u043b\u0438\u043b\u0430\u0441\u044c \u0441 China Metallurgical Group (MCC), \u000d\u000a\u0441\u043e\u0437\u0434\u0430\u0432 \u043f\u0435\u0440\u0432\u0443\u044e \u0432 \u043c\u0438\u0440\u0435 \u043a\u043e\u0440\u043f\u043e\u0440\u0430\u0446\u0438\u044e \u0441 \u043f\u043e\u043b\u043d\u043e\u0439 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0435\u043d\u043d\u043e\u0439 \u000d\u000a\u0446\u0435\u043f\u043e\u0447\u043a\u043e\u0439 \u2014 \u043e\u0442 \u0433\u0435\u043e\u043b\u043e\u0433\u043e\u0440\u0430\u0437\u0432\u0435\u0434\u043a\u0438 \u0438 \u0438\u043d\u0436\u0438\u043d\u0438\u0440\u0438\u043d\u0433\u0430 \u0434\u043e \u0434\u043e\u0431\u044b\u0447\u0438, \u000d\u000a\u043f\u0435\u0440\u0435\u0440\u0430\u0431\u043e\u0442\u043a\u0438 \u0438 \u043b\u043e\u0433\u0438\u0441\u0442\u0438\u043a\u0438.\u000a\u000d\u000a\u0421\u0435\u0433\u043e\u0434\u043d\u044f Minmetals \u2014 \u0432\u0435\u0440\u0442\u0438\u043a\u0430\u043b\u044c\u043d\u043e \u0438\u043d\u0442\u0435\u0433\u0440\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0439 \u000d\u000a\u0433\u043e\u0441\u0443\u0434\u0430\u0440\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0439 \u0433\u0438\u0433\u0430\u043d\u0442, \u0447\u0435\u0440\u0435\u0437 \u043a\u043e\u0442\u043e\u0440\u044b\u0439 \u041a\u0438\u0442\u0430\u0439 \u0432\u044b\u0441\u0442\u0440\u0430\u0438\u0432\u0430\u0435\u0442 \u000d\u000a\u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044c \u043d\u0430\u0434 \u0441\u0442\u0440\u0430\u0442\u0435\u0433\u0438\u0447\u0435\u0441\u043a\u0438\u043c\u0438 \u043c\u0435\u0442\u0430\u043b\u043b\u0430\u043c\u0438 \u0438 \u0433\u043b\u043e\u0431\u0430\u043b\u044c\u043d\u044b\u043c\u0438 \u000d\u000a\u0446\u0435\u043f\u043e\u0447\u043a\u0430\u043c\u0438 \u043f\u043e\u0441\u0442\u0430\u0432\u043e\u043a.\u000d\u000a\u0421\u0444\u0435\u0440\u0430 \u0434\u0435\u044f\u0442\u0435\u043b\u044c\u043d\u043e\u0441\u0442\u0438 \u0438 \u043f\u043e\u0437\u0438\u0446\u0438\u0438 \u0432 \u043e\u0442\u0440\u0430\u0441\u043b\u0438\u000d\u000a\u0418\u0441\u0442\u043e\u0440\u0438\u044f \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438\u000d\u000a\u041a\u043b\u044e\u0447\u0435\u0432\u044b\u0435 \u043f\u0440\u043e\u0435\u043a\u0442\u044b\u000d\u000a\u041c\u0435\u0434\u043d\u044b\u0439 \u0440\u0443\u0434\u043d\u0438\u043a \u041b\u0430\u0441-\u0411\u0430\u043c\u0431\u0430\u0441 (\u041f\u0435\u0440\u0443) \u2014 \u043a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0430\u044f \u0437\u0430\u0440\u0443\u0431\u0435\u0436\u043d\u0430\u044f \u000d\u000a\u0441\u0434\u0435\u043b\u043a\u0430 \u0432 \u0438\u0441\u0442\u043e\u0440\u0438\u0438 \u043a\u0438\u0442\u0430\u0439\u0441\u043a\u043e\u0439 \u0433\u043e\u0440\u043d\u043e\u0434\u043e\u0431\u044b\u0432\u0430\u044e\u0449\u0435\u0439 \u043e\u0442\u0440\u0430\u0441\u043b\u0438 \u000d\u000a\u0441\u0442\u043e\u0438\u043c\u043e\u0441\u0442\u044c\u044e $10,5 \u043c\u043b\u0440\u0434, \u0437\u0430\u043f\u0430\u0441\u044b \u043c\u0435\u0434\u0438 \u043f\u0440\u0435\u0432\u044b\u0448\u0430\u044e\u0442 20 \u043c\u043b\u043d \u0442\u043e\u043d\u043d, \u000d\u000a\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u043e \u0432 2024 \u0433\u043e\u0434\u0443 \u0434\u043e\u0441\u0442\u0438\u0433\u043b\u043e 323 \u0442\u044b\u0441. \u0442\u043e\u043d\u043d.\u000a\u000d\u000a\u0426\u0438\u043d\u043a\u043e\u0432\u044b\u0439 \u0440\u0443\u0434\u043d\u0438\u043a \u0414\u0443\u0433\u0430\u043b-\u0420\u0438\u0432\u0435\u0440 (\u0410\u0432\u0441\u0442\u0440\u0430\u043b\u0438\u044f).\u000a\u000d\u000a\u041d\u0438\u043a\u0435\u043b\u044c-\u043a\u043e\u0431\u0430\u043b\u044c\u0442\u043e\u0432\u044b\u0439 \u0440\u0443\u0434\u043d\u0438\u043a \u0420\u0430\u043c\u0443 (\u041f\u0430\u043f\u0443\u0430 \u2014 \u041d\u043e\u0432\u0430\u044f \u0413\u0432\u0438\u043d\u0435\u044f) \u000d\u000a\u0441 \u0437\u0430\u043f\u0430\u0441\u0430\u043c\u0438 \u043d\u0438\u043a\u0435\u043b\u044f 2,11 \u043c\u043b\u043d \u0442\u043e\u043d\u043d, 219 \u0442\u044b\u0441. \u0442\u043e\u043d\u043d \u043a\u043e\u0431\u0430\u043b\u044c\u0442\u0430 \u000d\u000a\u0438 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u043e\u043c \u043e\u043a\u043e\u043b\u043e 30 \u0442\u044b\u0441. \u0442\u043e\u043d\u043d \u043d\u0438\u043a\u0435\u043b\u044f \u0438 3 \u0442\u044b\u0441. \u0442\u043e\u043d\u043d \u000d\u000a\u043a\u043e\u0431\u0430\u043b\u044c\u0442\u0430 \u0432 \u0433\u043e\u0434.\u000a\u000d\u000a\u041f\u043e\u043b\u0438\u043c\u0435\u0442\u0430\u043b\u043b\u0438\u0447\u0435\u0441\u043a\u043e\u0435 \u043c\u0435\u0441\u0442\u043e\u0440\u043e\u0436\u0434\u0435\u043d\u0438\u0435 \u0428\u0438\u0447\u0436\u0443\u044e\u0430\u043d\u044c\u2028\u000d\u000a(\u043f\u0440\u043e\u0432\u0438\u043d\u0446\u0438\u044f \u0425\u0443\u043d\u0430\u043d\u044c).\u000a\u000d\u000a\u041a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0435\u0435 \u043c\u0438\u0440\u043e\u0432\u043e\u0435 \u043c\u0435\u0441\u0442\u043e\u0440\u043e\u0436\u0434\u0435\u043d\u0438\u0435 \u0440\u0430\u0441\u0442\u0432\u043e\u0440\u0438\u043c\u044b\u0445 \u0441\u043e\u043b\u0435\u0439 \u000d\u000a\u043a\u0430\u043b\u0438\u044f, \u043c\u0430\u0433\u043d\u0438\u044f \u0438 \u043b\u0438\u0442\u0438\u044f \u2014 \u043e\u0437\u0435\u0440\u043e \u041a\u0430\u0440\u0445\u0430\u043d (\u043f\u0440\u043e\u0432\u0438\u043d\u0446\u0438\u044f \u0426\u0438\u043d\u0445\u0430\u0439). \u000d\u000a\u0414\u043b\u044f \u0435\u0433\u043e \u043e\u0441\u0432\u043e\u0435\u043d\u0438\u044f \u0432 2025 \u0433\u043e\u0434\u0443 \u0441\u043e\u0432\u043c\u0435\u0441\u0442\u043d\u043e \u0441 \u043f\u0440\u0430\u0432\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u043e\u043c \u000d\u000a\u043f\u0440\u043e\u0432\u0438\u043d\u0446\u0438\u0438 \u0426\u0438\u043d\u0445\u0430\u0439 \u0441\u043e\u0437\u0434\u0430\u043d\u0430 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f Qinghai Salt Lake \u000d\u000aIndustry Co., Ltd.\u000a\u000d\u000a\u041c\u0435\u0434\u043d\u044b\u0439 \u0440\u0443\u0434\u043d\u0438\u043a \u0410\u0439\u043d\u0430\u043a, \u0410\u0444\u0433\u0430\u043d\u0438\u0441\u0442\u0430\u043d: \u0437\u0430\u043f\u0430\u0441\u044b \u043c\u0435\u0442\u0430\u043b\u043b\u0438\u0447\u0435\u0441\u043a\u043e\u0439 \u000d\u000a\u043c\u0435\u0434\u0438 11,08 \u043c\u043b\u043d \u0442\u043e\u043d\u043d, \u0434\u043e\u043b\u044f \u2014 75%.\u000a\u000d\u000a\u041c\u0435\u0434\u043d\u043e-\u0437\u043e\u043b\u043e\u0442\u043e\u0439 \u0440\u0443\u0434\u043d\u0438\u043a \u0421\u0430\u0438\u043d\u0434\u0430\u043a, \u041f\u0430\u043a\u0438\u0441\u0442\u0430\u043d: \u0437\u0430\u043f\u0430\u0441\u044b \u000d\u000a\u043c\u0435\u0442\u0430\u043b\u043b\u0438\u0447\u0435\u0441\u043a\u043e\u0439 \u043c\u0435\u0434\u0438 1,84 \u043c\u043b\u043d \u0442\u043e\u043d\u043d, MCC \u0432\u043b\u0430\u0434\u0435\u0435\u0442 50%.\u000a\u000d\u000a\u041c\u0435\u0434\u043d\u044b\u0439 \u0440\u0443\u0434\u043d\u0438\u043a \u0421\u0438\u0430\u0434\u0438\u043a, \u041f\u0430\u043a\u0438\u0441\u0442\u0430\u043d: \u0437\u0430\u043f\u0430\u0441\u044b \u043c\u0435\u0434\u0438 \u000d\u000a\u043f\u0440\u0438\u0431\u043b\u0438\u0437\u0438\u0442\u0435\u043b\u044c\u043d\u043e 3,78 \u043c\u043b\u043d \u0442\u043e\u043d\u043d, MCC \u0432\u043b\u0430\u0434\u0435\u0435\u0442 80%.\u000a\u000d\u000a\u0421\u0432\u0438\u043d\u0446\u043e\u0432\u043e-\u0446\u0438\u043d\u043a\u043e\u0432\u044b\u0439 \u0440\u0443\u0434\u043d\u0438\u043a \u0414\u0443\u0434\u0430 (\u041f\u0430\u043a\u0438\u0441\u0442\u0430\u043d): \u0441\u0432\u0438\u043d\u0435\u0446\u2028\u000d\u000a321,1 \u0442\u044b\u0441. \u0442\u043e\u043d\u043d + \u0446\u0438\u043d\u043a 642,9 \u0442\u044b\u0441. \u0442\u043e\u043d\u043d, \u0434\u043e\u043b\u044f 100%.\u000a\u000d\u000a\u0416\u0435\u043b\u0435\u0437\u043e\u0440\u0443\u0434\u043d\u043e\u0435 \u043c\u0435\u0441\u0442\u043e\u0440\u043e\u0436\u0434\u0435\u043d\u0438\u0435 \u041b\u0430\u043c\u0431\u0435\u0440\u0442 \u041a\u0435\u0439\u043f, \u0410\u0432\u0441\u0442\u0440\u0430\u043b\u0438\u044f: \u000d\u000a\u0440\u0435\u0441\u0443\u0440\u0441\u044b 1,56 \u043c\u043b\u0440\u0434 \u0442\u043e\u043d\u043d, \u0434\u043e\u043b\u044f 50%.\u000a\u000d\u000a\u0416\u0435\u043b\u0435\u0437\u043e\u0440\u0443\u0434\u043d\u043e\u0435 \u043c\u0435\u0441\u0442\u043e\u0440\u043e\u0436\u0434\u0435\u043d\u0438\u0435 \u0413\u0438\u0440\u0430 \u0413\u0440\u0430\u043d\u0434\u0435, \u0410\u0440\u0433\u0435\u043d\u0442\u0438\u043d\u0430: \u000d\u000a\u0437\u0430\u043f\u0430\u0441\u044b 230 \u043c\u043b\u043d \u0442\u043e\u043d\u043d, \u0434\u043e\u043b\u044f 70%.\u000d\u000a\u0421\u0430\u0439\u0442\u000d\u000awww.minmetals.com\u000d\u000a\u0418\u0441\u0442\u043e\u0447\u043d\u0438\u043a: \u043e\u0444\u0438\u0446\u0438\u0430\u043b\u044c\u043d\u044b\u0439 \u0430\u0440\u0445\u0438\u0432 China Minmetals\u000d\u000a\u0428\u0442\u0430\u0431-\u043a\u0432\u0430\u0440\u0442\u0438\u0440\u0430 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438","15/17\u000d\u000a\u041c\u0438\u043d\u0435\u0440\u0430\u043b\u044c\u043d\u0430\u044f \u0431\u0430\u0437\u0430 Minmetals \u043e\u0445\u0432\u0430\u0442\u044b\u0432\u0430\u0435\u0442 \u0431\u043e\u043b\u0435\u0435 70% \u000d\u000a\u0441\u0442\u0440\u0430\u0442\u0435\u0433\u0438\u0447\u0435\u0441\u043a\u0438\u0445 \u043d\u0435\u044d\u043d\u0435\u0440\u0433\u0435\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0445 \u0440\u0435\u0441\u0443\u0440\u0441\u043e\u0432 \u041a\u0438\u0442\u0430\u044f. \u041a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u2014 \u000d\u000a\u043c\u0438\u0440\u043e\u0432\u043e\u0439 \u043b\u0438\u0434\u0435\u0440 \u043f\u043e \u0437\u0430\u043f\u0430\u0441\u0430\u043c \u0432\u043e\u043b\u044c\u0444\u0440\u0430\u043c\u0430, \u043a\u0440\u0438\u0441\u0442\u0430\u043b\u043b\u0438\u0447\u0435\u0441\u043a\u043e\u0433\u043e \u000d\u000a\u0433\u0440\u0430\u0444\u0438\u0442\u0430 \u0438 \u0432\u0438\u0441\u043c\u0443\u0442\u0430. \u0412\u0445\u043e\u0434\u0438\u0442 \u0432 \u0447\u0438\u0441\u043b\u043e \u043a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0438\u0445 \u043f\u043e \u043b\u0438\u0442\u0438\u0435\u0432\u044b\u043c, \u000d\u000a\u043a\u0430\u043b\u0438\u0439\u043d\u044b\u043c, \u0446\u0438\u043d\u043a\u043e\u0432\u044b\u043c, \u0441\u0432\u0438\u043d\u0446\u043e\u0432\u044b\u043c, \u0441\u0443\u0440\u044c\u043c\u044f\u043d\u044b\u043c, \u0445\u0440\u043e\u043c\u043e\u0432\u044b\u043c \u000d\u000a\u0438 \u0444\u0442\u043e\u0440\u0441\u043e\u0434\u0435\u0440\u0436\u0430\u0449\u0438\u043c \u0440\u0435\u0441\u0443\u0440\u0441\u0430\u043c.\u000a\u000d\u000a\u0412 2025 \u0433\u043e\u0434\u0443 \u0434\u0432\u0430 \u0434\u043e\u0447\u0435\u0440\u043d\u0438\u0445 \u043f\u0440\u0435\u0434\u043f\u0440\u0438\u044f\u0442\u0438\u044f \u000d\u000a\u0438  \u0432\u044b\u043f\u0443\u0441\u0442\u0438\u043b\u0438 \u0434\u043e\u043a\u043b\u0430\u0434\u044b \u000d\u000a\u043e \u043c\u0438\u043d\u0435\u0440\u0430\u043b\u044c\u043d\u044b\u0445 \u0440\u0435\u0441\u0443\u0440\u0441\u0430\u0445, \u043f\u043e\u044f\u0441\u043d\u0438\u0432, \u0447\u0442\u043e \u0437\u0430\u043f\u0430\u0441\u044b \u041f\u0418 \u000d\u000a\u043d\u0435\u0434\u043e\u043e\u0446\u0435\u043d\u0435\u043d\u044b \u0440\u044b\u043d\u043a\u043e\u043c, \u0447\u0442\u043e \u0441\u043a\u0430\u0437\u044b\u0432\u0430\u0435\u0442\u0441\u044f \u043d\u0430 \u0438\u0445 \u043a\u0430\u043f\u0438\u0442\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u0438.\u000a\u000d\u000a\u041a\u043b\u044e\u0447\u0435\u0432\u044b\u0435 \u0437\u0430\u0440\u0443\u0431\u0435\u0436\u043d\u044b\u0435 \u0440\u0435\u0441\u0443\u0440\u0441\u044b \u0441\u043e\u0441\u0440\u0435\u0434\u043e\u0442\u043e\u0447\u0435\u043d\u044b \u0433\u043b\u0430\u0432\u043d\u044b\u043c \u000d\u000a\u043e\u0431\u0440\u0430\u0437\u043e\u043c \u043f\u043e\u0434 \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u0435\u043c \u044d\u0442\u0438\u0445 \u0434\u0432\u0443\u0445 \u043f\u0440\u0435\u0434\u043f\u0440\u0438\u044f\u0442\u0438\u0439 \u043a\u043e\u0440\u043f\u043e\u0440\u0430\u0446\u0438\u0438, \u000d\u000a\u0430 \u0442\u0430\u043a\u0436\u0435 \u0440\u044f\u0434\u0430 \u0441\u043e\u0432\u043c\u0435\u0441\u0442\u043d\u044b\u0445 \u043f\u0440\u0435\u0434\u043f\u0440\u0438\u044f\u0442\u0438\u0439.\u000d\u000aMinmetals Resources \u000d\u000aMetallurgical Corporation of China\u000d\u000a\u041c\u0435\u0434\u044c \u2014 60 \u043c\u043b\u043d \u0442\u043e\u043d\u043d (\u043e\u0431\u0449\u0430\u044f \u043e\u0446\u0435\u043d\u043a\u0430, \u0432 \u0442\u043e\u043c \u0447\u0438\u0441\u043b\u0435 \u000d\u000a18,617 \u043c\u043b\u043d \u0442\u043e\u043d\u043d \u0443 , 13,93 \u043c\u043b\u043d \u0442\u043e\u043d\u043d \u000d\u000a\u0443  , \u043e\u0441\u0442\u0430\u043b\u044c\u043d\u044b\u0435 \u0432 \u0431\u043e\u043b\u0435\u0435 \u000d\u000a\u043c\u0435\u043b\u043a\u0438\u0445 \u043f\u043e\u0434\u0440\u0430\u0437\u0434\u0435\u043b\u0435\u043d\u0438\u044f\u0445), \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0435 \u043c\u043e\u0449\u043d\u043e\u0441\u0442\u0438 \u2014 \u000d\u000a1,25 \u043c\u043b\u043d \u0442\u043e\u043d\u043d \u0432 \u0433\u043e\u0434.\u000a\u000d\u000a\u041d\u0438\u043a\u0435\u043b\u044c \u2014 2,8 \u043c\u043b\u043d \u0442\u043e\u043d\u043d, \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u043e \u2014 30 \u0442\u044b\u0441. \u0442\u043e\u043d\u043d \u0432 \u0433\u043e\u0434.\u000a\u000d\u000a\u041a\u043e\u0431\u0430\u043b\u044c\u0442 \u2014 290 \u0442\u044b\u0441. \u0442\u043e\u043d\u043d, \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u043e \u2014 3 \u0442\u044b\u0441. \u0442\u043e\u043d\u043d \u0432 \u0433\u043e\u0434.\u000a\u000d\u000a\u0421\u0432\u0438\u043d\u0435\u0446 \u2014 2,2 \u043c\u043b\u043d \u0442\u043e\u043d\u043d.\u000a\u000d\u000a\u0426\u0438\u043d\u043a \u2014 12,5 \u043c\u043b\u043d \u0442\u043e\u043d\u043d. \u000a\u000d\u000a\u0417\u043e\u043b\u043e\u0442\u043e \u2014 370 \u0442\u043e\u043d\u043d.\u000a\u000d\u000a\u0421\u0435\u0440\u0435\u0431\u0440\u043e \u2014 23,3 \u0442\u044b\u0441. \u0442\u043e\u043d\u043d.\u000a\u000d\u000a\u041c\u043e\u043b\u0438\u0431\u0434\u0435\u043d \u2014 357 \u0442\u044b\u0441. \u0442\u043e\u043d\u043d.\u000a\u000d\u000a\u041e\u043b\u043e\u0432\u043e \u2014 30 \u0442\u044b\u0441. \u0442\u043e\u043d\u043d.\u000a\u000d\u000a\u0421\u043a\u0430\u043d\u0434\u0438\u0439 \u2014 40 \u0442\u044b\u0441. \u0442\u043e\u043d\u043d.\u000a\u000d\u000a\u0421\u0443\u0440\u044c\u043c\u0430 \u2014 300 \u0442\u044b\u0441. \u0442\u043e\u043d\u043d.\u000d\u000aMinmetals Resources\u000d\u000aMetallurgical Corporation of China\u000d\u000a\u0443\u0445\u0443\u0434\u0448\u0435\u043d\u0438\u0435 \u043a\u043e\u043d\u044a\u044e\u043d\u043a\u0442\u0443\u0440\u044b \u0441\u044b\u0440\u044c\u0435\u0432\u044b\u0445 \u0440\u044b\u043d\u043a\u043e\u0432 \u0438 \u043f\u0430\u0434\u0435\u043d\u0438\u0435 \u043c\u0430\u0440\u0436\u0438 \u000d\u000a\u0432 \u0442\u043e\u0440\u0433\u043e\u0432\u043b\u0435 \u0441\u044b\u0440\u044c\u0435\u043c;\u000a\u000d\u000a\u0441\u043d\u0438\u0436\u0435\u043d\u0438\u0435 \u0432\u044b\u0440\u0443\u0447\u043a\u0438 Minmetals Development \u043d\u0430 14,89%\u2028\u000d\u000a\u0438\u0437-\u0437\u0430 \u0441\u0442\u0430\u0433\u043d\u0430\u0446\u0438\u0438 \u0441\u0442\u0430\u043b\u0435\u043b\u0438\u0442\u0435\u0439\u043d\u043e\u0439 \u043e\u0442\u0440\u0430\u0441\u043b\u0438;\u000a\u000d\u000a\u043f\u0430\u0434\u0435\u043d\u0438\u0435 \u0432\u044b\u0440\u0443\u0447\u043a\u0438 Minmetals Capital \u043d\u0430 19,68% \u0438 \u0441\u043d\u0438\u0436\u0435\u043d\u0438\u0435 \u000d\u000a\u0447\u0438\u0441\u0442\u043e\u0439 \u043f\u0440\u0438\u0431\u044b\u043b\u0438 \u043d\u0430 78,08% \u2014 \u043d\u0430 \u0444\u043e\u043d\u0435 \u0442\u0440\u0430\u043d\u0441\u0444\u043e\u0440\u043c\u0430\u0446\u0438\u0438 \u000d\u000a\u0442\u0440\u0430\u0441\u0442\u043e\u0432\u043e\u0433\u043e \u0431\u0438\u0437\u043d\u0435\u0441\u0430 \u0438 \u043f\u0435\u0440\u0435\u043e\u0446\u0435\u043d\u043a\u0438 \u0444\u0438\u043d\u0430\u043d\u0441\u043e\u0432\u044b\u0445 \u0430\u043a\u0442\u0438\u0432\u043e\u0432;\u000a\u000d\u000a\u0443\u0431\u044b\u0442\u043e\u043a Minmetals New Energy \u0432 \u0440\u0430\u0437\u043c\u0435\u0440\u0435 $63,5 \u043c\u043b\u0440\u0434 \u000d\u000a\u0432\u0441\u043b\u0435\u0434\u0441\u0442\u0432\u0438\u0435 \u043f\u0430\u0434\u0435\u043d\u0438\u044f \u0446\u0435\u043d \u043d\u0430 \u043a\u0430\u0442\u043e\u0434\u043d\u044b\u0435 \u043c\u0430\u0442\u0435\u0440\u0438\u0430\u043b\u044b \u000d\u000a\u0438 \u043d\u0435\u0434\u043e\u0441\u0442\u0430\u0442\u043e\u0447\u043d\u043e\u0439 \u0437\u0430\u0433\u0440\u0443\u0437\u043a\u0438 \u043c\u043e\u0449\u043d\u043e\u0441\u0442\u0435\u0439;\u000a\u000d\u000a\u0434\u0430\u0432\u043b\u0435\u043d\u0438\u0435 \u043d\u0430 \u0440\u044b\u043d\u043e\u043a \u043d\u0435\u0434\u0432\u0438\u0436\u0438\u043c\u043e\u0441\u0442\u0438 \u0443\u0445\u0443\u0434\u0448\u0438\u043b\u043e \u043f\u043e\u043a\u0430\u0437\u0430\u0442\u0435\u043b\u0438 \u000d\u000aMinmetals Land, \u043a\u0440\u0443\u043f\u043d\u043e\u0439 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438 \u0432 \u044d\u0442\u043e\u0439 \u0441\u0444\u0435\u0440\u0435, \u0438\u0433\u0440\u0430\u044e\u0449\u0435\u0439 \u000d\u000a\u0431\u043e\u043b\u044c\u0448\u0443\u044e \u0440\u043e\u043b\u044c \u0432 \u043c\u0430\u0441\u0448\u0442\u0430\u0431\u0430\u0445 \u0433\u0440\u0443\u043f\u043f\u044b.\u000d\u000a2024 \u0433\u043e\u0434 \u043e\u043a\u0430\u0437\u0430\u043b\u0441\u044f \u0434\u043b\u044f China Minmetals \u0437\u0430\u043c\u0435\u0442\u043d\u043e \u0441\u043b\u0430\u0431\u0435\u0435 \u000d\u000a\u043f\u0440\u0435\u0434\u044b\u0434\u0443\u0449\u0435\u0433\u043e. \u0412\u044b\u0440\u0443\u0447\u043a\u0430 \u0441\u043e\u043a\u0440\u0430\u0442\u0438\u043b\u0430\u0441\u044c \u0441 $132 \u043c\u043b\u0440\u0434 \u0434\u043e $116 \u043c\u043b\u0440\u0434.\u000a\u000d\u000a\u041e\u0441\u043d\u043e\u0432\u043d\u044b\u0435 \u043f\u0440\u0438\u0447\u0438\u043d\u044b:\u000d\u000a\u0421\u043e\u0432\u043e\u043a\u0443\u043f\u043d\u044b\u0435 \u0430\u043a\u0442\u0438\u0432\u044b \u043d\u0430 \u043a\u043e\u043d\u0435\u0446 2024 \u0433\u043e\u0434\u0430 \u043f\u0440\u0435\u0432\u044b\u0441\u0438\u043b\u0438 $181 \u043c\u043b\u0440\u0434.\u000a\u000d\u000a\u041e\u043f\u0435\u0440\u0430\u0446\u0438\u043e\u043d\u043d\u0430\u044f \u0432\u044b\u0440\u0443\u0447\u043a\u0430 \u2014 $116 \u043c\u043b\u0440\u0434.\u000d\u000a\u0424\u0438\u043d\u0430\u043d\u0441\u043e\u0432\u044b\u0435 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u044b\u000d\u000aChina Minmetals Corporation (\u4e2d\u56fd\u4e94\u77ff\u96c6\u56e2\u516c\u53f8)\u000d\u000a\u0420\u0435\u0441\u0443\u0440\u0441\u043d\u0430\u044f \u0431\u0430\u0437\u0430 \u0438 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0435\u2028\u000d\u000a\u043c\u043e\u0449\u043d\u043e\u0441\u0442\u0438\u000d\u000a\u041f\u0440\u043e\u0431\u043b\u0435\u043c\u044b \u0438 \u0432\u044b\u0437\u043e\u0432\u044b\u000d\u000a\u0418\u0441\u0442\u043e\u0447\u043d\u0438\u043a: \u043e\u0444\u0438\u0446\u0438\u0430\u043b\u044c\u043d\u044b\u0439 \u043e\u0442\u0447\u0435\u0442 Minmetals\u000d\u000a\u0428\u0442\u0430\u0431-\u043a\u0432\u0430\u0440\u0442\u0438\u0440\u0430 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438","16/17\u000d\u000a\u0427\u0435\u0442\u044b\u0440\u0435 \u0438\u0437 \u0441\u0435\u043c\u0438 \u043f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u043b\u0435\u043d\u043d\u044b\u0445 \u0432 \u0434\u0430\u0439\u0434\u0436\u0435\u0441\u0442\u0435\u2028\u000d\u000a\u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0439 \u0432\u0445\u043e\u0434\u044f\u0442 \u0432 Fortune Global 500\u000d\u000a\u041a\u043b\u044e\u0447\u0435\u0432\u044b\u0435 \u0437\u0430\u0440\u0443\u0431\u0435\u0436\u043d\u044b\u0435 \u043f\u0440\u043e\u0435\u043a\u0442\u044b\u2028\u000d\u000a\u043a\u0438\u0442\u0430\u0439\u0441\u043a\u0438\u0445 \u043c\u0435\u0442\u0430\u043b\u043b\u0443\u0440\u0433\u043e\u0432\u000d\u000aFortune 500\u000a\u000d\u000aGlobal* 2025\u000d\u000aFortune Global 500 \u2014 \u0435\u0436\u0435\u0433\u043e\u0434\u043d\u044b\u0439 \u000d\u000a\u0440\u0435\u0439\u0442\u0438\u043d\u0433 500 \u043a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0438\u0445 \u043c\u0438\u0440\u043e\u0432\u044b\u0445 \u000d\u000a\u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0439, \u0441\u043e\u0441\u0442\u0430\u0432\u043b\u044f\u0435\u043c\u044b\u0439 \u0436\u0443\u0440\u043d\u0430\u043b\u043e\u043c \u000d\u000aFortune \u043d\u0430 \u043e\u0441\u043d\u043e\u0432\u0435 \u0438\u0445 \u0432\u044b\u0440\u0443\u0447\u043a\u0438\u000d\u000a\u0412\u044b\u0440\u0443\u0447\u043a\u0430\u2028\u000d\u000a2025 \u0433\u043e\u0434\u0430 \u000d\u000a$115,8 \u043c\u043b\u0440\u0434 \u0412\u044b\u0440\u0443\u0447\u043a\u0430\u2028\u000d\u000a2025 \u0433\u043e\u0434\u0430 \u000d\u000a$77,7 \u043c\u043b\u0440\u0434\u000d\u000a\u0412\u044b\u0440\u0443\u0447\u043a\u0430 \u000d\u000a2025 \u0433\u043e\u0434\u0430 \u000d\u000a$56,6 \u043c\u043b\u0440\u0434\u000d\u000a\u0412\u044b\u0440\u0443\u0447\u043a\u0430 \u000d\u000a2025 \u0433\u043e\u0434\u0430 \u000d\u000a$58,9 \u043c\u043b\u0440\u0434\u000d\u000aChina \u000d\u000aMinmetals \u000d\u000aCorporation Jiangxi \u000d\u000aCopper \u000d\u000aCorporation\u000d\u000aTsingshan \u000d\u000aHolding \u000d\u000aGroup Co.\u000d\u000aJinchuan \u000d\u000aGroup Co.\u000d\u000a#86\u000d\u000a#165 #265\u000d\u000a#235\u000d\u000aJiangxi Copper\u000d\u000a18,61% First Quantum Minerals \u000d\u000a(\u041a\u0430\u043d\u0430\u0434\u0430), \u0432\u043a\u043b\u044e\u0447\u0430\u044f \u043c\u0435\u0434\u043d\u044b\u0439 \u000d\u000a\u0440\u0443\u0434\u043d\u0438\u043a \u041a\u043e\u0431\u0440\u0435 \u041f\u0430\u043d\u0430\u043c\u0430\u000d\u000aJinchuan \u000d\u000a\u041c\u0435\u0434\u043d\u044b\u0439 \u0440\u0443\u0434\u043d\u0438\u043a \u0411\u0430\u0443\u044d\u0440\u0430\u0447\u0438 \u000d\u000a(\u041c\u0435\u043a\u0441\u0438\u043a\u0430)\u000d\u000d\u000aTongling\u000d\u000a\u041c\u0435\u0434\u043d\u044b\u0439 \u0440\u0443\u0434\u043d\u0438\u043a \u041c\u0438\u0440\u0430\u0434\u043e\u0440 (\u042d\u043a\u0432\u0430\u0434\u043e\u0440)\u000d\u000aJiangxi Copper\u000d\u000a12,9% SolGold, \u0432\u043b\u0430\u0434\u0435\u044e\u0449\u0435\u0439 \u043c\u0435\u0434\u043d\u044b\u043c \u000d\u000a\u043c\u0435\u0441\u0442\u043e\u0440\u043e\u0436\u0434\u0435\u043d\u0438\u0435\u043c \u041a\u0430\u0441\u043a\u0430\u0431\u0435\u043b\u044c \u000d\u000a(\u042d\u043a\u0432\u0430\u0434\u043e\u0440)\u000d\u000aJiangxi Copper\u000d\u000a22,5% \u043c\u0435\u0434\u043d\u043e\u0433\u043e \u0440\u0443\u0434\u043d\u0438\u043a\u0430\u000a\u000d\u000a\u041b\u0430\u0441-\u0411\u0430\u043c\u0431\u0430\u0441 (\u041f\u0435\u0440\u0443)\u000d\u000aChina Minmetals \u000d\u000a\u041c\u0435\u0434\u043d\u044b\u0439 \u0440\u0443\u0434\u043d\u0438\u043a \u041b\u0430\u0441-\u0411\u0430\u043c\u0431\u0430\u0441 (\u041f\u0435\u0440\u0443)\u000d\u000aChina Minmetals \u000d\u000a\u0416\u0435\u043b\u0435\u0437\u043e\u0440\u0443\u0434\u043d\u043e\u0435 \u043c\u0435\u0441\u0442\u043e\u0440\u043e\u0436\u0434\u0435\u043d\u0438\u0435 \u000d\u000a\u0413\u0438\u0440\u0430 \u0413\u0440\u0430\u043d\u0434\u0435 (\u0410\u0440\u0433\u0435\u043d\u0442\u0438\u043d\u0430) \u000d\u000aJinchuan \u000d\u000a\u041d\u0438\u043a\u0435\u043b\u0435\u0432\u044b\u0439 \u0440\u0443\u0434\u043d\u0438\u043a \u041c\u0443\u043d\u0430\u043b\u0438 (\u0417\u0430\u043c\u0431\u0438\u044f)\u000d\u000aJinchuan \u000d\u000a\u041f\u043b\u0430\u0442\u0438\u043d\u043e\u0432\u044b\u0439 \u0440\u0443\u0434\u043d\u0438\u043a \u0411\u0430\u043a\u0443\u0431\u0443\u043d\u0433 (\u042e\u0410\u0420)\u000d\u000aJinchuan \u000d\u000a\u041c\u0435\u0434\u043d\u043e \u043a\u043e\u0431\u0430\u043b\u044c\u0442\u043e\u0432\u044b\u0439 \u0440\u0443\u0434\u043d\u0438\u043a\u2028\u000d\u000a\u0420\u0443\u0432\u0430\u0441\u0438 (\u0414\u0420 \u041a\u043e\u043d\u0433\u043e)\u000d\u000aJinchuan \u000d\u000a\u041f\u0440\u043e\u0435\u043a\u0442 \u0433\u043b\u0443\u0431\u043e\u043a\u043e\u0439 \u043f\u0435\u0440\u0435\u0440\u0430\u0431\u043e\u0442\u043a\u0438 \u000d\u000a\u041c\u0443\u0441\u043e\u043d\u043e\u0439 (\u0414\u0420 \u041a\u043e\u043d\u0433\u043e)\u000d\u000aJiangxi Copper\u000d\u000a100% \u043c\u0435\u0434\u043d\u043e\u0433\u043e \u0440\u0443\u0434\u043d\u0438\u043a\u0430\u2028\u000d\u000a\u041a\u0438\u043d\u0441\u0435\u0432\u0435\u0440\u0435 (\u0414\u0420 \u041a\u043e\u043d\u0433\u043e)\u000d\u000aChina Minmetals \u000d\u000a\u041c\u0435\u0434\u043d\u044b\u0439 \u0440\u0443\u0434\u043d\u0438\u043a \u0410\u0439\u043d\u0430\u043a (\u0410\u0444\u0433\u0430\u043d\u0438\u0441\u0442\u0430\u043d)\u000d\u000aChina Minmetals \u000d\u000a\u0421\u0432\u0438\u043d\u0446\u043e\u0432\u043e \u0446\u0438\u043d\u043a\u043e\u0432\u044b\u0439 \u0440\u0443\u0434\u043d\u0438\u043a\u2028\u000d\u000a\u0414\u0443\u0434\u0430 (\u041f\u0430\u043a\u0438\u0441\u0442\u0430\u043d) \u000d\u000aChina Minmetals \u000d\u000a\u041c\u0435\u0434\u043d\u043e-\u0437\u043e\u043b\u043e\u0442\u043e\u0439 \u0440\u0443\u0434\u043d\u0438\u043a \u0421\u0438\u0430\u0434\u0438\u043a \u000d\u000a(\u041f\u0430\u043a\u0438\u0441\u0442\u0430\u043d) \u000d\u000aChina Minmetals \u000d\u000a\u041c\u0435\u0434\u043d\u043e-\u0437\u043e\u043b\u043e\u0442\u043e\u0439 \u0440\u0443\u0434\u043d\u0438\u043a \u0421\u0430\u0438\u043d\u0434\u0430\u043a \u000d\u000a(\u041f\u0430\u043a\u0438\u0441\u0442\u0430\u043d) \u000d\u000aJiangxi Copper\u000d\u000a25% \u043c\u0435\u0434\u043d\u043e\u0433\u043e \u0440\u0443\u0434\u043d\u0438\u043a\u0430 \u0410\u0439\u043d\u0430\u043a \u000d\u000a(\u0410\u0444\u0433\u0430\u043d\u0438\u0441\u0442\u0430\u043d)\u000d\u000aJinchuan \u000d\u000a\u041d\u0438\u043a\u0435\u043b\u0435\u0432\u043e\u0435 \u043c\u0435\u0441\u0442\u043e\u0440\u043e\u0436\u0434\u0435\u043d\u0438\u0435 \u000d\u000a\u0412\u0430\u043d\u0438\u0430\u0442\u0430\u0440\u0430 \u041f\u0435\u0440\u0441\u0430\u0434\u0430 (\u0418\u043d\u0434\u043e\u043d\u0435\u0437\u0438\u044f)\u000d\u000aTsingshan\u000d\u000a\u041a\u043b\u0430\u0441\u0442\u0435\u0440\u044b \u043f\u043e \u0434\u043e\u0431\u044b\u0447\u0435 \u0438 \u043f\u0435\u0440\u0435\u0440\u0430\u0431\u043e\u0442\u043a\u0435 \u000d\u000a\u043d\u0438\u043a\u0435\u043b\u044f \u041c\u043e\u0440\u043e\u0432\u0430\u043b\u0438 \u0438 \u0412\u0435\u0434\u0430 \u0411\u044d\u0439 \u000d\u000a(\u0418\u043d\u0434\u043e\u043d\u0435\u0437\u0438\u044f)\u000d\u000aChina Minmetals \u000d\u000a\u041d\u0438\u043a\u0435\u043b\u044c-\u043a\u043e\u0431\u0430\u043b\u044c\u0442\u043e\u0432\u044b\u0439 \u0440\u0443\u0434\u043d\u0438\u043a \u0420\u0430\u043c\u0443 \u000d\u000a(\u041f\u0430\u043f\u0443\u0430 \u2014 \u041d\u043e\u0432\u0430\u044f \u0413\u0432\u0438\u043d\u0435\u044f) \u000d\u000aChina Minmetals \u000d\u000a\u0426\u0438\u043d\u043a\u043e\u0432\u044b\u0439 \u0440\u0443\u0434\u043d\u0438\u043a \u0414\u0443\u0433\u0430\u043b-\u0420\u0438\u0432\u0435\u0440 \u000d\u000a(\u0410\u0432\u0441\u0442\u0440\u0430\u043b\u0438\u044f)\u000d\u000aChina Minmetals \u000d\u000a\u0416\u0435\u043b\u0435\u0437\u043e\u0440\u0443\u0434\u043d\u043e\u0435 \u043c\u0435\u0441\u0442\u043e\u0440\u043e\u0436\u0434\u0435\u043d\u0438\u0435 \u000d\u000a\u041b\u0430\u043c\u0431\u0435\u0440\u0442 \u041a\u0435\u0439\u043f (\u0410\u0432\u0441\u0442\u0440\u0430\u043b\u0438\u044f) \u000d\u000a\u0412\u044b\u0432\u043e\u0434\u044b","\u041a\u043e\u043c\u043f\u0430\u043d\u0438\u0438 \u0446\u0432\u0435\u0442\u043d\u043e\u0439 \u043c\u0435\u0442\u0430\u043b\u043b\u0443\u0440\u0433\u0438\u0438 \u041a\u041d\u0420 \u0432\u044b\u0436\u0438\u0432\u0430\u044e\u0442 \u000d\u000a\u0432 \u0443\u0441\u043b\u043e\u0432\u0438\u044f\u0445 \u0436\u0435\u0441\u0442\u043a\u043e\u0439 \u043a\u043e\u043d\u043a\u0443\u0440\u0435\u043d\u0446\u0438\u0438, \u0438\u043d\u043e\u0433\u0434\u0430 \u000d\u000a\u0432\u044b\u043d\u0443\u0436\u0434\u0430\u044e\u0449\u0435\u0439 \u0438\u0445 \u0440\u0430\u0431\u043e\u0442\u0430\u0442\u044c \u043d\u0430 \u0433\u0440\u0430\u043d\u0438 \u0440\u0435\u043d\u0442\u0430\u0431\u0435\u043b\u044c\u043d\u043e\u0441\u0442\u0438.\u000d\u000a\u0414\u043b\u044f \u0442\u043e\u0433\u043e \u0447\u0442\u043e\u0431\u044b \u0432\u044b\u0436\u0438\u0442\u044c, \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f\u043c \u043f\u0440\u0438\u0445\u043e\u0434\u0438\u0442\u0441\u044f \u000d\u000a\u0440\u0430\u0437\u0432\u0438\u0432\u0430\u0442\u044c \u0438\u043d\u043d\u043e\u0432\u0430\u0446\u0438\u043e\u043d\u043d\u044b\u0435 \u0442\u0435\u0445\u043d\u043e\u043b\u043e\u0433\u0438\u0438 \u0438 \u0441\u043e\u0432\u0440\u0435\u043c\u0435\u043d\u043d\u044b\u0435 \u000d\u000a\u043c\u0435\u0442\u043e\u0434\u044b \u043e\u0440\u0433\u0430\u043d\u0438\u0437\u0430\u0446\u0438\u0438 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0430, \u043d\u0430\u043f\u0440\u0438\u043c\u0435\u0440 \u000d\u000a\u043f\u0440\u043e\u043c\u044b\u0448\u043b\u0435\u043d\u043d\u044b\u0435 \u043f\u0430\u0440\u043a\u0438.\u000d\u000a\u0427\u0440\u0435\u0437\u043c\u0435\u0440\u043d\u0430\u044f \u0434\u0438\u0432\u0435\u0440\u0441\u0438\u0444\u0438\u043a\u0430\u0446\u0438\u044f \u0434\u043b\u044f \u0431\u043e\u043b\u044c\u0448\u043e\u0439 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438 \u000d\u000a\u043e\u043f\u0430\u0441\u043d\u0430 \u0442\u0435\u043c, \u0447\u0442\u043e \u043d\u043e\u0432\u044b\u0435 \u043e\u0442\u0440\u0430\u0441\u043b\u0438 \u043c\u043e\u0433\u0443\u0442 \u043d\u0435 \u043f\u043e\u0434\u0434\u0435\u0440\u0436\u0430\u0442\u044c \u000d\u000a\u0442\u0440\u0430\u0434\u0438\u0446\u0438\u043e\u043d\u043d\u044b\u0435, \u0430 \u043d\u0430\u043e\u0431\u043e\u0440\u043e\u0442, \u0438\u0441\u043f\u043e\u0440\u0442\u0438\u0442\u044c \u0441\u043e\u0432\u043e\u043a\u0443\u043f\u043d\u044b\u0439 \u000d\u000a\u0444\u0438\u043d\u0430\u043d\u0441\u043e\u0432\u044b\u0439 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442. \u000d\u000a\u0411\u043e\u0440\u044c\u0431\u0430 \u0437\u0430 \u0437\u0430\u043f\u0430\u0441\u044b \u043f\u043e\u043b\u0435\u0437\u043d\u044b\u0445 \u0438\u0441\u043a\u043e\u043f\u0430\u0435\u043c\u044b\u0445, \u000d\u000a\u0438\u0441\u0442\u043e\u0449\u0430\u044e\u0449\u0438\u0445\u0441\u044f \u043d\u0430 \u0442\u0435\u0440\u0440\u0438\u0442\u043e\u0440\u0438\u0438 \u041a\u0438\u0442\u0430\u044f, \u043f\u0435\u0440\u0435\u0448\u043b\u0430 \u000d\u000a\u0432 \u043c\u0435\u0436\u0434\u0443\u043d\u0430\u0440\u043e\u0434\u043d\u0443\u044e \u0444\u0430\u0437\u0443.\u000d\u000a\u0423 \u0440\u044b\u043d\u043a\u0430 \u043f\u043e\u0441\u0442\u043e\u044f\u043d\u043d\u043e \u043f\u043e\u044f\u0432\u043b\u044f\u044e\u0442\u0441\u044f \u043d\u043e\u0432\u044b\u0435 \u0437\u0430\u043f\u0440\u043e\u0441\u044b \u000d\u000a\u043a \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u0442\u0435\u043b\u044f\u043c \u2014 \u0438\u0437-\u0437\u0430 \u0440\u0430\u0437\u0432\u0438\u0442\u0438\u044f \u0442\u0430\u043a\u0438\u0445 \u043e\u0442\u0440\u0430\u0441\u043b\u0435\u0439, \u000d\u000a\u043a\u0430\u043a \u043d\u043e\u0432\u0430\u044f \u044d\u043d\u0435\u0440\u0433\u0435\u0442\u0438\u043a\u0430 \u0438 \u044d\u043b\u0435\u043a\u0442\u0440\u043e\u043d\u0438\u043a\u0430. \u041c\u0435\u0442\u0430\u043b\u043b\u0443\u0440\u0433\u0430\u043c \u000d\u000a\u043f\u0440\u0438\u0445\u043e\u0434\u0438\u0442\u0441\u044f \u043e\u0441\u0432\u0430\u0438\u0432\u0430\u0442\u044c \u043e\u0447\u0435\u0440\u0435\u0434\u043d\u044b\u0435 \u0432\u0438\u0434\u044b \u043f\u0440\u043e\u0434\u0443\u043a\u0446\u0438\u0438 \u000d\u000a(\u0441\u0432\u0435\u0440\u0445\u0442\u043e\u043d\u043a\u0430\u044f \u043c\u0435\u0434\u043d\u0430\u044f \u0444\u043e\u043b\u044c\u0433\u0430, \u043d\u0438\u043a\u0435\u043b\u0435\u0432\u044b\u0435 \u043f\u0440\u0435\u043a\u0443\u0440\u0441\u043e\u0440\u044b \u000d\u000a\u0434\u043b\u044f \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0430 \u0430\u043a\u043a\u0443\u043c\u0443\u043b\u044f\u0442\u043e\u0440\u043e\u0432 \u0438 \u0442. \u0434.)\u000d\u000a\u041a\u0438\u0442\u0430\u0439\u0441\u043a\u0438\u0435 \u043c\u0435\u0442\u0430\u043b\u043b\u0443\u0440\u0433\u0438\u0447\u0435\u0441\u043a\u0438\u0435 \u043a\u043e\u0440\u043f\u043e\u0440\u0430\u0446\u0438\u0438 \u043f\u0440\u043e\u0434\u043e\u043b\u0436\u0430\u044e\u0442 \u000d\u000a\u0437\u0430\u043d\u0438\u043c\u0430\u0442\u044c \u043c\u0435\u0441\u0442\u043e \u0432 \u0433\u043b\u043e\u0431\u0430\u043b\u044c\u043d\u043e\u043c \u0440\u0435\u0439\u0442\u0438\u043d\u0433\u0435 Fortune 500, \u000d\u000a\u043a\u0443\u0434\u0430 \u0432\u0445\u043e\u0434\u044f\u0442 \u043a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0438\u0435 \u0432 \u043c\u0438\u0440\u0435 \u043f\u043e \u043e\u0431\u044a\u0435\u043c\u0443 \u0432\u044b\u0440\u0443\u0447\u043a\u0438 \u000d\u000a\u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438.\u000d\u000a\u0413\u043e\u0441\u0443\u0434\u0430\u0440\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u043c \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f\u043c \u043f\u0440\u043e\u0449\u0435 \u0432\u0441\u0442\u0440\u043e\u0438\u0442\u044c\u0441\u044f \u000d\u000a\u0432 \u0446\u0435\u043f\u043e\u0447\u043a\u0438 \u043f\u043e\u0441\u0442\u0430\u0432\u043e\u043a. \u041e\u0434\u043d\u0430\u043a\u043e \u0432 \u0447\u0438\u0441\u043b\u0435 \u043c\u0435\u0442\u0430\u043b\u043b\u0443\u0440\u0433\u0438\u0447\u0435\u0441\u043a\u0438\u0445 \u000d\u000a\u0433\u0438\u0433\u0430\u043d\u0442\u043e\u0432 \u041a\u0438\u0442\u0430\u044f \u0435\u0441\u0442\u044c \u0438 \u0447\u0430\u0441\u0442\u043d\u044b\u0435 \u043f\u0440\u0435\u0434\u043f\u0440\u0438\u044f\u0442\u0438\u044f, \u0432\u044b\u0440\u043e\u0441\u0448\u0438\u0435 \u000d\u000a\u0441 \u043d\u0443\u043b\u044f.\u000d\u000a1\u000d\u000a2\u000d\u000a3\u000d\u000a4\u000d\u000a5\u000d\u000a6\u000d\u000a7\u000d\u000a\u0412\u044b\u0432\u043e\u0434\u044b\u000d\u000a17/17"]